window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["34863179"]={"book":{"id":34863179,"title":"好好思考","author":"成甲","translator":"","publisher":"北京联合出版有限公司","pubdate":"2019-10","isbn":"9787559637390","tags":["思维模型","思维","学习方法","个人成长","终身学习","自我管理","成甲","成长"],"memCount":null},"np":1,"pb":[14],"idx":[{"i":19926,"t":"如何能成事或者学什么会什么？","l":"TF1-1","c":"月巧","g":1,"p":1},{"i":19854,"t":"三问辨模型！信息爆炸下的思维模型识别术","l":"TF3-1","c":"kkk-cq","g":1,"p":1},{"i":19714,"t":"追问有效策略背后的原理","l":"TF2-1","c":"林子呀","g":1,"p":1},{"i":17118,"t":"NLP思维逻辑层次模型","l":"TF3-2","c":"嘿，Lydia你来了","g":1,"p":1},{"i":14872,"t":"关键词读书法","l":"TF2-2","c":"石研","g":1,"p":1},{"i":14677,"t":"五星笔记法","l":"TF2-1","c":"石研","g":1,"p":1},{"i":13828,"t":"还不会记笔记？一个方法帮你摆脱无效笔记","l":"TF1-1","c":"小金在路上","g":1,"p":1},{"i":13282,"t":"寻找“贵人”四步法","l":"TF1-1","c":"Luna0511","g":1,"p":1},{"i":12788,"t":"提炼思维模型","l":"TF2-4","c":"徐徐","g":1,"p":1},{"i":12547,"t":"放下阅读快感，用“不读书法”读书","l":"TF2-3","c":"粉黑天空","g":1,"p":1},{"i":12450,"t":"“超一流”学习法","l":"TF2-2","c":"梅花Muses","g":1,"p":1},{"i":11849,"t":"如何练就高超学习力","l":"TF1-1","c":"大源","g":1,"p":1},{"i":9822,"t":"能够挖掘出核心知识的五星笔记法","l":"TF1-2","c":"李慢慢","g":1,"p":1},{"i":9670,"t":"思维模型——培养深度思考的利器","l":"TF3-3","c":"草莓大人","g":1,"p":1}],"ms":[{"id":19926,"topic":"如何能成事或者学什么会什么？","learn_goal":"","remark":"拆书主题：如何能成事或者学什么会什么？\n拆书介绍：好好思考，并且行动起来，学会成事的方法，不再让书本知识停留于纸面。\n","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"月巧","city":"深圳市"},"club":{"name":"深圳桃李分舵","city":"深圳"},"prologue":"\u003cp>&lt;自我介绍&gt;\u003c/p>\u003cp> 大家好，我是今晚的拆书家王月巧。我用三个便签作一下自我介绍：第一个标签，我是一名律师，律师行业从业15年，做过一些重大要案，为很多客户挽回经济损失，也曾为农民工成功讨薪，当然执业之初也办砸过一些案件；第二个标签，我也是一女一儿两个孩子的妈妈；第三个标签，我是一名人生体验派的践行者，在多个城市居住生活过，喜欢运动、读书写作、旅行。所以常年会规律运动，跑过半程马拉松、全程马拉松，也跑过垂直马拉松，喜欢户外徒步旅行，也喜欢自驾旅行，自驾过西走廊、海南、新疆以及有名的独库公路等；公众号发表原创文章900篇以上。\u003c/p>\u003cp>&lt;拆书帮介绍&gt;\u003c/p>\u003cp> 第一次参加拆书帮的小伙伴可能会很好奇：啥是拆书？拆书帮又是一个什么鬼？不会又是什么打着学习的幌子收割我们，把我们当韭菜的机构？今天做分享的拆书家又是什么样的人？接下来我一一为大家解答这些问题，因为我当初也有同样的一连串问号。\u003c/p>\u003cp>What （什么是拆书，什么是拆书帮，什么是拆书家）\u003c/p>\u003cp>拆书，大家不要从字面意思去理解，以为是把书撕了或者拆散了，实际上拆书是一种学习方法，不再以书为中心，而是以学习者为中心。\u003c/p>\u003cp>拆书帮是一个非营利性的公益自组织，所以大家大可放心---我们不会被收割，相反在这个组织里，大家会在师傅和伙伴的无私帮助下更快更好的成长。拆书家则是通过RIA便签训练法把看过的书讲出来，不仅自己会用还教会别人把知识应用起来，通过三级九拆不断打磨自己对知识的提取、思考、内化、讲述、应用能力，从而实现达己助人的效果。\u003c/p>\u003cp>Why为什么要拆书？\u003c/p>\u003cp>爱看书学习的我们想必都有相同或者类似的经历，从最初的爱买书并束之高阁，压根看不了几页或者看不完，到后面能够静下心来看书，而且看了不少，但是却总感觉看的时候很激动，但是没几天热情褪去，生活工作还是老样子，没有达到期望的效果，结果开始不停怀疑读书的意义和方法。\u003c/p>\u003cp>怀疑就对了，来拆书帮是我也是各位做出的非常正确的选择，拆书主要是为了解决成年人学习最主要的问题。拆书帮创始人、帮主赵周老师在《这样读书就够了》这本书中，首次提出了“拆书”这个概念，强调甚至你不一定要把一本书读完，关键是要能将书中知识“拆为已用”，真正达到“学以致用”。所以，大家想解决以前的痛点，只要在拆书帮按照已经非常体系化的方法，学习照做，一级级过级通关，不断打磨自己对知识的提取、思考、内化、讲述、应用能力，最终会越来越喜欢读书学习的自己。 \u003c/p>\u003cp>How如何拆书呢？\u003c/p>\u003cp>拆书可以分为个人拆书和集体拆书。个人拆书学习主要通过RIA便签训练法来训练应用，待会儿我会进一步给大家示范。而集体拆书则是拆书家将一本书加工成一场现场教学，促进更多人把知识拆为己用，以达到参加同主题培训的效果。\u003c/p>","ratings_count":1,"texts":[{"id":24367,"quote":"\u003cp>R原文片段：\u003c/p>\u003cp>\u003cstrong>重复实践：\u003cu>从小事入手，积小胜为大胜。\u003c/u>重复，是熟练掌握的核心。——查理·芒格\u003c/strong>\u003c/p>\u003cp>\u003cstrong>为什么新手花费大量时间也分析不出来的问题，专家能瞬间给出答案？关键在于，专家通过大量重复练习，已将许多复杂的思考过程内化为一种能够瞬间启动的直觉。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学过开车的人都有类似的经历：初学阶段，既要观察路面，又要注视后视镜，还要兼顾换挡、刹车和油门等操作，整个人精神高度紧张。如果此时有人和你说话，你甚至会烦躁地喊“别跟我说话，影响我开车！”然而一旦驾驶技术熟练后，你不仅能边开车边和别人聊天，还可以同时听新闻、看导航。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>表3-1 思维模型内化的五个阶段\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一个阶段：不知不觉\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我们学习了某方面知识，并且自认为理解了。然而，当生活中真正遇到和这方面知识相关的问题时，我们却往往想不起自己其实学过它。很多人学过谈判策略，但到了菜市场讨价还价时，却完全想不起运用这些技巧。问题只是换了“马甲”，我们就认不出来了。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>知识和应用场景脱节。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二个阶段：“事后诸葛亮”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>很可能在做完某件事后，你才突然想起来：“不对呀，我明明学过一种策略可以反驳他的！”这就是我们常说的“事后诸葛亮”。但“事后诸葛亮”其实是一个很关键的阶段。经过多次这样的经历，我们对运用这一知识就会变得越来越敏锐\u003c/strong> \u003cstrong>在面对类似的应用场景时，通过刻意思考，可以回忆起那些不太明显的弱关联。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>在面对类似的应用场景时，通过刻意思考，可以回忆起那些不太明显的弱关联。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三个阶段：中途掉头\u003c/strong>\u003c/p>\u003cp>\u003cstrong>在实践过程中意识到：“我好像学过某个方法，正好可以用来解决这个问题。”在这一阶段，对知识的应用意识已明显增强。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>看到类似场景，能够想到相关知识。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第四个阶段：刻意为之\u003c/strong>\u003c/p>\u003cp>\u003cstrong>当遇到相关问题时，我们能第一时间想到：“可以用 ×× 知识来解决这个问题。”但在具体应用时，还需要有意识地启动系统进行深入思考。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>在知识和应用场景之间建立强关联。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第五个阶段：回到不知不觉\u003c/strong>\u003c/p>\u003cp>\u003cstrong>没有意识到自己正在用某个知识解决问题，它已经内化为一种自然的思维方式和习惯。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>知识内化为直觉\u003c/strong>\u003c/p>","explains":"\u003cp>&lt;What（知识点和相关理念介绍，适用边界）&gt;\u003c/p>\u003cp>\u003cstrong>《刻意练习》这本书也曾提到过重复、刻意练习的价值，成为某一行业专家需要的练习时长。但是《好好思考》这本书最打动我的点在于，让我明白了重复不是苦哈哈的坚持，并且解决了我总是半途而废，没有意志力，又或者总是有种种困难，没办法做到不停去重复的问题。这本书让我明白了成事的关键、原理，以及获得每一个小小胜利的重要性。\u003c/strong>\u003c/p>\u003cp>请大家关注片段中一句话：\u003cstrong>\u003cu>从小事入手，积小胜为大胜。\u003c/u>\u003c/strong>\u003c/p>\u003cp>&lt;Why（前因后果、为什么要这么做，不这么做会有哪些糟糕的后果等）&gt;\u003c/p>\u003cp>\u003cstrong>为什么要从小事入手，积小胜为大胜很重要？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>估计有经验的人都知道靠意志力靠热情，一件事情坚持不了多久。但是前进道路上每一次小小的胜利，每一次成就感的获得，却会给即将消失殆尽的耐心浇灌甘露，也会使自信一点点建立，进而建立起正向的飞轮。做成一件小事，获得一次小胜利，一个个的小胜利终究会累积成大胜利，也许最终会取得令我们自己都惊艳的大胜利。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>同时拆页中的表格也告诉了我们知识的内化、习惯的的形成需要经过“不知不觉”“事后诸葛亮”“中途掉头”“刻意为之”“回到不知不觉”五个阶段。\u003c/strong>\u003c/p>\u003cp>&lt;How&gt;\u003c/p>\u003cp>哪具体怎么做呢？原文中提到两个建议，一是\u003cstrong>\u003cu>从小事入手，\u003c/u>二是\u003cu>积小胜为大胜\u003c/strong>\u003c/u>\u003cstrong>，\u003c/strong>我应用咱们拆书帮的方法将这两个建议转化“\u003cstrong>成事三步法”\u003c/strong>：\u003c/p>\u003cp>第一步：\u003cstrong>把大事或者把大目标先拆成小事、小目标。\u003c/strong>化大为小看似很简单，但是在实际操作中，我们往往低估事情的难度，而又高估自己的能力，导致目标制定不合理，往往出现事与愿违，越来越灰心丧气，之后开始怀疑动摇，最终放弃目标。\u003c/p>\u003cp>第二步：迈出第一步，先行动起来\u003cstrong>很重要。设定好小目标，并不意味着目标会自动达成，这也就是为什么很多人年初立flag很容易，但是年年立年年倒，至今也没有活成自己喜欢的样子。所以迈出第一步很重要，先开始干起来再说，不怕烂就怕因为完美情结作祟，一直等待完美的时机，等待一切准备好了再说，想一出手就让众人惊艳，结果自己把自己吓到裹足不前。\u003c/strong>\u003c/p>\u003cp>第三步：\u003cstrong>设法先取得一个小胜利，品尝一点小胜利的甜头，同时保持战略耐心，时刻提醒自己需要经过五个阶段才可以。\u003c/strong>\u003c/p>","interaction":"\u003cp>&lt;A1便签&gt;\u003c/p>\u003cp>我说一个自己的反面案例，不知道大家注意到没有，我3月份就报名了拆书过级，结果就因为没有\u003cstrong>把这个目标先拆分成小目标，拆页、逐字稿、拆书预备表，PPT应该什么时候准备，压根没有设立各个节点的目标，高估了自己的能力，又低估了拆书的难度，结果导致3月份压根没有拆。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>而且当时总觉要把其他事情忙完了才开始，还一定要选一本大家眼前一亮的书作为拆页，结果小胜利没取得，却因为没有遵守对自己的承诺，让自己丧失了信心，一度不愿意重新开始，拖过了3月又拖过了4月初，很感谢今天一同拆书的拆书家胜男对我的等待，推了我一把。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>正面案例：人到中年，随着代谢能力的下降，体重蹭蹭往上涨，自然就会跟自己的体重较起劲来，估计很多人也有过减肥经历，但是这一次我却取得了成功，成功减重20多斤。\u003c/strong> \u003c/p>\u003cp>\u003cstrong>回顾过去，就是因为把减肥这个目标拆成了一件件小事，从迈出家门的第一步开始，从最初的2公里，到5公里，10公里，以及能够跑下半程马拉松；也从最初的衣服都变得不合身，到年会能穿上原来漂亮的礼服，加入不同的跑圈认识很多有趣自律的朋友，每一次都有反馈的小胜利；最终把跑步变成了一项习惯，现在每天不运动总会觉得少了点什么。\u003c/strong>\u003c/p>\u003cp>&lt;A2便签&gt;\u003c/p>\u003cp>\u003cstrong>把成事三步法用在和孩子们的英语学习中：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一，针对和初中大宝的英语学习，计划以100天为大目标，以10天学一集《走遍美国》的内容为一个小目标。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二，计划从4月15日开始，每天晚上九点钟学习半个小时，不管刚开始读的有多磕巴都没事，先赶紧做起来，做的过程中再不断调整。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三，不再以学校的考试成绩作为是否胜利的指标，而是以每一集内容能听懂会跟着说作为小胜利，不断取得一集集的小胜利。保持战略耐心，同时刻提醒自己需要经过五个阶段才可以脱口而出。\u003c/strong>\u003c/p>\u003cp>&lt;强有力的结束语&gt;\u003c/p>\u003cp>从小事入手，先积小胜，大家可以看看最近有没有想达成的目标或者想学习的技能，从以上三个方面入手，先确立一个小目标取得一次小胜利，希望我今天的分享对大家可以有一点点启发，感谢大家抽出宝贵的时间耐心倾听，再次感谢我的师傅彭老师、观察家主持人红姐、一起拆书的小伙伴胜男，以及线上聆听的各位，也欢迎大家一起结伴拆书相互鼓励前进，我今天的分享就到这里，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1780477067000,"updated_at":1780655615000,"ria":true},{"id":19854,"topic":"三问辨模型！信息爆炸下的思维模型识别术","learn_goal":"","remark":"教你用三问法快速区分有效思维工具与无实操的鸡汤建议，精准筛选有价值知识，提升独立分析和思考判断能力","level":"TF3-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"kkk-cq","city":"重庆市"},"club":{"name":"重庆山城分舵","city":"重庆市"},"prologue":"\u003cp>\u003cstrong>【开场】自我介绍\u003c/strong>\u003c/p>\u003cp>大家好，我是KKK, 欢迎大家参加今天的拆书活动，今天给大家分享的主题是“三步辨别是“思维模型”还是“鸡汤””，活动前，我用三个标签介绍一下自己。\u003c/p>\u003cp>第一个标签，我是拆书帮的二级拆书家。\u003c/p>\u003cp>第二个标签，我是一名新能源行业售前工程师，\u003c/p>\u003cp>第三个标签，我是成甲《好好思考》慢读会成员。\u003c/p>\u003cp>\u003cstrong>技能点：【场景法图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>场景\u003c/strong>：大家有没有遇到过这样的情况？早上刷视频，手机都会看到各种各样的观点，有人教你要果断放弃、及时止损，又有人劝你要坚持到底、绝不认输；有人说做事要极致专注，又有人说要多线发展、全面开花。\u003c/p>\u003cp>\u003cstrong>提问：\u003c/strong>这些话听着都有道理，可真遇到事了，我们到底该听谁的、怎么选？\u003c/p>\u003cp>\u003cstrong>影响：\u003c/strong>如果一直没有一套靠谱的判断方法，我们就只能跟着感觉瞎选，学再多碎片化知识，也没法帮自己做对决策、解决实际问题。\u003c/p>\u003cp>\u003cstrong>解决：\u003c/strong>今天我带来的《好好思考》这本书，就能帮我们打破这种困局。本书作者成甲深入研究了投资大师查理·芒格的学习法，为我们提炼出了一个实用的底层思考工具——也就是书里说的“思维模型”。掌握了这个工具，我们就能拥有一套靠谱的判断标准，快速看透现象，筛选出真正有价值的信息。\u003c/p>\u003cp>\u003cstrong>技能点：【学习目标】\u003c/strong>\u003c/p>\u003cp>今天的学习目标是：在跟随我完成本次 RIA 现场学习后，学习者能够使用“三问法“\u003cstrong>（澄清），\u003c/strong>辨别（\u003cstrong>行为\u003c/strong>）接收到的信息是否是思维模型\u003cstrong>（界定）\u003c/strong>。\u003c/p>","ratings_count":1,"texts":[{"id":24292,"quote":"\u003cp>\u003cstrong>【原文片段】\u003c/strong>\u003c/p>\u003cp>什么是思维模型\u003c/p>\u003cp>芒格的启示：理解思维模型的核心定义\u003c/p>\u003cp>要理解芒格如何从跨学科知识中汲取智慧并解决实际问题，首先需要弄明白他所说的 “思维模型” 究竟是什么。\u003c/p>\u003cp>芒格在《穷查理宝典》中极为推崇*“思维模型” 这一概念，但对于其具体定义，并未给出特别明确的界定。其中一段较为相关的论述如下：\u003c/p>\u003cp>长久以来，我坚信存在“某个系统”——几乎所有聪明人都能掌握的系统，它比绝大多数人用的系统管用。你需要的是在你的头脑里形成一种思维模型的“复式框架”。有了那个系统之后，你就能逐渐提高对事物的认识。\u003c/p>\u003cp>然而，这段话还不足以让我们准确理解思维模型的核心要义。\u003c/p>\u003cp>于是，2019年5月赴美采访芒格先生时，我特意向他提问：“究竟什么是思维模型？您又是如何寻找思维模型的？”\u003c/p>\u003cp>芒格笑了笑，回答道： “其实很简单，你在解决问题时，需要关注哪些做法有效，哪些无效。 ”\u003c/p>\u003cp>他的合伙人李录先生补充道：“芒格先生会把那些持续有效的方法总结出来，形成思考某一类问题的思维模型。 ”\u003c/p>\u003cp>这次采访以及我后续的研究启发了我，可以从“有效思考方法”这一角度来理解思维模型。\u003c/p>\u003cp>在此基础上，我总结出一个关于思维模型的简单定义——\u003c/p>\u003cp>思维模型，是有效解决特定问题的思考工具。\u003c/p>","explains":"\u003cp>\u003cstrong>技能点：【概念辨析】\u003c/strong>\u003c/p>\u003cp>什么是思维模型？书中给出了一个非常清晰的定义：\u003c/p>\u003cp>所谓的思维模型，就是有效解决特定问题的思维工具。\u003c/p>\u003cp>这个定义有三个关键点，分别是“有效”、“特定问题”和“思考工具”，我们来一一看一下。\u003c/p>\u003cp>\u003cstrong>案例1\u003c/strong>：“凡事要换位思考”这是思维模型吗？\u003c/p>\u003cp>先看&quot;特定问题&quot;， &quot;凡事&quot;没有边界，处理家庭矛盾可以用，遇到骗子也要换位思考吗？肯定不对。\u003c/p>\u003cp> 再看&quot;有效&quot;， 在处理人际关系、化解矛盾时，确实有效。\u003c/p>\u003cp> 再看&quot;思考工具&quot;，可以照着做，站在对方角度想一想。\u003c/p>\u003cp> 两项满足，但缺&quot;特定问题&quot;——不是思维模型。\u003c/p>\u003cp>\u003cstrong>案例2\u003c/strong>：上火喝王老吉？是思维模型吗？\u003c/p>\u003cp>先看&quot;特定问题&quot;，针对&quot;上火&quot;这个具体场景，问题明确。\u003c/p>\u003cp> 再看&quot;有效&quot;，中医里&quot;上火&quot;分实火、虚火、心火、肝火，情况各不相同。一罐凉茶饮品没有经过系统验证，无法适配所有情况。所以有效性存疑。 \u003c/p>\u003cp>再看&quot;思考工具，可以照着做，去买一罐喝。\u003c/p>\u003cp>两项满足，但缺&quot;有效&quot;——不是思维模型。\u003c/p>\u003cp>\u003cstrong>案例3：\u003c/strong>“减法就是少吃多动”是思维模型吗？\u003c/p>\u003cp>先看&quot;特定问题&quot;，这句话是针对&quot;减肥&quot;这个具体问题。\u003c/p>\u003cp> 再看&quot;有效&quot;吗？有效能减肥。\u003c/p>\u003cp> 再看&quot;思考工具&quot;，“*不是**——少吃多少？多动什么？怎么动？没有具体方法或步骤。\u003c/p>\u003cp>所以它不是思维模型。\u003c/p>\u003cp>\u003cstrong>案例4：\u003c/strong>我们再看“设定目标要符合SMART原则”是不是思维模型？\u003c/p>\u003cp>首先看它针对特定问题，例如“定目标不落地，定了完不成”。\u003c/p>\u003cp>其次看他它是有效的，有无数人测试有效。\u003c/p>\u003cp>最后它还是可复用的工具，可以照着5个要素去一一检查，可以反复用。\u003c/p>\u003cp>所以，思维模型必须同时具备这三个特征：针对特定问题、有效、思维工具。缺任何一个，都只是建议或鸡汤，不能作为我们做决策的思维模型。\u003c/p>\u003cp>\u003cstrong>【how】那具体怎么判断呢？\u003c/strong>\u003c/p>\u003cp>那么，在日常生活中，我们具体怎么辨别呢？我给大家总结了三问法。\u003c/p>\u003cp>第一步：定位问题——当你听到一个观点，先问自己：“这个观点是想帮我解决什么具体问题？”（如果是空话，pass）\u003c/p>\u003cp>第二步：检验有效性——问自己或对方：“这个说法有实践验证过吗？有没有反例？”（如果只是鸡汤，pass）\u003c/p>\u003cp>第三步：检查可操作性——问：“这句话能让我照着做吗？有没有具体的方法/步骤？”（如果只是口号，pass）\u003c/p>\u003cp>以后你刷到任何观点，用这三问一试，立刻分清是能帮你的思维模型，还是没用的鸡汤。\u003c/p>\u003cp>\u003cstrong>【where】适用边界\u003c/strong>\u003c/p>\u003cp>这个方法适用于你在学习、工作中遇到感兴趣的观点、方法或建议时，想快速判断它是否值得深入学习或应用。\u003c/p>\u003cp>\u003cstrong>【案例】\u003c/strong>\u003c/p>\u003cp>那这个方法到底怎么用呢？我来给大家展示一下，我将来应用这个方法的一个包括时间、地点、人物、起因、经过、结果及对话的案例。\u003c/p>\u003cp>【时间】：昨天下午\u003c/p>\u003cp>【地点】：公司茶水间\u003c/p>\u003cp>【人物】：我、朋友小高\u003c/p>\u003cp>【起因】\u003c/p>\u003cp>我去茶水间接水，看见小高正在刷手机，一脸感慨。\u003c/p>\u003cp>小高：“哎，我刚刷到个说法，我特别认同。”\u003c/p>\u003cp>我：“哦？说的啥呀？”\u003c/p>\u003cp>小高：“他说，成年人学习最好的方式就是找个老师。我想想还真是，我学东西一直进步慢，就是没人带。”\u003c/p>\u003cp>【经过】\u003c/p>\u003cp>我心里想到用“三问法”判断了一下，嘴上顺着和他聊：\u003c/p>\u003cp>我：“我也觉得有道理，那这句话是想帮我们解决什么问题呢？”\u003c/p>\u003cp>小高：“就是学习没方向、进步慢，想高效成长。”\u003c/p>\u003cp>我：“那只靠找老师，就一定有用吗？”\u003c/p>\u003cp>小高：“找对才有用，找错反而浪费时间。”\u003c/p>\u003cp>我：“那光听这句话，我们知道接下来具体该怎么做吗？”\u003c/p>\u003cp>小高：“不知道，去哪找、怎么选都没说。”\u003c/p>\u003cp>【结果】\u003c/p>\u003cp>聊完之后，我们都明白，这只是个有道理的建议，没法直接拿来用，对于我来讲这句话，就不是一个“思维模型”。\u003c/p>","interaction":"\u003cp>\u003cstrong>技能点：【A2编剧本】\u003c/strong>\u003c/p>\u003cp>“接下来请大家结合自己的真实生活，想一个你在未来一周内极有可能遇到的场景（比如：你的领导给你提了一个职场建议，或者家人给你发了一篇养生文章，刷抖音看到学习方法）。请为你自己编写一段未来会发生的小故事剧本。要求包含：时间、地点、人物、起因、经过、结果以及对话。\u003c/p>\u003cp>剧本中需要用三问法自然交流：\u003c/p>\u003cp> 第一问：这个观点解决什么具体问题\u003c/p>\u003cp> 第二问：分析它是否真实有效\u003c/p>\u003cp> 第三问：判断是不是可重复使用、落地操作的工具\u003c/p>\u003cp>\u003cstrong>【分享】\u003c/strong>\u003c/p>\u003cp>好了，时间到。有哪位伙伴想分享一下你的故事剧本？\u003c/p>\u003cp>学习者嘉文分享剧本。\u003c/p>\u003cp>剧本：判断“人人都要学小龙虾”是不是思维模型\u003c/p>\u003cp>时间：未来一周的周一工作日，地点：公司茶水间，老板叫住刚接完水的嘉文\u003c/p>\u003cp>老板：嘉文，我昨天看了个行业分享，那个叫OpenClaw的AI工具大家都简称“龙虾”，都说效果不错，他们说“人人都要学小龙虾”，你这周抽空上手试试，回头同步下学习情况。\u003c/p>\u003cp>嘉文：好的老板，我记下了，这周我会安排时间试试的。\u003c/p>\u003cp>老板走后，嘉文用刚学到的三问法做梳理辨别，人人都要学小龙虾”是不是思维模型。\u003c/p>\u003cp>嘉文（边梳理边自言自语）：\u003c/p>\u003cp>第一问：这个观点解决什么具体问题？——这个AI工具本身是解决特定开发场景问题的，对应不上我日常本职工作要解决的具体问题，没有适配我岗位的适用边界，不符合要求。\u003c/p>\u003cp>第二问：分析它是否真实有效？——目前从来没有验证过它用在我这个工作场景里是有效的，没有对应的实践支撑，有效性确认不了，不符合要求。\u003c/p>\u003cp>第三问：判断是不是可重复使用、落地操作的工具？——它也没有给出适配我工作场景的明确操作步骤、执行标准，我没办法把它反复用在我日常的同类工作里，不符合要求。\u003c/p>\u003cp>嘉文最终得出结论：老板说的“人人都要学小龙虾”，目前看不到能解决我任何具体问题，也没法验证龙虾就有效，也没有告诉具体的方法或提供工具，所以，“人人都要学小龙虾”不是思维模型。\u003c/p>\u003cp>\u003cstrong>【反馈】\u003c/strong>\u003c/p>\u003cp>嘉文的剧本里用三问法一步步追问，发现老板的“人人都要学小龙虾”不是“思维模型”，顶多只是一个建议。\u003c/p>\u003cp>\u003cstrong>【总结】\u003c/strong>\u003c/p>\u003cp>今天我们学会了用三问法判断思维模型，这个能力在信息爆炸的时代特别宝贵。从今天开始，当你在工作中遇到各种观点和方法时，就可以运用这个三问法，问解决的是什么问题，问有效吗？问具备操作性吗？快速识别出哪些是真正有价值的思维工具，哪些只是鸡汤。\u003c/p>\u003cp>学会思考比学会答案更重要。掌握了判断方法，你就拥有了持续成长的能力。期待大家把这个方法真正应用到生活和工作中去！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1777975634000,"updated_at":1777977201000,"ria":true},{"id":19714,"topic":"追问有效策略背后的原理","learn_goal":"","remark":"《好好思考》","level":"TF2-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"林子呀","city":"上海市"},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":"\u003cp>【自我介绍】\u003cbr>大家好，我是林子， 是一个很喜欢用\u003cstrong>系统模型\u003c/strong>来理解问题的拆书家。\u003cbr>今年我的核心关键词是「积极主动」。\u003cbr>【学习目标】\u003cbr> 在本场拆书学习中，现场使用「两步追问」法，去寻找小妙招背后的原理和思维方式。\u003cbr>\u003cbr>【FAB法介绍书籍】\u003cbr>今天我选的拆页是来自于《好好思考》这本书。\u003cbr>\u003cstrong>F｜特征\u003c/strong>\u003cbr>作者是成甲，一位聚焦“多元思维模型”的作者，这本书关注的不是单个技巧，而是我们在做判断、做决策时，背后到底在用什么样的思维方式。\u003cbr>\u003cstrong>A｜优势\u003c/strong>\u003cbr>和很多教你“怎么做”的方法书不同，这本书更强调“为什么这么做有效”。它试图把不同的方法放进同一套思维框架里，帮助我们理解方法之间的共通原理，而不是记一堆零散步骤。\u003cbr>\u003cstrong>B｜收益\u003c/strong>\u003cbr>如果你也有这样的体验：方法学了不少，但一换场景就不知道该怎么用，这本书真正想帮你的，是把这些零散的方法，变成一种以后还能反复使用的思考能力。而这个拆页可以让你用追问的方式找到通用的原理。\u003cbr>下面请大家用两分钟的时间阅读一下拆页，阅读时可以带着一个问题：这个例子里，作者是怎么一步步往“更底层”去追问的？\u003c/p>","ratings_count":1,"texts":[{"id":24133,"quote":"\u003cp>追问有效策略背后的原理\u003cbr>关于如何在解决问题的过程中，不断追问有效策略背后更深层的原理，我自己有一段有趣的经历。\u003cbr>在‘动批’砍价的方式是：从脚脖子上砍，如果他报价400元，你就还价为40元！”她们看我目瞪口呆不相信，就带我现场实战，真的从40元起，一番博弈后，成功地以95元的价格买下我看中的衣服。这件事给我留下了深刻的印象，也带来了深深的伤害。\u003cbr>如果我们要训练自己的深度思考力，就不能停留于此，而是要继续追问，为什么“从脚脖子上砍”这个策略会有效？这个策略对所有类似问题都有效吗？有没有比这个策略更基本、更底层的原理？\u003cbr>带着这个问题，我发现，如果不是在“动批”买衣服，而是换了其他场景，如买车或进行商业谈判，这个“从脚脖子上砍”的策略就不太好使了：一辆车定价40万元，我和导购砍价4万元，不被保安轰出来才怪。\u003cbr>这时，我们就看到这个有效策略的局限性。那我们就要追问，“从脚脖子上砍”背后的原理究竟是什么？有一次，我看到一本讲商业谈判方法论的书，书中介绍了一系列谈判方法论。值得一提的是，其中第一个策略就是“狮子大开口”，要给谈判对手出乎意料的强硬条件。这让我一下子就想起了当年的“从脚脖子上砍”。\u003cbr>为什么当年在“动批”买衣服的策略，会在商业谈判方法论中出现呢？显然，这两个方法背后有共同的更底层的原理。直到学习心理学后，我才发现，“从脚脖子上砍”和“狮子大开口”等谈判策略其实都是利用了心理学“锚定效应”，其背后的思维方式都是利用人性的弱点寻求博弈中的优势。\u003cbr> ——片段摘自《好好思考》P30-33\u003c/p>","explains":"\u003cp>【WHAT】\u003cbr> 这个片段讲的是\u003cstrong>遇到看似好用的技巧时，不停留在表面，而是追问它为什么有效、在什么情况下失效\u003c/strong>。核心内容是理解技巧背后的原理和思维方式.\u003cbr>\u003cstrong>【WHY\u003c/strong>】\u003cbr>掌握这些原理和思维方式，让我们在不同环境下都能灵活应用技巧。它可以帮助我们更稳健地解决问题、应对复杂情境，同时培养可迁移的思维能力，使学习和实践更有效。\u003cbr>【WHY NOT】 \u003cbr>\u003cstrong> 常见做法\u003c/strong>：\u003cbr>很多人遇到好用的技巧，直接照搬使用，却不去想为什么它有效。短期可能看起来管用，但一旦环境或任务改变，技巧就会失效，挫败感随之而来。\u003cbr>比如直接套用拆书模板，像我这次2-1的拆页改了好几稿，因为开始只是直接套用拆书稿模板，而没有理解whatwhyhow这些背后的原理和思维方式。\u003cbr>【HOW\u003cstrong>】\u003c/strong>\u003cbr>那具体怎么做呢？今天我们只用一个非常简单的工具——\u003cstrong>两步追问\u003c/strong>。\u003cbr>\u003cstrong>第一步：这招为什么会管用：寻找方法背后的学科原理\u003c/strong>\u003cbr>\u003c/p>\u003cul>\u003cli>它可能涉及心理学、管理学、教育学等哪个方面的原理？\u003c/li>\u003cli>例如，它是通过激励、奖励、习惯养成，还是认知调节起作用的？\u003c/li>\u003c/ul>\u003cp>\u003cstrong>第二步：我是在用什么方式看人或看问题？找到底层的思维方式和视角\u003c/strong>\u003cbr>\u003c/p>\u003cul>\u003cli>你是在尝试控制、激励、理解、交换，还是尊重对方？\u003c/li>\u003cli>想想自己的出发点和心态，这招体现了怎样的思维方式。\u003c/li>\u003c/ul>\u003cp>不需要一次想得多深，只要比原来多往下一层，就已经在进步了。\u003cbr>【WHERE\u003cstrong>】\u003c/strong>\u003cbr> 两步追问法适用于一个问题反复出现、对你影响很大，或你已经试过多种方法却始终不稳定时；不适用于紧急事务、简单操作或信息不全的猜测。 \u003cbr>【案例】\u003cbr>在读这个拆页时，我想到了自己在亲密关系里反复踩的一个坑。\u003cbr>以前，只要有冲突，我第一反应就是不说话，把情绪压下来，等事情过去就算了。当时觉得这是在避免冲突，也算是一种成熟处理方式。\u003cbr>后来我发现，这种“沉默”虽然能让场面暂时安静，但问题并没有消失。时间一长，对方会觉得我在回避、不在乎，我自己也越憋越难受。关系看似没吵架，但总是卡在原地。\u003cbr>再后来，我学了一些沟通方法，比如“提问式倾听”。一开始我照着做：认真听对方、点头回应，但关系依然不顺。原因在于，我并没有对“提问式倾听”进行思考，只是拿来就用。\u003cbr>这时，我开始用书里讲的\u003cstrong>两步追问\u003c/strong>：\u003cbr>\u003c/p>\u003cul>\u003cli>为什么“倾听”有时候有效，有时候却流于形式？\u003c/li>\u003cul>\u003cli>往下一层看，我发现真正起作用的不是技巧，而是心理学里的\u003cstrong>同理心\u003c/strong>：我有没有一边感受对方情绪，一边承认自己的需要？\u003c/li>\u003c/ul>\u003cli>继续追问，我是在以什么方式去看的？\u003c/li>\u003cul>\u003cli>我意识到：当我把对方当成需要“安抚”的对象时，无论用什么方法，关系都会卡住；只有当我把对方当成一个有感受、有边界的人时，倾听才真正发生——哲学上叫看到对方的\u003cstrong>主体性\u003c/strong>。\u003c/li>\u003c/ul>\u003c/ul>\u003cp>回头看，我发现问题不在方法不够，而是一直停留在“怎么做”，没有关注“我用什么方式对待这段关系”。\u003cbr>当视角发生变化后，再遇到冲突，我更能判断：什么时候需要安静下来，什么时候需要表达真实感受，而不是机械套用技巧。\u003c/p>","interaction":"\u003cp>分享A1-激活经验\u003c/p>\u003cp>你在生活中有没有遇到一些尴尬场景，比如“你想找人帮忙但不好意思开口”，“在聚会上遇到不熟的朋友从哪里聊起”“想拒绝别人的工作请求”，请写下你的小妙招，并说明在什么情境下使用？给大家3分钟左右时间讨论，结束后请一位伙伴分享。\u003cbr>学习者经验分享：\u003c/p>\u003cp>场景是，别人觉得我画画比较好，所以想找我免费写一个春节对联；\u003c/p>\u003cp>我一般应对的方式是：可以我可以买一副送给你。或者我给你介绍一个书法大师跟你认识，你让他给你写一幅。\u003c/p>\u003cp>A1+反思加工\u003c/p>\u003cp>刚才你写下了一个自己常用的小妙招，现在请用刚学到的 \u003cstrong>两步追问法\u003c/strong>，如果再遇到同样的情况可以依次思考这两个问题：\u003c/p>\u003col>\u003cli>\u003cstrong>这招为什么会起作用？\u003c/strong>\u003c/li>\u003cul>\u003cli>它可能涉及心理学、管理学、教育学等哪个方面的原理？\u003c/li>\u003cli>例如，它是通过激励、奖励、习惯养成，还是认知调节起作用的？\u003c/li>\u003c/ul>\u003cli>\u003cstrong>我是在用什么方式看人或看问题？\u003c/strong>\u003c/li>\u003cul>\u003cli>你是在尝试控制、激励、理解、交换，还是尊重对方？\u003c/li>\u003cli>想想自己的出发点和心态，这招体现了怎样的思维方式。\u003c/li>\u003c/ul>\u003c/ol>\u003cp>不需要回答得非常精准，重点是\u003cstrong>开始往下一层追问\u003c/strong>，理解背后的原理和自己的心态，而不是只停留在“我做了什么”，3分钟讨论后做分享。\u003c/p>\u003cp>学习者分享：\u003c/p>\u003cp>这招为什么起效，背后是给他提供了更多可能性的选项，应该是属于心理学领域的原理。\u003c/p>\u003cp>再深一步追问，有点像你之前提到的哲学的主体性，因为我是把这件事的的选择权又交还给他，他可以自由做选择，而不是“不得不“”只能找我这样。\u003c/p>\u003cp>好的感谢学员的分享，感谢大家的参与， 希望大家在生活中不断练习这两步追问 ， 让思考越来越有力量 。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1770617788000,"updated_at":1770622281000,"ria":true},{"id":17118,"topic":"NLP思维逻辑层次模型","learn_goal":"","remark":"我们的生活中充满了柴米油盐酱醋茶，七大姑，八大婆，工作上各种临时突发状况，还有常常使用PUA的上司。结了婚的人当初的在一起只用考虑两个人的关系，现在揉合了非常多现实的考量，还有孩子教育的各种卷……类似这样的日常琐碎麻烦充斥着我们的生活，让人焦虑、自责、无助，倍感心累。该怎么摆脱这种日常琐碎麻烦？“NLP思维逻辑层次模型”可以帮到你！","level":"TF3-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"嘿，Lydia你来了","city":"广州市"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"\u003cp>大家好。看来今天有老朋友也有新朋友哈。我是Lydia。我有三个标签。标签一是职场搬砖人，目前在企业里从事行政管理工作，我擅长发现工作中的心流时刻；标签二是孩儿妈，我和一个小姑娘斗智斗勇超过13年，饱尝个中滋味，至今斗志昂扬；三是向内探索者，我渴望更加深刻地直面自己，来拆书帮打怪升级就是我向内探索的重要方式之一。\u003c/p>\u003cp>【分组】\u003c/p>\u003cp>今天来了2位学习者，那就直接成一组，方便等下小组讨论哈。\u003c/p>\u003cp>【用场景介绍法介绍图书】\u003c/p>\u003cp>今天我选择的拆页来自成甲老师的《好好思考》中的“NLP思维逻辑层次模型”。\u003c/p>\u003cp>\u003cstrong>事件场景：\u003c/strong>最近有件事对我有些困扰：今年4月我在家附近的游泳馆办了张年卡，眼看着没几个月到期了，我一共去了7次，心里有些挫败和沮丧。当时办卡的时候心里盘算着一个月怎么着也能保证去6-8次，结果连一个月的量都没达到……\u003c/p>\u003cp>\u003cstrong>提问：\u003c/strong>想必大家也遇到过这种困扰吧？除了自我成长上的困扰，事实上我们的生活中还充满了柴米油盐酱醋茶，七大姑，八大姨，工作上各种临时突发状况，还有常常使用PUA的上司。结了婚的人当初的在一起只用考虑两个人的关系，现在揉合了非常多现实的考量，还有孩子教育的各种卷……类似这样的日常琐碎麻烦充斥着我们的生活，让人焦虑、自责、无助，倍感心累。该怎么摆脱这种日常琐碎麻烦呢？ \u003c/p>\u003cp>\u003cstrong>影响：\u003c/strong>如果被这种日常琐碎麻烦包裹，糟糕的感受反复出现，我们的情绪可能失控，身心会受到极大的威胁，做出的行为很有可能伤人伤己，导致生活一团糟。\u003c/p>\u003cp>\u003cstrong>解决：\u003c/strong>成甲老师的《好好思考》是国内第一本研究如何用多元思维模型培养深度思考力的书。这本书可以帮助我们辨识不同场景下面临的同一种难题，帮助我们找到共通的关键。而我们今天分享的“NLP思维逻辑层次模型”通过提升思维层次的方式能够让我们对日常琐碎麻烦重新定位，从而促使我们采取积极行动，适应并接受现实环境制约，实现身心健康平衡。\u003c/p>\u003cp>【学习目标】\u003c/p>\u003cp>希望大家在跟随我完成本次RIA现场学习后，能够运用NLP思维逻辑层次模型对自己近期遇到的问题进行一次分析，准确辨识自己学习前后对同一问题的思考层次，达到重新定义问题的目的。\u003c/p>\u003cp>【A1自测】\u003c/p>\u003cp>开始今天的拆页分享前，请大家做一个简单的自测题。\u003c/p>\u003cp>这个自测能够帮助大家了解一下自己在工作生活中的思考层次。请仔细阅读下面表格中的每句话，根据自己的实际情况打分，不用纠结分数，以自己的第一反应为准即可，打完分请大家将每题得分相加计算总分，时间为1分钟。\u003c/p>\u003cp>【I】解释自测题\u003c/p>\u003cp>大家都做完了吗？19分及以上的请举手。两位学习者一个24分，一个30分，都在19分以上啊。说明大家平时思考得已经比较深入了，希望今天的分享能让大家从理论上更加坚定自己的判断和选择；如果在13-18分（含13分）这个区间，说明大家的思考已经开始深入了；如果分值低于13分，说明思考相对浅层。\u003c/p>\u003cp>下面我们开始今天的分享。\u003c/p>\u003cp>下面请大家阅读拆页。请大家读完后抬头或举手示意。\u003c/p>","ratings_count":1,"texts":[{"id":21287,"quote":"\u003cp>【R】原文片段《好好学习》第五章 综合运用多元思维模型解决复杂问题 第一节 多元思维模型综合应用之降维打击P201-203 \u003c/p>\u003cp>理解思维的层次性对我们解决问题极为重要，因为在低层次无法解决或者非常困难的问题，从高一个层次思考往往就能轻易找到解决方法。可很多时候，我们只关注思考问题要逻辑清晰、推理严密，但是很少思考我们是在哪个层次上分析的。如果能够对思考逻辑进行分层，我们就有了强大的思考武器。比如，心理学家罗伯特·迪尔茨，他发现了人们思考问题的分层逻辑——环境层、行为/行动层、能力层、价值观层、角色层、愿景层六个逻辑层次。这六个层次逐级上升——低层次难以解决的问题，在高层次就容易处理。\u003c/p>\u003cp>罗伯特·迪尔茨的逻辑层次模型\u003c/p>\u003cp>举个例子，你朋友考试没考好，他在总结原因，而你需要鼓励他好好学习。当你朋友说：“我们家总是很吵，考试复习没法静心，我考不好。”你不要着急和他讨论家里环境的事情，你要意识到，他思考问题的层次在“环境”层，归因于外部环境，如果你和他在一个层次讨论问题，你们就陷入了争辩。这时，你可以从更高的“行为/行动”层启发他，让他意识到环境是可以改变的。比如你可以说：“那下次遇到这种情况，能否自己改变环境，比如临时去朋友家或者宾馆复习，避免影响考试？”\u003c/p>\u003cp>当你朋友说：“嘿，我家有钱，反正以后要做买卖，会算数就行了。”你要意识到，他现在思考问题的层次在价值观层。如果你要启发他，就要从“角色”层入手：“未来你是你们家族的顶梁柱，要处理各种复杂情况，很多情况由不得你选的。你必须学会解决这样的情况。所以，现在你就开始锻炼自己解决问题的能力。”从角色层思考问题就跳出了价值观层的陷阱，看到新解决方案。\u003c/p>","explains":"\u003cp>我看到大家基本上都看完了哈。\u003c/p>\u003cp>【互动】\u003c/p>\u003cp>大家通过拆页看到了什么关键信息？拆页中有什么字词引起了你的注意？\u003c/p>\u003cp>层次、愿景等六个词、思维……\u003c/p>\u003cp>【What】\u003c/p>\u003cp>通过“层次”一词我们知道，人的思维是有层次的，一般分为六层，分别是愿景、角色、价值观、能力、行为和环境。不同层次思考的内容不同，这就是NLP思维逻辑层次模型。\u003c/p>\u003cp>关于这六个层次，我们直接上例子。大家知道，关于读书的目的，周恩来总理说过“为中华之崛起而读书”。我们就这句话用NLP模型来梳理一下。\u003c/p>\u003cp>通过这句话，大家能感受求学时的周恩来渴望为世界、为中华民族做些什么？\u003c/p>\u003cp>对，希望中华崛起，这就是他当时的愿景。\u003c/p>\u003cp>为了实现中华崛起，他希望成为什么样的人呢？\u003c/p>\u003cp>百度百科上的评价是伟大的马克思主义者等等。但对于当时的他而言，有一点是很明确的——他一定希望打破当时的社会现状，成为一个社会变革者，对吧？这就是他希望成为的角色。\u003c/p>\u003cp>为了成为社会变革者，在他心里，什么最重要呢？是的，革旧出新、振兴中华。其他的事情都要这个让路。这就是价值观层了。\u003c/p>\u003cp>为此，他需要培养什么样的能力呢？\u003c/p>\u003cp>社会组织、管理能力、洞悉本质能力、谈判能力等等。\u003c/p>\u003cp>为了培养这些能力，读书时他是怎么做的呢？他发奋苦读、海外求学。即使社会大环境动荡、生活清苦，他也在努力调整改善自己周边的小环境，发动、组织、宣传爱国进步青年，对吧？\u003c/p>\u003cp>请大家看看表格，通过表格，想必大家对思维六层次对应内容会有更深刻的印象。\u003c/p>\u003cp>请大家可以倒回去看看刚才的自测量表。第一题关于堵车，这个处于思维的哪个层次？对，环境层。第三题是“跟另一半沟通像是对着一堵墙，我也没什么办法”是哪个层次？是的，能力层。最后一个是“人生没有意义”，其实就是愿景层了。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>大家想想，刚才我讲的因为计划一个月游泳6-8次，实际8个月才去了7次而困扰的事情中，我对问题的思考处于哪个层次？\u003c/p>\u003cp>大家一致认为是行为层，对吧？事实上，当我意识到这件事对我造成困扰后，我就回想了一下一些细节，比如我当初为什么要办卡。因为我希望把游泳作为日常运动的一种方式。保持日常运动是因为我希望尝试不同运动方式对自己的适宜性，想找到自己适合的运动方式。而这么做的目的是希望能坚持运动，保持身体健康，实现自由。\u003c/p>\u003cp>这个思考过程如下图所示：\u003c/p>\u003cp>后面为什么没有经常去呢？因为办完卡没多久我就二阳了。二阳之后，我每次游泳后，鼻子就要难受很久。所以我才暂停了游泳这件事。但是我每天早起会拉伸，周一至周五会规律散步，周末会跑步，我的运动习惯一直保持着。这与我通过运动保持身体健康的初衷一致，只是改变了运动形式。那么在游泳卡这件事上，我要做的是如何减少自己的损失，比如转让游泳卡或者申请延期。\u003c/p>\u003cp>从上面这段经历大家对应用NLP思维逻辑层次模型应该有了感知了：\u003c/p>\u003cp>应用步骤：\u003c/p>\u003cp>1.确定问题。\u003c/p>\u003cp>2.运用NLP思维逻辑层次模型确定自己现在的思考层次。\u003c/p>\u003cp>3.运用NLP思维逻辑层次模型向上拓展思考层次。\u003c/p>\u003cp>4.对比前后思考内容，重新定位问题。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>由上可知，掌握并熟练运用这个模型能够帮助我们从更高层次去认识问题，获得有效解决方法，甚至消灭问题。\u003c/p>\u003cp>【Where】\u003c/p>\u003cp>其实只要我们思考问题，都会有思考层次的问题。只要想致力于从自身角度去解决问题，那么这个模型被广泛应用于生活的各个层面。比如在工作上如何和同事合作，在生活中如何与家人相处，还有如何规划个人发展路径等。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>有小伙伴可能有疑问，每次遇到问题都要这样思考吗？感觉好累。\u003c/p>\u003cp>其实NLP模型的应用关键是在你遭遇现实中的一地鸡毛时，促使你去想象未来你期望达到的样子，用美好的愿望帮你跨越现实的问题。大家习惯用这种方式思考后，会发现问题越来越少，会日渐轻松的。\u003c/p>","interaction":"\u003cp>（一）A3：场景设计（3分钟）\u003c/p>\u003cp>刚才一直是我在讲，下面大家来实践一下。我们刚刚学习了用NLP思维逻辑层次模型来重新定位日常琐碎麻烦。现在我们做个演练。请大家注意听要演练的场景：现在你是一个刚进入大学不喜欢自己专业的大学生，心里应该有很多抱怨：这个学校不咋地，管得严、课程设置没意思，还不能换专业。哎，谁叫我就是个普通学生呢？好像没什么办法换专业。上大学就是混日子……请尝试用NLP思维逻辑层次模型定位一下这些抱怨，并用NLP思维逻辑层次模型自上而下分析一下，看看会有什么不同？\u003c/p>\u003cp>大家请注意对照下面的应用模板先设计好你的思考路径，然后用两分钟设计出以“我是这样看待这些抱怨的”开头的一段话，然后在小组内分享。\u003c/p>\u003cp>NLP思维模板：\u003c/p>\u003cp>1.确定问题：刚进入大学不喜欢自己专业\u003c/p>\u003cp>2.运用NLP思维逻辑层次模型确定现在的思考层次。\u003c/p>\u003cp>“这个学校不咋地，管得严、课程设置没意思，还不能换专业”属于（ ）层；“哎，谁叫我就是个普通学生呢？”属于（ ）层；“好像没什么办法换专业。” 属于（ ）层；“上大学就是混日子”属于（ ）层。\u003c/p>\u003cp>3.运用NLP思维逻辑层次模型向上拓展思考层次。\u003c/p>\u003cp>刚才这些抱怨是站在（ ）层次上的，如果向上拓展，我们可以站在（ ）层次上思考，我们可以试着考虑（ ）。\u003c/p>\u003cp>4.对比前后思考内容，重新定位问题。 \u003c/p>\u003cp>之前我认为面对这个问题我只能（），通过模型分析我发现其实解决问题的办法很多，比如（）等等。\u003c/p>\u003cp>（二）A3：小组讨论（1分钟）（观察进展、纠正偏差）\u003c/p>\u003cp>下面请各组选取一个分享的场景讨论并补充完善，讨论中要能够明确指出使用模型前后思维所处层次，并对比使用模型前后的解决办法。\u003c/p>\u003cp>刚才听了小组的讨论，有一个点需要明确，我们使用NLP模型，最终目的是解决问题和麻烦，不必纠结是否一定要穷尽六个层次。拆页里举的例子也只是向上拓展了一个层次而已。\u003c/p>\u003cp>（三）A3：当众展示（2分钟）（当众展示环节）\u003c/p>\u003cp>下面请一位小伙伴展示一下你们小组的讨论结果。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>止盈老师：\u003c/p>\u003cp>1.确定问题：刚进入大学不喜欢自己专业，内心很多抱怨\u003c/p>\u003cp>2.运用NLP思维逻辑层次模型确定现在的思考层次。\u003c/p>\u003cp>“这个学校不咋地，管得严、课程设置没意思，还不能换专业”属于（ 环境 ）层；“哎，谁叫我就是个普通学生呢？”属于（ 角色 ）层；“好像没什么办法换专业。” 属于（ 能力 ）层；“上大学就是混日子”属于（ 价值观 ）层。\u003c/p>\u003cp>3.运用NLP思维逻辑层次模型向上拓展思考层次。\u003c/p>\u003cp>刚才这些抱怨是站在（ 环境、能力、价值观和现在的角色 ）层次上思考的，如果向上拓展，我们可以站在（ 愿景和未来的角色 ）层次上思考，我们可以试着考虑（四年大学毕业后我的角色，到时候我就是一个职场打工人了，我当然希望能成为一个受欢迎的、优秀的职场人。这个是角色。为此，我意识到我掌握相应的职场生存技能对我很重要，肯定不能混日子。这个是价值观。为此，我必须要掌握专业知识、顺利毕业、不能缺课、准时完成作业、通过考试。这个是行为。）。\u003c/p>\u003cp>4.对比前后思考内容，重新定位问题。\u003c/p>\u003cp>通过对比我发现，我现在面临的问题不是喜不喜欢专业的问题，而是要考虑应该为四年后的我提前做好哪些准备的问题。\u003c/p>\u003cp>（四）A2：布置任务，指定具体要行动的事情，要求学习者回去后完成。（1分钟）\u003c/p>\u003cp>刚才的现场讨论很热烈，结果也很有成效，大家应该是比较接受这个思维模型的。但是我们即使在理智上认同应该从愿景、角色和价值观层次去看待现实问题，真正在日常生活中我们可能还是会处于惯性等原因从环境等下三层看待问题。接下来的两三周，请大家刻意留心遇到日常琐碎麻烦的场景，用NLP模型拓展思维层次，感受它的力量和效果。请大家完成之后微信反馈思考的过程情况。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>杨老师：场景1：迟到\u003c/p>\u003cp>* 确定问题：开会迟到了。\u003c/p>\u003cp>* 当前思考层次：能力层次（我没有足够的时间管理能力）。\u003c/p>\u003cp>* 向上拓展思考层次：角色层次（作为专业人士，我需要更好地管理我的时间以保持职业形象）。\u003c/p>\u003cp>* 重新定位问题：我应该如何在角色层次上思考，以更好地管理我的时间，避免开会迟到的问题？\u003c/p>\u003cp>场景2：忘记生日\u003c/p>\u003cp>* 确定问题：我忘记了朋友的生日。\u003c/p>\u003cp>* 当前思考层次：行为层次（我没有设置提醒或记日历）。\u003c/p>\u003cp>* 向上拓展思考层次：价值观层次（我重视保持亲密关系和关心朋友的幸福）。\u003c/p>\u003cp>* 重新定位问题：我应该如何在价值观的层次上思考，以更好地维护友情，避免忘记生日的问题？\u003c/p>\u003cp>场景3：无法专注工作\u003c/p>\u003cp>* 确定问题：我无法专注于工作任务。\u003c/p>\u003cp>* 当前思考层次：能力层次（我的专注力不够强）。\u003c/p>\u003cp>* 向上拓展思考层次：愿景层次（我渴望在工作中取得更多的愿景反馈）。\u003c/p>\u003cp>* 重新定位问题：我应该如何在愿景层次上思考，以更好地提高工作的专注度？\u003c/p>\u003cp>场景4：健康不佳\u003c/p>\u003cp>* 确定问题：中招了，我感到身体不适。\u003c/p>\u003cp>* 当前思考层次：环境层次（我的生活环境可能导致了健康问题）。\u003c/p>\u003cp>* 向上拓展思考层次：价值观层次（我重视健康和身体福祉，爱自己）。\u003c/p>\u003cp>* 重新定位问题：我应该如何在价值观的层次上思考，以更好地改善我的健康状况？\u003c/p>\u003cp>场景5：与家人争吵\u003c/p>\u003cp>* 确定问题：我与家人发生了争吵。\u003c/p>\u003cp>* 当前思考层次：行为层次（我无法有效地与家人沟通和处理冲突）。\u003c/p>\u003cp>* 向上拓展思考层次：价值观层次（家和万事兴，我重视家庭和和谐关系）。\u003c/p>\u003cp>* 重新定位问题：我应该如何在价值观的层次上思考，以更好地维护家庭和谐？\u003c/p>\u003cp>场景6：额外家务\u003c/p>\u003cp>* 确定问题：额外家务工作打搅太多了。\u003c/p>\u003cp>* 当前思考层次：环境层次（额外家务工作的量太大）。\u003c/p>\u003cp>* 向上拓展思考层次：角色层次（作为家庭成员，我需要更好地管理家务工作以维护家庭和谐）。\u003c/p>\u003cp>* 重新定位问题：我应该如何在角色层次上思考，以更好地管理家务工作？\u003c/p>\u003cp>场景7：学习进展缓慢\u003c/p>\u003cp>* 确定问题：我的某些新内容学习进展缓慢。\u003c/p>\u003cp>* 当前思考层次：能力层次（我需要提高学习能力）。\u003c/p>\u003cp>* 向上拓展思考层次：愿景层次（我渴望获得更多的知识和技能以实现愿景目标）。\u003c/p>\u003cp>* 重新定位问题：我应该如何在愿景层次上思考，以更好地提高学习进展？\u003c/p>\u003cp>止盈老师：\u003c/p>\u003cp>✅场景1：晚睡\u003c/p>\u003cp>a.确定问题：晚睡\u003c/p>\u003cp>b.当前思考层次：环境层次-各种事情太多了，花很多时间完成，所以导致晚睡。\u003c/p>\u003cp>c.向上拓展思考层次：能力层次-按重要及时事情来安排，能够很快的完成事情。\u003c/p>\u003cp>d.重新定位问题：我应该将事情分类，重新安排事情。\u003c/p>\u003cp>✅场景2：晚起\u003c/p>\u003cp>a.确定问题：晚起\u003c/p>\u003cp>b.当前思考层次：环境层次-晚睡导致晚起\u003c/p>\u003cp>c.向上拓展思考层次：行动层次-尝试养成早起生物钟\u003c/p>\u003cp>d.重新定位问题：我应该从行动层来解决晚起问题。\u003c/p>\u003cp>\u003cstrong>小结\u003c/strong>\u003c/p>\u003cp>止盈老师的分享让我想起了《大话西游》里面的一句台词：我的意中人是一个盖世英雄，有一天他会踩着七色的云彩来娶我。曾经我们期待有盖世英雄来拯救自己，后来才发现原来自己就是盖世英雄。NLP思维逻辑层次模型其实就是要我们在遇到问题时，站在理想中的那个自己的维度上去思考，为了那个美好的自己，在现实中具备在任何情况下处理好任何事情的勇气，并为此积攒能量。希望大家多多使用，早日遇见期许中的自己！\u003c/p>\u003cp>以上是本次过级的全部内容，感谢聆听！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1704345155000,"updated_at":1704437342000,"ria":true},{"id":14872,"topic":"关键词读书法","learn_goal":"","remark":"本书试图回答这样一个问题：如果说太阳底下没有新鲜事，那么*效的学习方法是什么？与人们通常认为的学习的关键是努力掌握更多的知识不同，作者认为如果我们能够看到事物之间的相似性，那么我们只需要学习各学科*杰出的思想，去抓*关键的要害，就可以解决绝大多数的问题。因此，作者把学习知识的基本单位定义为“思维模型”。思维模型有四个层次：经验技巧型、方法流程型、学科原理型、哲学视角型。查理·芒格所说的掌握“重要学科的重要原理”，即为本书中定义的“学科原理型”思维模型。那我们如何从思维模型入手，构建一个全新的学习思考体系，进而练就超强学习力？作者将结合自己10多年的研究经验，从基本原理、搭建知识体系、演示实战方法等多个角度系统讲解论述。","level":"TF2-2","duration":35,"status":30,"type":0,"chaishujia":{"username":"石研","city":"石家庄市"},"club":{"name":"石家庄冀城分舵","city":"石家庄"},"prologue":"\u003cp>大家好，我是石研，一个专职在线课程运营官，也是一个终身学习不断精进中的个人成长教练！\u003c/p>\u003cp>\u003cstrong>技能点：在讲解时，通过共享屏幕播放PPT，清晰呈现R原文、I便签核心内容、和A2指令。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>技能点：学习目标包含了学习者可被观察到/被测量到的行为或动作，线上学习者设计清晰体现了该学习目标。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>通过跟随我今天的RIA学习，学习者可以运用关键词阅读三步法高效理解一本书的核心问题和关键词，并向大家分享最近阅读一本书作者的思想和观点。\u003c/p>\u003cp>\u003cstrong>技能点：在FAB介绍法中，能够清晰辨别出聚焦于图书和学习主题的F、A、B。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【Feature特征】（以书为核心来满足好奇心）\u003c/strong>\u003c/p>\u003cp>今天我们要拆解的是《好好思考》，这本书豆瓣评分7.9，是知识管理研究者、“得到”说书人成甲的畅销书，被逻辑思维评选为“中国最会学习的人”， 通过深入解析查理·芒格的\u003cstrong>多元思维模型\u003c/strong>，帮助我们从\u003cstrong>思维模型入手，构建一个全新的学习思考体系，用思考打造超强学习力！\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 【Advantage优势】（用比较建立安全感）\u003c/strong>\u003c/p>\u003cp>《好好思考》是\u003cstrong>国内第一本\u003c/strong>研究如何用多元思维模型培养深度思考力的书，这本书不是简单罗列了一堆思维模型，而是作者结合自己10多年的研究经验，从基本原理、搭建知识体系、演示方法案例、拆解思维模型等多角度进行系统讲解论述，提供查理·芒格思维模型的落地方法。结合具体的生活案例解析，配有图示和表格，读起来不枯燥，非常落地实用。\u003c/p>\u003cp>\u003cstrong>【Benefit利益、好处】\u003c/strong>（强调学习者能学到什么以引发兴趣）\u003c/p>\u003cp>\u003cstrong>【B1】（学完本书可得利益）\u003c/strong>\u003c/p>\u003cp>大家有没有遇到过这些情况：你学习了很多知识，却零散不成体系，依旧无法解决绝大多数的问题？这本书将告诉我们搭建自己的知识体系，运用多元思维模型解决复杂问题。如果如果你发现不同领域和工作之间，往往面临同一种难题？这本书教我们打破学科壁垒，找到共通的关键。走进这本书，拓展思维模式的格局和边界，用思考看见世界的不同。\u003c/p>\u003cp>\u003cstrong> 【B2】（学完此片段可得利益）\u003c/strong>\u003c/p>\u003cp>如果你在阅读时也经常觉得只停留在“点状”零散的知识层面，无法形成提纲挈领地认识，好像读完一本书，依然没太大的印象到底这本书作者讲了什么内容，今天大家和我一起学习完拆页片段后，可以学习到用“关键词法”阅读和理解作者的整体思想和观点，高效掌握全书的脉络系统结构！\u003c/p>","ratings_count":1,"texts":[{"id":18886,"quote":"\u003cp>现在由我来带领大家拆解一下今天的片段：《好好思考》P65-66，下面我们花2分钟时间看一下原文片段，看完一页可以示意我一下。\u003c/p>\u003cp>选择书籍：《好好思考》\u003c/p>\u003cp>【R阅读原文拆页】\u003c/p>\u003cp>\u003cstrong>技能点：所选图书是实用类或理论类书籍。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【R】所选拆页，包括How的内容；且总内容未超过2页图书内页。\u003c/strong>\u003c/p>\u003cp>主题【页码】P65—66\u003c/p>\u003cp>关键词法——寻找更系统的思维模型\u003c/p>\u003cp>那我们该如何阅读和理解作者的整体思想呢？是不是必须逐字逐句读完呢？\u003c/p>\u003cp>未必。\u003c/p>\u003cp>当然，我说“未必”，并不代表我反对逐字逐句地读。实际上对于一些能够大幅提升我们现阶段认知地经典图书，是值得逐字逐句地读地。但是，就算逐字阅读，也需要先整体理解作者地思想和观点。\u003c/p>\u003cp>为了解决读书时单个思维模型积累地弊端，同时又高效地理解作者地整体思想，我们可以采用关键词法。\u003c/p>\u003cp>所谓关键词法。就是把阅读的单位，从在文章中找模型单点突破上升到从全书中找分析逻辑的系统思维。这样，我们在阅读的时候，就要先思考这本书要讨论的问题是什么。再看作者用了哪些知识、概念和思维模型分析这个问题，然后把重要的概念、思维模型以关键词的形式找出来，组织成解释问题的知识结构，即关键词网。\u003c/p>\u003cp>具体而言，关键词阅读法可以分为三步：\u003c/p>\u003cp>1. 分析确定作者在书中要解决的核心问题是什么。\u003c/p>\u003cp>2. 寻找书中与核心问题相关的关键词有哪些。\u003c/p>\u003cp>3. 这些关键词之间的关系是什么，它们是以什么逻辑解决问题的，有哪些有效策略？\u003c/p>\u003cp>找到了这三个问题的答案，我们对作者解决复杂问题的整体策略就会有提纲挈领地认识。\u003c/p>","explains":"\u003cp>what:\u003c/p>\u003cp> 这个拆页讲述了快速高效阅读和理解一本书作者的整体思想和观点的关键词三步法，关键词法，就是首先，确定全书的核心问题，然后寻找相关的关键词，最后把关键词之间的和与问题直接的关系厘清。当了解了这些，就能看到作者解决复杂问题的整体策略，积累我们自己的思维模型。\u003c/p>\u003cp>why:\u003c/p>\u003cp>我们过去读书，基本只是停留在书里面零散的信息层面，只是“点状”地吸收书里面的信息，对于全书的整体结构和脉络是很难有一个系统认知。如何才能高效阅读和理解作者的整体思想呢？关键词读书法能够让我们在快速掌握全书脉络的同时，也理解不同思维模型是如何组合搭配成一个知识结构，构成整本书的系统脉络的。\u003c/p>\u003cp>how:\u003c/p>\u003cp> 具体而言，关键词阅读法可以分为三步：\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong> \u003cstrong>分析确定作者在书中要解决的核心问题是什么？\u003c/strong>\u003c/p>\u003cp>可以参考封面或封底，序言和后记\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong> \u003cstrong>寻找书中与核心问题相关的关键词有哪些？\u003c/strong>\u003c/p>\u003cp> 看目录；上网搜索别人制作的思维导图\u003c/p>\u003cp>\u003cstrong>3.\u003c/strong> \u003cstrong>这些关键词之间的关系是什么，它们是以什么逻辑解决问题的，有哪些有效策略？\u003c/strong>\u003c/p>\u003cp> 序言里，先了解作者的思路，或者网上搜别人的总结。\u003c/p>\u003cp>找到了这三个问题的答案，我们对作者解决复杂问题的整体策略就会有提纲挈领地认识。\u003c/p>\u003cp>简而言之，就是首先确认书籍的中心思想——讨论什么问题，再看作者用了哪些知识、概念和思维模型分析这个问题，最后把重要的概念、思维模型以关键词的形式找出来，组织成解释问题的知识结构，即关键词网。\u003c/p>\u003cp>（以上是行动步骤建议）\u003c/p>\u003cp>\u003cstrong>技能点：【I】环节提到了学习者可能产生的异议，并给与了预防性讲解。\u003c/strong>\u003c/p>\u003cp> 关键词读书法也有两面性。好处是能够快速掌握全书解决问题的逻辑和结构，形成清晰的思路。不足的地方在于，这样思考只能抓住作者写出来的“显性知识”和看得见的“思维模型”，但这些看得见的思维模型明线背后，有时候还有埋藏得更深得、作者未写出来的“思维暗线”。而这种思维暗线往往和作者的思维方式相关。如果要进一步挖到思维方式的高度，就需要掌握读出“弦外之音”的新读书方法。\u003c/p>\u003cp>where:\u003c/p>\u003cp>所以关键词读书法适用于我们阅读实用类书籍时，需要快速高效整体理解作者的思想和观点，就可以站在作者的角度上对整本书的系统思维逻辑有一个提纲挈领的认识。\u003c/p>\u003cp>【案例讲解】\u003c/p>\u003cp>案例：用关键词法阅读《好好思考》\u003c/p>\u003cp>l 核心问题：如何练就高超学习力？（封面）\u003c/p>\u003cp>换句话说，就是如何构建和运用多元思维模型培养内化成深度思考力从而解决复杂问题？\u003c/p>\u003cp>l 相关关键词：多元思维模型 复杂问题 知识体系\u003c/p>\u003cp>（目录）\u003c/p>\u003cp>l 关键词之间关系：\u003c/p>\u003cp>在序言部分，作者对全书的结构有一个具体的阐述。\u003c/p>\u003cp>第一部分：介绍什么是思维模型，分析它的本质。\u003c/p>\u003cp>第二部分：教你如何高效学习和掌握思维模型。\u003c/p>\u003cp>第三部分：如何把跨学科的思维模型融入一个知识体系。\u003c/p>\u003cp>第四部分：如何综合运用跨学科思维模型解决复杂问题。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A2】\u003c/strong>(分步催化) 4分钟\u003c/p>\u003cp>\u003cstrong>技能点：分步催化中，提问中包括情境或场景，有学习者受启发联想到自己的具体应用场景。（无须分组，在会议软件主界面讨论）\u003c/strong>\u003c/p>\u003cp>大家听了我的例子，可以思考一下你在读书的时候，是如何进行阅读思考的？联系实际生活关键词阅读法还可以运用到哪些场景？每人1-2分钟，时间总共是 5分钟。\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>\u003c/p>\u003cp>京京：读书的时候是逐字逐句读，听了今天的分享，我会把关键词法再逐字逐句读书前用起来，这样可以提前先对作者的核心观点和思想有一个大概的了解。\u003c/p>\u003cp>李跃：我读书的时候从来不读序言这些，今天听了分享，我感觉这部分还是很重要的，要用关键词法先从序言后记、目录这里面先把书的核心问题和关键词找出来，这样对全书的脉络有一个大概理解，我觉得这个方法还是很实用的，不仅仅是读书，像听课参加会议也可以用这个方法对这个学习内容的脉络结构有一个清晰的了解。\u003c/p>\u003cp>\u003cstrong>技能点：分布催化中指令清晰，有学习者根据指令，规划出了以后可以如何做的具体计划。（无须分组，先让学习者写出规划，然后在会议软件主界面分享）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A2】\u003c/strong>（分步催化）\u003c/p>\u003cp>结合工作和学习中的场景，我们应该如何使用关键词法来高效理解作者地思想和观点呢？请大家按照今天学的关键词法，分享自己最近阅读的一本书，写下来核心问题和相关关键词，向大家介绍一下作者的整体思想和观点。会后可以用思维导图分析这本书中关键词之间的关系，总结分析出整本书“关键词网”的脉络结构，整体掌握这本书作者的思想和观点，并写下自己\u003cstrong>以后运用关键词读书法的具体行动规划。\u003c/strong>\u003c/p>\u003cp>介绍的书名：\u003c/p>\u003cp>核心问题：参考封面封底，序言和后记\u003c/p>\u003cp>相关关键词：参考目录\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>\u003c/p>\u003cp>李跃介绍的书名：《目标》\u003c/p>\u003cp>核心问题：如何制定和实现目标的方案（参考封面封底，序言和后记）\u003c/p>\u003cp>相关关键词：信念 目标 计划（参考目录） \u003c/p>\u003cp>京京介绍的书名：《沟通的方法》\u003c/p>\u003cp>核心问题：如何掌握沟通的方法\u003c/p>\u003cp>相关关键词：倾听 沟通的原则 方法 \u003c/p>\u003cp>【结束语】\u003c/p>\u003cp>相信通过刚才的讲解和分享，大家对关键词阅读法有了一个清晰的了解和认知，我们在阅读一本书时，除了可以“点状”吸收知识外，还可以用关键词法对全书的整体脉络结构有一个认知和理解，更好的上升到从全书中找分析逻辑的系统思维，感谢大家今天的陪伴，我的TF2-2拆书过级到此结束，感谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1671424594000,"updated_at":1674273707000,"ria":true},{"id":14677,"topic":"五星笔记法","learn_goal":"","remark":"如果你也有这样的困惑：\n\n（1）如何搭建体系？\n\n学习了很多知识，却零散不成体系，依旧无法解决绝大多数的问题？\n\n（2）如何找到共通的关键？\n\n不同领域和工作之间看似有壁，却往往面临同一种难题？\n\n（3）如何突破瓶颈：\n\n无论哪个领域，工作几年，总会遇到天花板和瓶颈期，却找不到“开窍”的关键？\n\n你需要：\n\n打破学科思考界限，拓展思维模式的格局和边界。认真阅读《好好思考》。\n\n4、全面解析查理·芒格思维模型，打破学科思考界限，拓展思维模式的格局和边界。每个人都有天花板，解决之道往往在另一条路上","level":"TF2-1","duration":30,"status":30,"type":0,"chaishujia":{"username":"石研","city":"石家庄市"},"club":{"name":"石家庄冀城分舵","city":"石家庄"},"prologue":"\u003cp>大家好，我是石研，一个专职在线课程运营官，也是一个终身学习不断精进中的个人成长教练！\u003c/p>\u003cp>\u003cstrong>技能点：在讲解时，通过共享屏幕播放PPT，清晰呈现R原文、I便签核心内容、和A1、A1+指令。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>技能点：学习目标包含了学习者可被观察到/被测量到的行为或动作，线上学习者设计清晰体现了该学习目标。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003ch2>通过跟随我今天的RIA学习，学习者在学习新知识，需要快速理解内容的底层逻辑时，\u003cstrong>能够运用“五星笔记法”，更有效的进行知识梳理和理解\u003c/strong>，让自己下一步有\u003cstrong>更清晰的行动计划\u003c/strong>。\u003c/h2>\u003cp>\u003cstrong>技能点：在FAB介绍法中，能够清晰辨别出聚焦于图书和学习主题的F、A、B。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>【Feature特征】（以书为核心来满足好奇心）\u003c/strong>\u003c/p>\u003ch2>今天我们要拆解的是《好好思考》，这本书是知识管理研究者、“得到”说书人成甲的畅销书，被逻辑思维评选为“中国最会学习的人”， 通过深入解析查理·芒格的\u003cstrong>多元思维模型\u003c/strong>，帮助我们\u003cstrong>用思考打造超强学习力！\u003c/strong>\u003c/h2>\u003cp>\u003cstrong>【Advantage优势】（用比较建立安全感）\u003c/strong>\u003c/p>\u003cp>《好好思考》是\u003cstrong>国内第一本\u003c/strong>研究如何用多元思维模型培养深度思考力的书，这本书不是简单罗列了一堆思维模型，而是作者结合自己10多年的研究经验，从基本原理、搭建知识体系、演示方法案例、拆解思维模型等多角度进行系统讲解论述，提供查理·芒格思维模型的落地方法。结合具体的生活案例解析，配有图示和表格，读起来不枯燥，非常落地实用。\u003c/p>\u003cp>\u003cstrong>【Benefit利益、好处】\u003c/strong>（强调学习者能学到什么以引发兴趣）\u003c/p>\u003cp>\u003cstrong>【B1】（学完本书可得利益）\u003c/strong>\u003c/p>\u003cp>大家有没有遇到过这些情况：你学习了很多知识，却零散不成体系，依旧无法解决绝大多数的问题？这本书将告诉我们如何搭建自己的知识体系。如果如果你发现不同领域和工作之间，往往面临同一种难题？这本书教我们如何找到共通的关键。如果你工作了多年，遇到自己的天花板和瓶颈期，却找不到“开窍”的关键？这本书告诉我们每个人都有天花板，解决之道往往在另一条路上。\u003c/p>\u003cp>走进这本书，拓展思维模式的格局和边界，用思考看见世界的不同。\u003c/p>\u003cp>\u003cstrong>【B2】（学完此片段可得利益）\u003c/strong>\u003c/p>\u003cp>如果你在生活或工作学习中常常羡慕别人，听了一次演讲、参加了一场会议或看完一本书能快速梳理出背后的底层逻辑，提炼出思维模型，并学以致用。而你却学了很多知识，依旧解决不了问题，知道很多道理，依旧过不好这一生，今天大家和我一起学习完拆页片段后，可以学习到用“五星笔记法”深度加工知识，提炼出思维模型，内化形成自己的知识体系，并进行学以致用！\u003c/p>","ratings_count":1,"texts":[{"id":18697,"quote":"\u003cp>现在由我来带领大家拆解一下今天的片段：《好好思考》P85-86，下面我们花2分钟时间看一下原文片段，看完一页可以示意我一下。\u003c/p>\u003cp>选择书籍：《好好思考》\u003c/p>\u003cp>【R阅读原文拆页】\u003c/p>\u003cp>\u003cstrong>技能点：所选图书是实用类或理论类书籍。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【R】所选拆页，包括How的内容；且总内容未超过2页图书内页。\u003c/strong>\u003c/p>\u003cp>主题【页码】P85—86\u003c/p>\u003cp>“五星笔记法”，用笔记挖掘隐性知识！过去很多年，有一个问题一直困惑着我：人人都说，好记性不如烂笔头，我也做过不少笔记，但是除了事后查阅方便一些之外，也没有什么特别的地方。直到有一天，在思考如何能够在短时间内快速理解一次演讲或一篇文章的底层逻辑时，我突然发现，过去我做笔记的方法效率很低的原因是有一个误区：我以为做笔记就要记下重点的句子和观点，以便提醒自己，强化记忆。然而，这根本不是做笔记的核心，做笔记的目的不是记录下别人的想法或观点，而是要借鉴别人的思想和做法，改进我们自己的知识体系，寻找解决问题更有效的策略。换言之，做笔记的目的不是记录别人的知识，而是寻找更有效的解决问题的策略，完善你思考解决问题的知识体系。为了做到这一点，我设计了一个全新的做笔记方法：五星笔记法。 \u003c/p>\u003cp>所谓“五星笔记法”，就是每次做笔记之前，先画出一个五角星，每个角代表一个问题，一共五个问题，我做笔记的过程就是回答这五个问题的过程。五个问题回答完，笔记才算做完了。这个方法背后的核心原理是，别人说出来的东西，你就算记下来，也还是别人的知识。我们只有对别人说出来的东西进行二次深加工，把别人的知识放在自己的知识体系里，把那些启发和收获与自己的经历、接下来的行动相联系，才能真正从别人的做法中提取精华。\u003c/p>","explains":"\u003cp>\u003cstrong>what\u003c/strong>:\u003c/p>\u003cp> 这个拆页说了一个挖掘隐性知识的记笔记的方法：五星笔记法，通过预判内容，记录逻辑，记下疑问启发，提炼思维模型，变成行动，来让我们能快速地理解作者或者演讲者的底层逻辑，化为己用，真正把知识内化成自己的！\u003c/p>\u003cp>\u003cstrong>why\u003c/strong>:\u003c/p>\u003cp>无论是读书，还是学习，或是参加会议听分享，我们都爱通过记笔记来记录下当下我们所看到、听到的内容，以便于我们作为复习所用或者是遇到相关类似问题的时候可以翻出来作为参考所用！但这样大多数只能回忆起部分片断或者是提醒了自己有这么一回事，但真正需要应用落地的时候总会有差那么一点儿吃不透的感觉！这是因为，我们记的都是别人的知识，而没有转化成自己的知识体系，但我们都希望学以致用，因此，我们需要一个新的记笔记法：五星笔记法，让我们通过5个步骤的动作把知识内化，转为己用！\u003c/p>\u003cp>\u003cstrong>how\u003c/strong>:\u003c/p>\u003cp> 如何用“五星笔记法”做笔记呢？一共有以下五个问题，做笔记的过程就是回答这五个问题的过程。\u003c/p>\u003cp>1. \u003cstrong>判内容—预判核心内容\u003c/strong>：判断对方要讲的核心内容是什么？为什么这个内容值得讨论？\u003c/p>\u003cp>2. \u003cstrong>记逻辑—记录讲解逻辑\u003c/strong>：记录对方讲解的逻辑是什么？\u003c/p>\u003cp>3. 记启发—记下疑问启发：这次讨论中，我有什么疑问和启发？\u003c/p>\u003cp>4. \u003cstrong>提模型—提炼思维模型\u003c/strong>：对方的做法想法或者给我的启发点可以提炼为哪些有效策略（思维模型）？\u003c/p>\u003cp>5.\u003cstrong>变行动—变成具体行动\u003c/strong>：这次讨论中给我的启发，哪些可以立刻变成下一步行动，如何运用到自己的生活里？\u003c/p>\u003cp>（以上是行动步骤建议）\u003c/p>\u003cp>\u003cstrong>where\u003c/strong>:\u003c/p>\u003cp>这个方法适用于读致用类书籍或者听演讲分享、参加会议及课堂学习，总之能用到所有给我们有启发的场合，作用就是帮我们挖掘隐性知识，但休闲打发时间看书的时候就不太合适了。\u003c/p>\u003cp>【案例讲解】\u003c/p>\u003cp>\u003cstrong>技能点：【I】的讲解，拆书家提到了不那么做的坏处，找出人们的通常做法，并举出了具体的反面例子，而且使用了片段包含的技能把反面例子加工成正面例子。\u003c/strong>\u003c/p>\u003cp>案例：五星笔记法解读“五星笔记法”\u003c/p>\u003cp>\u003cstrong>l\u003c/strong> \u003cstrong>平常笔记法\u003c/strong>（储藏式伪收藏的假学习）反面例子：\u003c/p>\u003cp>我感觉这个笔记法非常棒，用通常记笔记的方法，我会怎么做呢？抄写五个方法步骤，画出五星标注好，以备以后查阅学习，最多加一句，这个笔记法太好了。就没有然后了，等着可能需要的时候翻出来能记住这五步已经很不错了，仅此而已。（负面案例）\u003c/p>\u003cp>\u003cstrong>l\u003c/strong> \u003cstrong>五星笔记法\u003c/strong>（内化知识为己用的真学习）：\u003c/p>\u003cp>\u003cstrong>1.预判核心内容：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>判断对方要讲的核心内容是什么？为什么这个内容值得讨论？\u003c/strong>\u003c/p>\u003cp>确定主题，角色带入，若你如何讨论这个主题？\u003c/p>\u003cp>成甲老师讲了五星笔记法的核心原理：如何挖掘隐性知识，将知识内化，形成思维模型，进行实践运用，以及操作执行的模型步骤！\u003c/p>\u003cp>如果我是作者，会用更有趣直观的图示加文字加案例分析的形式来展现和讨论！\u003c/p>\u003cp>\u003cstrong>2.记录讲解逻辑：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>记录对方讲解的逻辑是什么？\u003c/strong>\u003c/p>\u003cp>推理逻辑比结论重要！把逻辑、关键词推理思考过程记录下来！\u003c/p>\u003cp>五星笔记法从是什么，到背后为什么这么操作，以及我的下一步行动由浅入深影响到自己，把别人的知识一步步知识内化形成自己的知识体系！\u003c/p>\u003cp>\u003cstrong>3.\u003c/strong> \u003cstrong>记下疑问启发：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这次讨论中，我有什么疑问和启发？\u003c/strong>\u003c/p>\u003cp>内容有何疑问？想法有何局限性？哪些观点有启发？我还联想到哪些相关案例或经验？\u003c/p>\u003cp>记录之后要花时间加工分析。\u003c/p>\u003cp>启发：用五角星的形式，特别形象，具体的展示了笔记法\u003c/p>\u003cp>五步流程有点多，需要运用时间记忆理解和运用。\u003c/p>\u003cp>和拆书法有点类似，理解原文，结合自己过往的经历以及下一步行动规划。\u003c/p>\u003cp>\u003cstrong>4.\u003c/strong> \u003cstrong>提炼思维模型：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>对方的做法想法或者给我的启发点可以提炼为哪些有效策略（思维模型）？\u003c/strong>\u003c/p>\u003cp>继续追问：这个方法解决什么问题？这个策略为什么有效？这个策略的来源依据是什么？把新启发点和过去知识点及原理进行联系！\u003c/p>\u003cp>解决了字面记录笔记，只看到表面现象和文字，不深入容易忘记无法实践运用的问题。\u003c/p>\u003cp>从表象到内在逻辑，到内在逻辑和自己之前旧知识的联系，以及未来的行动规划发展。\u003c/p>\u003cp>\u003cstrong>5.\u003c/strong> \u003cstrong>变成具体行动：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这次讨论中给我的启发，哪些可以立刻变成下一步行动，如何运用到自己的生活里？\u003c/strong>\u003c/p>\u003cp>在参加学习聊天，看书，听课等等的事情上运用五星笔记法突破表象，深入内在本质和自己过往知识和经验相结合，深入思考，形成自己的思维体系！（附“五星笔记法”笔记模板，石研绘制）\u003c/p>\u003cp>（以上是与行动步骤相对应的案例）\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】\u003c/strong>(激活过去的经验) 4分钟\u003c/p>\u003cp>\u003cstrong>技能点：【A1】显像提问清晰，其中包含具体的情景。刚才又学习者分享了自己根据这个场景联系出的过往情景或具体经验。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【显像提问】\u003c/strong>\u003c/p>\u003cp>大家听了我的例子，也了解到在学习新知时或者需要快速梳理理解一次会议、一次课程、一本书一篇文章时，我们可以用五星笔记进行记录和学习，那么接下来请回想一下在过去的一个月里，你有没有对哪些你刚刚接触学习的知识点印象深刻的，我们可以分享一下自己是如何做笔记进行学习的。每人1-2分钟，时间总共是 5分钟。\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>（失败案例）\u003c/p>\u003cp>\u003cstrong>超先森\u003c/strong>：共读《反脆弱》读到第4章，选择性=不对称性+理性这部分知识，以前也学过类似的知识，确实就没有用起来。平时记笔记会用关键词做个记录，但是没有什么效果。今天听完分享，对我触动很大，我以后要把“五星笔记法”用起来！\u003c/p>\u003cp>\u003cstrong>小诚\u003c/strong>：我主要是听会议做记录，以前我记笔记只记录和自己相关的，不相关的记都不记。\u003c/p>\u003cp>\u003cstrong>技能点：【A1+】反思加工指令清晰。刚才又学习者根据指令联系出了假如再遇到同样情况时，自己的具体做法。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A1+】\u003c/strong>（反思加工）\u003c/p>\u003cp>结合工作和学习中的场景，我们应该如何使用五星笔记法呢？请大家按照今天学的方法，分享自己未来如果再遇到学习新知识时或者需要快速理解一篇文章、一场演讲、一次会议的底层逻辑时，将如何使用“五星笔记法”进行记录笔记和深度学习？谈谈具体的行动和做法。\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>（反思加工的案例）\u003c/p>\u003cp>\u003cstrong>小诚\u003c/strong>：疫情防控的主题会议\u003c/p>\u003cp>\u003cstrong>预判核心内容\u003c/strong>：疫情防控如何去做?\u003c/p>\u003cp>\u003cstrong>记录讲解逻辑\u003c/strong>：听的时候需要注意和分析：哪部分是我需要去做的和需要注意的，哪些是其他部门需要注意的，大概整理一下会议逻辑。\u003c/p>\u003cp>\u003cstrong>记录疑问启发\u003c/strong>：在记录过程中针对自己的这部分有什么疑问和启发，把它记录下来。\u003c/p>\u003cp>\u003cstrong>提炼思维模型：\u003c/strong>提炼所有的这些形成行动方面的思维模型。\u003c/p>\u003cp>\u003cstrong>变成具体行动：\u003c/strong>行动变得简单、更有框架一些，先做什么后做什么，更加清晰。\u003c/p>\u003cp>【结束语】\u003c/p>\u003cp>相信通过刚才的讲解和分享，大家对五星笔记法已经越来越熟悉，再遇到学习新知识，需要快速高效理解一篇文章、一场演讲、一次会议的底层逻辑时，要通过五星笔记法来提炼思维模型，学以致用，知行合一。感谢大家今天的陪伴，我的TF2-1拆书过级到此结束，感谢大家！\u003c/p>\u003cp>\u003cstrong>技能点：总时长没有少于25分钟，没有超过30分钟。\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1669565040000,"updated_at":1670541271000,"ria":true},{"id":13828,"topic":"还不会记笔记？一个方法帮你摆脱无效笔记","learn_goal":"","remark":"《好好思考》是一本写给终身学习者的书，对查理·芒格的思维模型进行了全面的解析，并提供了很多有效的学习方法和思考模型， 可以教会我们如何从思维模型入手，构建一个全新的学习思考体系，进而练就超强的学习力，书中从多个角度讲述了如何搭建知识体系以及实战演练的方法。本书的豆瓣评分7.9分。作者成甲据说是逻辑思维最会学习的人。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"小金在路上","city":"郑州市"},"club":{"name":"郑州轩辕分舵","city":"郑州"},"prologue":"\u003cp>【自我介绍】\u003c/p>\u003cp>各位拆书帮的前辈们，大家好！我叫李金泽，大家可以叫我小金。首先用三个标签介绍我自己。\u003c/p>\u003cp>一，我是一名95后；\u003c/p>\u003cp>二，我是一名心理学的实践者；\u003c/p>\u003cp>三，我是一名知行合一理念的践行者，每日有习得必有实践和输出，这也是我参加完拆书营后的收获。\u003c/p>\u003cp>平时喜欢烘焙、阅读和辩论，日后希望有机会跟在坐的各位相互交流,共同进步！\u003c/p>\u003cp>【拆书法介绍】\u003c/p>\u003cp>今天到场的有一些伙伴是第一次来到拆书帮，所以简单跟大家介绍一下拆书帮和拆书法。拆书法是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心而不是以知识为中心，要把知识与学习者的经验相关联，从而规划具体的运用。\u003c/p>\u003cp>拆书法也分为个人学习的拆书法和组织学习的拆书法。个人学习的应用是便签法，通过阅读原文、复述拆页内容、回顾过往经历、规划行动四个步骤得以实现，产生读一本书就能达到参加相同主题培训的效果；组织学习的应用是一位拆书家把一本书加工成一次现场学习，通过拆书家精心的设计，让学习者更轻松、高效地激活经验或者规划行动，也就是把知识拆为己用。从学习者的效果来衡量的话，一位拆书家创造的价值不亚于一位培训师。\u003c/p>\u003cp>而 “拆书帮”是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵。拆书帮是非盈利性的学习组织，其使命是帮助更多学习爱好者成长为拆书家。我个人也是受益者之一，在这里要感谢我师父墨小多的指导，在拆书营给了我很多建议和鼓励。\u003c/p>\u003cp>【技能点1：如何介绍拆书帮】\u003c/p>","ratings_count":1,"texts":[{"id":17851,"quote":"\u003cp>今天给大家带来的是成甲老师非常有名的一本书，叫做《好好思考》，主要讲的如何构建终身学习者的底层思维，实用性非常强。拆解的片段的主题是“五星笔记法”。下面请大家阅读这个片段，时间两分钟，读完请举手示意。\u003c/p>\u003cp>【技能点2：请学习者阅读拆页】\u003c/p>\u003cp>\u003cstrong>《好好思考》 P75\u003c/strong>\u003c/p>\u003cp>做笔记的目的不是记录别人的知识，而是寻找更有效的解决问题的策略，完善你思考解决问题的知识体系。为了做到这一点，我设计了一个全新的做笔记方法：五星笔记法。\u003c/p>\u003cp>所谓“五星笔记法”，就是每次做笔记之前，先画出一个五角星，每个角代表一个问题，一共五个问题，我做笔记的过程就是回答这五个问题的过程。五个问题回答完，笔记才算做完了。\u003c/p>\u003cp>这个方法背后的核心原理是，别人说出来的东西，你就算记下来，也还是别人的知识。我们只有对别人说出来的东西进行二次深加工，把别人的知识放在自己的知识体系里，把那些启发和收获与自己的经历、接下来的行动相联系，才能真正从别人的做法中提取精华。\u003c/p>\u003cp>而五星笔记法中的五个问题分别是：\u003c/p>\u003cp>1．预判对方要讲的核心内容是什么，为什么这个内容值得讨论。\u003c/p>\u003cp>2．记录对方讲解的逻辑是什么？\u003c/p>\u003cp>3．这次讨论中，我有什么疑问和启发？\u003c/p>\u003cp>4．对方的做法、想法或者给我的启发点，可以提炼为哪些有效策略（思维模型）？\u003c/p>\u003cp>5．这次讨论中给我的启发，哪些可以立刻变成下一步的行动？我如何把它们运用到自己的生活里？\u003c/p>\u003cp>好，看大家差不多都看完了，没有看完的小伙伴也没关系，我会带领大家对该片段详细解读。\u003c/p>\u003cp>【技能点3：选书与选拆页】\u003c/p>","explains":"\u003cp>如何才能摆脱低效的学习方式呢？五星笔记法给了我们答案。\u003c/p>\u003cp>WHAT：这是一个让学习更有效的思考方法。通过对知识的二次加工，取其精华，把知识真正内化成自己的内容，从而做到融会贯通，并获得最适合自己的后续行动方案。\u003c/p>\u003cp>WHY：如果不使用五星笔记法，而使用传统的记笔记方式，我们对知识的理解就会浮于表面，还会陷入低效学习的状态，难以达到想要的学习效果。如果使用五星笔记法，我们对学习知识的理解的就会更加深刻，有利于形成自己的知识体系，真正做到学以致用。\u003c/p>\u003cp>HOW：五星笔记法其实就是由5个问题组成的思考系统，我们需要通过以下五个问题，来填充笔记的内容。\u003c/p>\u003cp>1、学习前预判核心内容，即思考如果是我来讲这个内容，有哪些内容是想要重点关注的；\u003c/p>\u003cp>2、学习时找到并记录讲解的逻辑，即利用关键词找到前后的逻辑关系；\u003c/p>\u003cp>3、及时记录学习中的疑问和启发，还可以加上自己的分析；\u003c/p>\u003cp>4、把新知和启发与其他知识关联起来，并总结提炼出之后可以实践的方法；\u003c/p>\u003cp>5、根据启发写出下一步行动，即如何运用到自己的生活。\u003c/p>\u003cp>WHERE：适用于需要做笔记的各种场景，如听课学习笔记、阅读笔记、工作讨论笔记等等。但是如果是单纯的数据、事件记录则不需要使用五星笔记法。\u003c/p>","interaction":"\u003cp>为了帮助大家更好的理解，我分享一个我自己的亲身经历：2020年，我参加了非常多的知识付费课程。我本来觉得2020是我成长最快的一年，是很不错的一年。直到我2020年12.31号，听到了一场直播，一名同样是98年的女生，她没有参加任何的训练营，却在短短4个月的时间建立了自己的个人品牌，创办了自己的公司和社群产品，目前已经有几百名付费社员。而做到这一步，只是因为她读书做到了知行合一。这给了我当头一棒，我以为我参加训练营已经深度思考，拿优秀就是真的做得不错，殊不知依然还是在用被动的学习方式学习。【背景】\u003c/p>\u003cp>在后来的反思中，我回顾了我参加训练营的学习方式，其实跟在学校没有差别，就是听课然后做笔记，老师让做什么我就做什么。什么思维导图，总结笔记无非是把核心内容换了一种展现形式，虽然在社群的设计下，我有思考有成长，但是花费了大量的金钱，学习效果却被一个自学的人远远甩在身后。这就好像我花了很多钱给孩子报了名师辅导班，结果他还不如邻居家啥班也没报的孩子成绩好一样。【痛点】\u003c/p>\u003cp>就是因为我们在学校习惯了低效的学习方式，记笔记方式，所以才会导致被动的接受的知识，而弱化了理解和思考。但是当今社会，不管是应试教育，还是成年人的学习，实践才是检验真理的唯一标准。【总结】\u003c/p>\u003cp>在之后的学习中，当我看到想要实践的书或者文章时，不会再做传统笔记，而是按照五星笔记的步骤做笔记，在学习提炼后获得模板和行动方案。【行动】\u003c/p>\u003cp>1、根据标题判断核心内容，想想我写这个话题的话我会写什么？（比如今天的如何高效记笔记你会写什么？）\u003c/p>\u003cp>2、找到作者的写作的关键词逻辑，并做记录；\u003c/p>\u003cp>3、记录看文章时的疑问和启发点，简单分析；\u003c/p>\u003cp>4、根据学到的内容和收获的启发总结出一套实践模板；\u003c/p>\u003cp>5、根据启发写出下一步行动方案，并实践。\u003c/p>\u003cp>【技能点4：当众表达你的便签】\u003c/p>\u003cp>以上就是五星笔记法的全部内容，感谢大家的聆听与陪伴，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1658750626000,"updated_at":1659061251000,"ria":true},{"id":13282,"topic":"寻找“贵人”四步法","learn_goal":"","remark":"贵人，就是有更好的资源、能力、知识，能更好解决问题的人。他们能够给我们更好的机会，帮助我们在生活、学业、事业上获得更快的发展和提升。强联系的人提供安全感，弱联系的人提供信息和机会。因此，我们可以不等熟人介绍，主动去寻找贵人。今天，我们将用15分钟时间，一起学习如何从心理到方法上寻找到自己的贵人。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"Luna0511","city":"镇江市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>各位拆友大家好！我是今天的拆书者Luna。三个标签介绍一下自己，我是一个晚熟的人、易经爱好者，还是一名教育诊疗推进者。我刚刚从RIA训练营结业，本月报名了TF1-1和TF1-2的拆书过级，希望可以趁热打铁，更新标签，早日成“家”。下面我介绍一下拆书帮。\u003c/p>\u003cp>拆书帮于2013年正式成立，网上有人说，这是最好的读书江湖。拆书帮是基于拆书法的学习爱好者社群，是一个非盈利性青年组织，旨在帮助更多学习爱好者成长为拆书家。目前拆书家正式分舵覆盖全国28个省，60多座城市，正式分舵50多家。\u003c/p>\u003cp>接下来我来介绍一下拆书。\u003c/p>\u003cp>“拆书”是一种学习方法，它有别于传统的学院式学习，是以提升能力、解决问题为目标的成人学习方法。强调以学习者为中心而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。分为个人学习的拆书法和组织学习的拆书法。个人学习通过运用RIA便签学习法，让人读一本致用类图书就能达到同主题培训的效果。组织学习的应用就是我们的线下拆书，由一位拆书家把一本书加工成一场现场学习，引导和促进一群人把知识拆为己用。这就是我们现在正在做的事。\u003c/p>\u003cp>我今天的拆页来自于成甲的《好好思考》，这本书主要教读者如何建立自己的思维模型。是我读过的最震撼的书，是一本可以帮助我们提升思维能力的书。下面请大家花一分钟时间阅读今天的拆页内容。\u003c/p>","ratings_count":4,"texts":[{"id":17281,"quote":"\u003cp>R便签：\u003c/p>\u003cp>    后来，双方（小马宋和罗振宇）的合作就奠定了基础，再后来有了这层关系，罗辑思维“时间的朋友”跨年演讲时又找到了小马宋进行策划，双方进行了更深入的合作。\u003c/p>\u003cp>    这是小马宋认识罗振宇的大概过程。我们简单梳理一下，小马宋的行动可以分为四个阶段：\u003c/p>\u003cp>1、 小马宋对超级人脉感兴趣；\u003c/p>\u003cp>2、 寻找接触超级人脉的机会；\u003c/p>\u003cp>3、 接触后寻找自己相对的比较优势；\u003c/p>\u003cp>4、 找到契合点，推动双方合作。\u003c/p>\u003cp>这四个阶段就是一个利用自身特长不断寻找高手，利用比较优势最终建立合作的过程。\u003c/p>","explains":"\u003cp>看样子大部分同学已经阅读完了，没有读完的也没关系。下面我从what.why.how,where几个方面来跟大家分享一下我对这对拆页的理解：\u003c/p>\u003cp>Part I【what】\u003c/p>\u003cp> 寻找贵人四步法，是主动寻找超级人脉并用自己的比较优势与之建立合作的行为模式。\u003c/p>\u003cp>关键词：超级人脉，比较优势。\u003c/p>\u003cp>超级人脉指的是能解决各种问题的高手，他们可能有优秀的思维品质，也可能有高级人脉资源和 \u003c/p>\u003cp>行业影响力，也可能有独特的行事方式。在下面的拆解过程中，“贵人”指的也是“超级人脉”。\u003c/p>\u003cp> 比较优势是经济学中的一个思维模型，专业解释是，一个生产者以低于另一个生产者的机会成本 \u003c/p>\u003cp> 生产一种商品的行为。打个比方说，某件事上，你比小王做得好，是你的优势。但是这时候你有\u003c/p>\u003cp>更重要的事情要做，你就把这件事交给了小王，这对你们双方都是好事。这时候，小王就拥有了\u003c/p>\u003cp>在这件事情上的比较优势。\u003c/p>\u003cp>Part II【why】\u003c/p>\u003cp> 1、超级人脉是我们生活和事业上的贵人，能四两拨千斤，帮我们事半功倍解决问题。\u003c/p>\u003cp>2、超级人脉能带领我们加入一个更高质量的人脉网络，获取更有价值的信息和资源，为我们日\u003c/p>\u003cp> 后的学习、生活、事业提供更多的优势。\u003c/p>\u003cp>Part III【How】\u003c/p>\u003cp> 接下来我们来了解一下如何寻找贵人并与之建立合作。\u003c/p>\u003cp>Step1 “心里有火”。你得非常非常结识某个贵人。这里要更新一个观念，就是不要仅仅通过熟人的介\u003c/p>\u003cp> 绍去寻找贵人。熟人不一定了解你的比较优势，他们更不知道怎么运用你的比较优势。现在，我 \u003c/p>\u003cp>们完全可以通过网络找到超级人脉的信息。\u003c/p>\u003cp>Step2 “眼里有光” 。主动寻找接触超级人脉的机会，哪怕是微不足道的小机会。比如，某个超级人脉签\u003c/p>\u003cp>名售书了，赶紧去买书啊；某个超级人脉去某地做大型讲座了，赶紧去报名志愿者啊；知道了某\u003c/p>\u003cp>超级人脉在哪个网络社群活动，赶紧加入啊……如果这个超级人脉非常厉害，别指望三两次能搞\u003c/p>\u003cp>定，要多关注他，他出席的公众活动，你都尽可能去参加，把它当成考大学、求职去做。如果这\u003c/p>\u003cp>个超级人脉没有那么厉害，说不定三五次就能搞定了。\u003c/p>\u003cp>Step3 “身上有宝”。寻找自己相对的比较优势，这是很关键的一点。好不容易在超级人脉那里混了个\u003c/p>\u003cp> 脸熟，人家凭什么帮助你？这时候，你得提供特有的价值，就是比较优势。先看看自己有什么本\u003c/p>\u003cp>事是超过身边大部分人的，再看看这些本事里面有哪一个可以给对方提供价值。比如，如果他的\u003c/p>\u003cp>孩子恰逢青春期叛逆，你或者你的配偶恰好有一套独特的办法处理青春期问题。或者对方父 母\u003c/p>\u003cp>身体不好，久治不愈，你正好认得一个大名医能治疗类似的病症。或者，他的英文秘书生病了，\u003c/p>\u003cp>你正好做他的随行翻译……\u003c/p>\u003cp>Step4 “手上有力”，推动合作。这是一次双方的价值交换时期。一开始的合作，要肯吃亏，即使赔本\u003c/p>\u003cp> 也要接受。这是你真正加入超级网络的机会，你吃亏花的是必要的社交费用。\u003c/p>\u003cp>Part IV【where】\u003c/p>\u003cp> 1.这个方法适用于主动寻找事业上贵人、生意上伙伴、人生导师，甚至年轻人找对象。\u003c/p>\u003cp>2.不适用于双方悬殊太大。如果悬殊太大，比如我的某个同事想要结识赵丽颖并且跟她结婚，这\u003c/p>\u003cp> 个方法就不太好使了。他也许可以用这个方法去结识局长的女儿。 \u003c/p>\u003cp>3.如果你没有比较优势，没有价值输出，光靠讨好、献殷勤，也不好使。\u003c/p>","interaction":"\u003cp>【A1便签】 \u003c/p>\u003cp> 下面我跟大家分享一个我曾经运用这个四步法找到我的贵人的经历：\u003c/p>\u003cp> 2017年，我看了一本教育类书籍《教育智慧从哪里来》，作者是北京的王晓春老师。他在书中提出的观点相当吸引我，比如他说：为什么人家觉得医生专业而教师不专业呢？因为老师的那些招，家长大部分都会，甚至连工地上的工人都懂。你缺少专业的技术，你没有一把好使的枪，没有一套严密的思维逻辑。我非常想认识他，可是当时，我没有资格、也没有机会认识他。\u003c/p>\u003cp> 巧了，2018年，我们教育局邀请他做现场大规模培训，听众好几百人。尽管距离是近了，但是能靠近他并且为他服务的也是局一级领导，没我什么事啊。我总不好意思当着好几百老师的面到台上给他倒水献殷勤啊。培训结束后，领导说，暑期将组织三十个对教育诊疗真正感兴趣的老师去北京封闭培训一周。\u003c/p>\u003cp> 机会来了，接下来的几个月里，我把王老师所有的书都读了一遍，很认真哦，并且把有不同意见和疑问的地方都列举了出来，积极发到论坛上讨论。暑期，我真的被选到北京去啦，这一次王老师认识我了，知道有个叫Luna的看过他所有的书，在培训会上，别人的思路堵塞的时候，他会问：Luna，你有什么新的想法？2019年，我们又去北京参加暑期培训，这一次，我是讲师之一。2020年，教育局再次组织五个人去北京，为国家教育行政学院录制了教育诊疗培训视频。现在，王老师团队有七八个人，我是其中之一。\u003c/p>\u003cp>【A2便签】\u003c/p>\u003cp> 拆书帮的价值观是拆为己用、反求诸己。我想把今天的“寻找超级人脉四步法”拆为己用，用它来结识我想交往的一对夫妻，然后建立合作---写他们的故事。\u003c/p>\u003cp> 镇江最近来了一对旅居者琪哥夫妇，他们已经成了网红，发在百度里的vlog天天被催更，我对他们的生活方式特别感兴趣，想跟他们交朋友。我给他们的vlog留了言，但是他们没有回复我。下周我想用这个寻找超级人脉的办法找到他们，并试试能不能联系合作，拍摄微电影。因为我想利用五年时间，写五十个有趣的人物故事，他们是我觉得有趣的人。\u003c/p>\u003cp> 首先要做的是寻找接触到他们的机会。他租住在我家附近的一个小区，目前活动范围就在我家附近。我要每天看他们vlog里的行走路线，然后推测他们第二天可能要去的地方。晚饭后，我们去他们小区出口和可能去的路上散步，争取偶遇。另外，再看看抖音和B站里有没有他们发的资源，如果有，继续关注。\u003c/p>\u003cp> 建立了最初的联系后，我要提供我的比较优势。他们一直在发vlog，并让大家点赞转发，说明他们在意影响力。我有朋友在电视台，也有做电影广告的朋友，可以帮助他们扩大影响，这些是我的比较优势。\u003c/p>\u003cp> 总结一下，寻找超级人脉四步法是通过“心里有火—有渴望；眼里有光---有行动；身上有宝---有优势优势；手上有力---推动合作”四个步骤来主动寻找超级人脉并与之建立合作。而不是等熟人介绍。找到有趣、有用的人，得有点不同的法子。\u003c/p>\u003cp>以上是我今天的分享，感谢大家的参与，谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1650030672000,"updated_at":1650178154000,"ria":true},{"id":12788,"topic":"提炼思维模型","learn_goal":"","remark":"好好思考》是国内第一本研究如何用多元思维模型培养深度思考力的书，这本书不是一堆思维模型的简单罗列，而是作者结合自己10多年的研究经验，从基本原理、搭建知识体系、演示实战方法等多个角度系统讲解论述，提供查理·芒格思维模型的落地方法。结合国人生活案例解析，贴近生活，行文流畅，读起来不枯燥","level":"TF2-4","duration":60,"status":30,"type":0,"chaishujia":{"username":"徐徐","city":"石家庄市"},"club":{"name":"石家庄梧桐分舵","city":"石家庄"},"prologue":"\u003cp>\u003cstrong>拆书技能点1：拆书活动前，已发送《拆书预备表》给观察家，且内容填写准确、完整。\u003c/strong>\u003c/p>\u003cp>大家好，我是徐徐，现在开始TF2-4的拆书过级。用三个标签介绍下自己，互联网产品经理、个人成长实践者和不断升级的拆书家。\u003c/p>\u003cp>为了方便今天拆书活动的讨论环节，我们对线上人员进行分组。\u003c/p>\u003cp>\u003cstrong>拆书技能点2：选择图书是实用类或理论类图书\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书技能点5：在FAB介绍法中，能够清晰辨别出聚焦于图书和学习主题的F、A、B。\u003c/strong>\u003c/p>\u003ch2>今天我们要拆解的是《好好思考》，这本书是知识管理研究者、“得到”说书人成甲的畅销书， 通过深入解析查理·芒格思维模型，帮助我们用思考打造超强学习力！F\u003c/h2>\u003cp>《好好思考》是国内第一本研究如何用多元思维模型培养深度思考力的书，这本书不是一堆思维模型的简单罗列，而是作者结合自己10多年的研究经验，从基本原理、搭建知识体系、演示实战方法等多个角度系统讲解论述，提供查理·芒格思维模型的落地方法。结合国人生活案例解析，贴近生活，行文流畅，读起来不枯燥。A\u003c/p>\u003cp>如果你学习了很多知识，却零散不成体系，依旧无法解决绝大多数的问题？这本书将告诉我们如何搭建自己的体系。如果你发现不同领域和工作之间，往往面临同一种难题？这本书教我们如何找到共通的关键。如果你工作了多年，遇到自己的天花板和瓶颈期，却找不到“开窍”的关键？这本书告诉我们每个人都有天花板，解决之道往往在另一条路上。\u003c/p>\u003cp>走进这本书，拓展思维模式的格局和边界，用思考看见世界的不同。B \u003c/p>\u003ch2> \u003c/h2>\u003cp>今天我们学习《好好思考》中的两个片段，都是与提炼思维模型有关。\u003c/p>\u003cp>如果你喜欢看人物传记，积累了一些有启发的故事，却提炼不出故事背后的思维模型，更不知道如何与现在的生活场景关联，那么第一个片段可以帮到你。\u003c/p>\u003cp>如果你在生活或工作学习中常常羡慕别人，听了一次演讲、参加了一场会议或看完一本书能快速梳理出背后的底层逻辑，提炼出思维模型，并学以致用。而你却苦于偷师无门，找不到门道，那么第二个片段五星笔记法会帮助你。B1\u003c/p>\u003cp>\u003cstrong>拆书技能点4：2个学习目标均包含学习者被观察到/被测量到的行为或动作，且有逻辑关系，现场的2个RIA设计都清晰体现了各自的学习目标。\u003c/strong>\u003c/p>\u003cp>第一个片段的学习目标是在跟随我完成本次RIA学习后，大家能利用从源头思考的思维模型时，找到自己过往的具体经验，并通过从源头思考的思维模型，加工出更好的做法。\u003c/p>","ratings_count":1,"texts":[{"id":16732,"quote":"\u003cp>\u003cstrong>拆书技能点3：2个拆页的【R】，至少一个包含How的内容；有一定的逻辑关系，比如递进关系；且总内容未超过4页图片内页。\u003c/strong>\u003c/p>\u003cp>第一个片段来自于《好好思考》。请大家用2、3分钟的时间认真阅读手中的拆页，完成后麻烦小伙伴举手示意我。\u003c/p>\u003cp>选书：《好好思考》\u003c/p>\u003cp>拆页1：p48-49页\u003c/p>\u003cp>人物传记以故事的形式还原当事人当初面临的问题、做过的努力乃至这些做法带来的影响，这正是我们挖掘思维方式的材料。\u003c/p>\u003cp>举个例子，古罗马历史上，有一位伟大的人物，叫恺撒。他一生取得的成就，超越了同时代所有人，以至于千年之后的今天人们都熟知这个名字。那恺撒究竟有哪些思维方式不同于常人呢？\u003c/p>\u003cp>带着这个好奇，我在盐野七生的著作《罗马人的故事》里寻找关于恺撒大帝的故事。恺撒的一次经历，给我很大启发：\u003c/p>\u003cp>故事发生于公元前49年，恺撒在和九万敌军对垒时，突然天气异变。\u003c/p>\u003cp>原本应该是干旱季节的地中海地区，罕见地下起了暴雨。如果是平日，下大雨对于习惯野外作战的恺撒军队而言，也不是大问题。可是这次情况却不一样，因为恺撒的三万军队正好处在两条河流中间的三角洲地带。\u003c/p>\u003cp>连日的大雨让河水暴涨，恺撒的军队被困在河水包围形成的孤岛里，连粮食都运不进来。\u003c/p>\u003cp>现在，部队粮食已经所剩不多，可是暴雨继续肆虐，持续多日，完全没有好转的迹象。再这样下去，恺撒的三万将士还没打仗就得先饿死。\u003c/p>\u003cp>河对岸就是三倍于自己的敌军，他们吃着面包，看着被围困的恺撒军队，哈哈大笑。恺撒进入了“无路可走的绝境”。敌军司令官甚至已经派人向首都送出捷报了。\u003c/p>\u003cp>在军事史上，由于天气导致战斗失败的案例不胜枚举。\u003c/p>\u003cp>就当所有人都认为恺撒要失败的时候，恺撒突然想出一个绝妙的办法：\u003c/p>\u003cp>他让战士们秘密地在湍急的河流的上游开掘新河沟，把河水导向敌军。结果，河道改变，不仅三万人的生存困局被打破，而且，暴雨和洪水转而围困住了九万敌军。要知道，九万人被困吃饭的问题可远比三万人麻烦得多。\u003c/p>","explains":"\u003cp>\u003cstrong>拆书技能点6：2个拆页的【I】，涵盖了二级的4种讲解引导技巧：1）强调不那么做的坏处，2）给出了学习者可能异议的预防性讲解，3）细化了原文行动建议的步骤4）根据原书中案例脉络，给出了更贴近实际的例子。\u003c/strong>\u003c/p>\u003cp>好，大家都读完了，下面我带领大家拆解一下这个片段。\u003c/p>\u003cp>这个片段的主旨是通过恺撒化险为夷的故事，告诉我们在遇到困境无计可施时，如何通过改变思维方式，从问题的源头出发解决困境，扭转局势。What\u003c/p>\u003cp>面对恺撒这样的困境大多数人都会束手无策，为什么恺撒能想到解决办法？可能源于他另一种思维方式，为什么我面临的一定是困境？为什么我一定要摆脱困境呢？我面对的环境能不能转化为优势，能不能借助天气战胜对方？why\u003c/p>\u003cp>恺撒的做法让我提炼出了一个从源头解决困境的解决问题模型\u003c/p>\u003cp>第一步：质疑我们提出的问题本身，重新定义问题。\u003c/p>\u003cp>是不是我们要解决的问题，本身就是错的呢？为什么暴雨给我带来的一定是困境呢？\u003c/p>\u003cp>第二步：从困境的源头思考问题，改变源头。\u003c/p>\u003cp>洪水的源头是暴雨，我能不能改变暴雨？不能？我能改变什么？我可以改变上游洪水的方向，于是凯撒安排战士在上游重新开挖河道，改变河道的方向，把洪水的困境转给了对方。how\u003c/p>\u003cp>这个片段是恺撒穿越千年送给我们的思维模型的礼物，你可能担心故事太过遥远，又是关于行军打仗的场景，是不是适合我们日常生活场景呢？(异议)\u003c/p>\u003cp>下面举一个生活中的案例来回答这个疑问，或许能让你联想到更多的应用场景。\u003c/p>\u003cp>这个案例发生在我家天天6岁的时候，当时他们学了三个多月的国际象棋就报名参加了专业比赛，与他们对弈的很多都是专业棋手，甚至学习长达三年之久。\u003c/p>\u003cp>原本就根基浅底子薄，没有比赛的经验，这次遇到了很多专业选手，加上赛制是嬴对嬴，输对输，一直这样循环积分，非常激烈。\u003c/p>\u003cp>平日里，他们之间也互相下棋，尽管也会有输赢，孩子们很快就释然了。但是放在正式的比赛里，每场比赛都将结果公布，6岁的孩子完全没有准备好面对被众人围观的输赢。有的孩子连输了两场就开始情绪低落，甚至哭起来。\u003c/p>\u003cp>残酷激烈的赛制把孩子们的自信心很快就消磨没了，有一场三个孩子都输了，其中一个孩子自尊心比较强，哭着的对妈妈说“为什么我已经很努力了，却一直都赢不了！” 尽管家长一直安慰孩子输赢不重要，可是孩子却无法平复情绪，眼看下一场比赛就要开始了。\u003c/p>\u003cp>就当所有家长都无计可施时，我却想到了一个绝妙的办法：从源头重新定义了输赢，让小朋友快速化解了负面情绪。我对小朋友说，比赛输了，你可以学会对手的招式，你学了别人的绝招，下次可以用这招打败别的小朋友，你实际是赢了。如果比赛赢了，说明你技高一筹，所以无论如何，你都是赢的。那个小朋友瞬间明白了，一边往赛场跑一边说：”我知道怎么打败对手了”。要知道，只要方法对，孩子们的情绪变化比翻书还快。（意译案例）\u003c/p>\u003cp>从源头解决困境的思维模型，适用于与人发生冲突时，从源头挖掘别人真正的需求和问题所在；也适用于处理事情时，问题的根本原因被掩盖，或不易察觉时，解决表面问题无果时。（where）\u003c/p>\u003cp>这个片段，我记住了在遇到问题找不到答案时，质疑提出问题本身，从源头解决。（结语）\u003c/p>","interaction":"\u003cp>………………………………………………………………………………以下是第一个片段A1激活经验…………………………………………………………………………\u003c/p>\u003cp>\u003cstrong>拆书技能点7：【A1】技能点的环节提问和指令清晰，学习者能根据提问中的场景联系自己过往的具体经验，且加工出加入再遇到同等情况，可以如何做。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）\u003c/strong>：\u003c/p>\u003cp> 通过前面的拆解和举例，小伙伴们应该都明白了从源头解决困难的思维模型的步骤和适用场景了。\u003c/p>\u003cp>下面请大家认真的思考，最近你有没有与人发生冲突或摩擦，有没有只是关注当下的情绪而没有了解对方真正需求的场景？比如当你和你的老板意见不一致时，你曾经是怎么处理的？现在运用从源头解决困境的方法能不能让你处理的更好的呢？\u003c/p>\u003cp>或者最近在工作或生活中有没有困扰你的事情，比如孩子被老师惩罚，你发现其实惩罚制度本身有问题？比如你是领导或老师，经常苦恼于下属或孩子们之间经常互相告状或打小报告等等场景，想想如果用今天所学的从源头解决困境，重新定义问题，你会有哪些更好的处理方式呢？\u003c/p>\u003cp>给大家4分钟的时间，联系一下自己过往的经历讨论一下，然后用今天的方法加工成更好的做法？4分钟后我们请一位小伙伴进行分享，现在开始。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>近期作为家委会主席，接到家长反映的问题，说作业多，孩子这几天晚上写到一两点，希望我给老师反映，对此我没有马上反馈，而是先从调研和让家人和孩子从源头查找，到底是作业多，还是自己写得慢，还是时间没有安排好，如果是作业多，是哪一科多？感觉需要控制到多少时间的范围，通过这样的引导，我帮助大家从源头分析和梳理，再反馈给老师就有理有据，同样比较高效。\u003c/p>\u003cp>回应：暖雨联想到的这个场景用到了片段中的从源头思考的步骤，非常赞！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":16733,"quote":"\u003cp>\u003cstrong>拆书技能点3：2个拆页的【R】，至少一个包含How的内容；有一定的逻辑关系，比如递进关系；且总内容未超过4页图片内页。\u003c/strong>\u003c/p>\u003cp>第二个片段同样来自于《好好思考》。请大家用2、3分钟的时间认真阅读手中的拆页，完成后麻烦小伙伴举手示意我。\u003c/p>\u003cp>选书：《好好思考》\u003c/p>\u003cp>拆页2 五星笔记法 p86-87页\u003c/p>\u003cp>所谓五星笔记法，就是每次记笔记之前，先画出五个星星，每个星星代表一个问题，一共五个问题，记笔记的过程就是回答这五个问题的过程。\u003c/p>\u003cp>这个方法背后的核心原理是：别人写出来的东西，还是别人的知识。我们只有对书中知识进行二次深加工，把别人的知识放在自己的知识体系里，把那些启发和收获与自己的经历、接下来的行动相联系，才能真正从别人的做法中提取精华。\u003c/p>\u003cp>而五星笔记法中的五个问题分别是：\u003c/p>\u003cp>1.预判对方要讲的核心内容是什么？为什么这个内容值得讨论？\u003c/p>\u003cp>其实，无论是一本书的主题还是工作、上课要讨论的议题，我们往往是提前知道的。因此，在读书或者开会之前，可以想想，如果我是作者或演讲人，我会如何讨论这个主题？等到打开书或者领导、同事开始讲的时候，我们就很容易比较大家思路之间的差别。\u003c/p>\u003cp>2.记录对方讲解的逻辑是什么？\u003c/p>\u003cp>推理逻辑往往比具体结论更重要。\u003c/p>\u003cp>因此，我在记录笔记的时候，不仅留心他说了什么，更关注他讲述的逻辑，在对方讲的时候，就尝试画出关键词之间的逻辑图，推测对方的思考过程。\u003c/p>\u003cp>3.这次讨论中我有什么疑问和启发？\u003c/p>\u003cp>对方讲的内容我有疑问吗？\u003c/p>\u003cp>有哪些观点给自己很大启发？\u003c/p>\u003cp>在讨论中我还联想到了哪些相关的案例和经验？……\u003c/p>\u003cp>这些灵光一现的启发点、疑问点，要及时记录下来，之后要再花时间加工分析。\u003c/p>\u003cp>4.对方的做法、想法或者给我的启发点，可以提炼为哪些思维模型？\u003c/p>\u003cp>顺着启发点继续发问：这个方法是解决什么问题的？这个策略为什么有效？这个策略的来源和依据是什么？把启发加工成过去自己学习过的其他原理，用新原理解释旧道理，把它提炼出思维模型。这个工作是要专门花时间提炼总结的。\u003c/p>\u003cp>5.这次讨论中给我的启发，哪些可以立刻变成下一步的行动？我如何把它们运用到自己的生活里？\u003c/p>\u003cp>启发不能仅仅停留在想法中，还要变成自己日程表中的行动计划，改变自己的生活\u003c/p>","explains":"\u003cp>…………………………………………………………………………………………………………以下是第二个片段的I拆书家引导………………………………………………………………………………\u003c/p>\u003cp>第二个片段也是提炼思维模型，和第一个片段属于并列关系，是关于五星笔记法，学习目标是通过学习拆页“五星笔记法”，大家能够在现场学以致用，根据给出的场景，加工出背后的思维模型进行现场演练分享，并找到未来的具体使用场景。\u003cbr>\u003c/p>\u003cp>\u003cstrong>拆书技能点6：2个拆页的【I】，涵盖了二级的4种讲解引导技巧：1）强调不那么做的坏处，2）给出了学习者可能异议的预防性讲解，3）细化了原文行动建议的步骤4）根据原书中案例脉络，给出了更贴近实际的例子。\u003c/strong>\u003c/p>\u003cp>说到做笔记，大家通常都是怎么做的？记录下重点的句子和观点，提醒自己，强化记忆便于日后查阅。我们认为做笔记就是记下别人的观点和想法。(通常做法)\u003c/p>\u003cp>这么做笔记实用吗？当我想要快速弄清楚一篇文章或一次演讲的底层逻辑，获得新的洞见时，我发现这种做笔记的方法非常低效，用这个方法时间久了，我就成了个搬书将，最多比别人会引经据典，根本不会获得新的洞见和智慧。（通常做法的坏处）\u003c/p>\u003cp>比如我曾经看到一个小故事：\u003c/p>\u003cp>“美国二战时期，参战回来的飞机，基本上清一色都是机翼部分有明显弹孔。于是司令下令加固所有飞机的机翼，这时顾问提出了疑问，机翼中弹的还能飞回来，可能是机翼足够结实，而机头机尾中弹的可能飞都飞不回来了。于是司令大惊，立刻派人调查，没想到结果果真如此，因此改为加固飞机的机头机尾。”\u003c/p>\u003cp>我感觉这个故事非常棒，用通常记笔记的方法，我会怎么做呢？抄写整段故事，以备以后查阅和引用，最多加一句，这个故事太有启发了。就没有然后了，等着需要的时候查阅，仅此而已。（负面案例）\u003c/p>\u003cp>如果我告诉你，运用今天的五星笔记法拆解一下这个故事，我能从这个小故事里拆出一个思维模型，还能指导你未来怎么用，让故事的智慧变成可以改变生活的方法论，你信不信？why\u003c/p>\u003cp>五星笔记法具体要怎么做呢？ \u003c/p>\u003cp>第一步：预判核心内容 \u003c/p>\u003cp>在读一本书、开会或听演讲之前，可以先预判对方要讲的核心内容是什么？然后比较大家思路之间的差距。如果去分析一篇文章或演讲，关注这段信息的核心内容是什么。\u003c/p>\u003cp>第二步：记录讲解逻辑\u003c/p>\u003cp>推理逻辑往往比结论更重要。不仅关心对方说了什么更要关心别人怎么说的，也就是讲解的逻辑，尝试画出逻辑图，推测出对方的思考过程。\u003c/p>\u003cp>第三步：记下疑问和启发\u003c/p>\u003cp>对方讲解的内容我有疑问吗？他的想法有什么局限？哪些观点对我有启发？及时记录下来。\u003c/p>\u003cp>第四步：提炼思维模型\u003c/p>\u003cp>提炼思维模型这一步有难度，其实就是找出解决问题的策略，可能是有步骤的方法论也可能就一句话。以下两步可以帮助大家提炼思路。\u003c/p>\u003cp>1、 顺着启发点，追问这个方法解决什么问题？\u003c/p>\u003cp>2、 依据讲解逻辑，整理出解决问题的具体步骤，提炼出方法论。（细化步骤）\u003c/p>\u003cp>第五步：变成具体行动\u003c/p>\u003cp>这次讨论中给我的启发，哪些可以立刻变成下一步的行动？我如何把它们运用到自己的生活里？\u003c/p>\u003cp>这五个步骤就是五星笔记法的核心内容。How\u003c/p>\u003cp>现在我们用五星笔记法挖掘一下我笔记本上记录的故事，看看收获会有什么不同？\u003c/p>\u003cp>“美国二战时期，参战回来的飞机，基本上清一色都是机翼部分有明显弹孔。于是司令下令加固所有飞机的机翼，这时顾问提出了疑问，机翼中弹的还能飞回来，可能是机翼足够结实，而机头机尾中弹的可能飞都飞不回来了。于是司令大惊，立刻派人调查，没想到结果果真如此，因此改为加固飞机的机头机尾。”\u003c/p>\u003cp>第一步：这个故事在讲什么问题？\u003c/p>\u003cp>美国二战期间参战回来的飞机普遍机翼中弹多，最后却加固了机头机尾。\u003c/p>\u003cp>第二步：故事的解决逻辑是什么？\u003c/p>\u003cp>司令凭经验决定加固机翼，通过调查发现没有飞回来的飞机，机头机尾中弹多，最后决定加固机头机尾。\u003c/p>\u003cp>第三步：给我什么启发或疑问？\u003c/p>\u003cp>遇到问题时，有时候依靠经验并不靠谱，需要对结论进行验证才能下判断。\u003c/p>\u003cp>这个方法的局限是什么？用于规避大的风险，调研验证成本高于试错成本时，就不适用了。\u003c/p>\u003cp>第四步：故事里的做法，我能提出什么方法论呢？\u003c/p>\u003cp>1、 顺着启发点，追问这个方法解决什么问题？重大问题决策，如何通过调研验证保证决策的正确性。\u003c/p>\u003cp>2、 依据讲解逻辑，关联已知原理，整理出解决问题的具体步骤，提炼出方法论\u003c/p>\u003cp>司令凭经验决定加固机翼，通过调查发现没有飞回来的飞机，机头机尾中弹多，最后决定加固机头机尾。\u003c/p>\u003cp>假设：该给机翼加钢板\u003c/p>\u003cp>求证：没有飞回来的飞机是否机翼弹痕多\u003c/p>\u003cp>结论：机翼不多机头机尾多\u003c/p>\u003cp>调整：加固机头机尾\u003c/p>\u003cp>提炼出决策模型 假设-求证-结论-调整的方法论。\u003c/p>\u003cp>提示下：提炼方法论的两个小步骤不一定必须都用到。\u003c/p>\u003cp>第五步：这个方法论如何用到我的生活中？\u003c/p>\u003cp>这个方法论适用于我遇到重要问题或者试错成本比较高的情况下，比如跳槽、转入新的跑道、选择合伙人或者终身伴侣等等。 （正面案例）\u003c/p>\u003cp>你可能觉得五星笔记法太费时间了，之前做笔记的方法多省事啊。事实上，不这么做会更麻烦，甚至麻烦不断，通常做笔记的方法就是低水平的勤奋，无论你多么努力都不会给你带来多大的突破。\u003c/p>\u003cp>比如上面的故事，通过对比传统做笔记法和五星笔记法的收益，结果一目了然，同一个故事，传统笔记法只是做到记录和积累素材，而五星笔记法帮助我挖掘出了假设-求证-结论-调整的决策思维模型，还让我找到了适用场景和适用边界，一举多得啊，虽然看起来比别人花时间，收益也会大很多。\u003c/p>\u003cp>五星笔记法的核心目的不是记录别人的知识和观点，而是挖掘和借鉴知识背后别人的思想和做法，帮助你寻找更有效的解决问题的策略，完善你解决问题的知识体系，建立知识体系的收益真的太划算了。（异议预防讲解）\u003c/p>","interaction":"\u003cp>…………………………………………………………………………………………以下是第二个片段的\u003cstrong>【A3】\u003c/strong>促动参与……………………………………………………………………\u003c/p>\u003cp>\u003cbr>\u003cstrong>拆书技能点9：使用【A3】技能点指令清晰， 学习者可以根据拆书家设定的案例场景，进行小组讨论，应用知识点并形成一个解决方案，或者是应用知识点进行角色扮演。\u003c/strong>\u003c/p>\u003cp>通过前面的拆解和举例，相信小伙伴们都感受到了五星笔记法的魅力，是不是都跃跃欲试了，俗话说得好：光学不练假把式，下面大家通过具体的场景来演练下。 \u003c/p>\u003cp>请大家用五星笔记法来挖掘一下这则笑话，背后的启发和思维模型。\u003c/p>\u003cp>朋友一直想去KTV玩，可是没钱，今天进了一家KTV随便挑了个包厢，推门进去说：我是隔壁的，玩大冒险输了，惩罚就是过来唱首歌。结果就这样唱了二十几个包厢，还免费喝了很多酒，还有人来搭讪！真是服了他了。\u003c/p>\u003cp>演练的时间是7分钟，大家用五星笔记法五个步骤来挖掘背后的价值，小组内讨论完成，加工出小组的知识模型。7分钟后我们请一位小伙伴进行分享，现在开始。\u003c/p>\u003cp>好的，7分钟时间到，哪位小伙伴们用五星笔记法五个步骤分享下小组挖掘出的思维模型或价值。\u003c/p>\u003cp>第一步：这个笑话在讲什么问题？\u003c/p>\u003cp>如果没有钱的情况下，如何免费唱KTV。\u003c/p>\u003cp>第二步：这个人解决问题的逻辑是什么？\u003c/p>\u003cp>通过大家都知道的大冒险游戏，免费赢得唱歌的机会。\u003c/p>\u003cp>第三步：这个解决方案给我什么启发和疑问？\u003c/p>\u003cp>免费唱KTV表面是是利用别人，实际上是一种交换，人们唱KTV是为了找乐子，寻开心，去别人房间唱KTV就是给别人创造欢乐时光。\u003c/p>\u003cp>局限性，就是这个人在每个包房只能唱一首歌。\u003c/p>\u003cp>第四步：这个人的做法，可以提炼什么思维模型？\u003c/p>\u003cp>在资源不足或者缺钱的缺资源的时候，如何通过交换或者已有资源交换在谋求发展。\u003c/p>\u003cp>第五步：我如何应用到自己的生活中？\u003c/p>\u003cp>遇到没有资源解决问题时，可以考虑利用已有资源解决。\u003c/p>\u003cp>回应：在你们小组几个人的努力下，用五星笔记法拆出了自己的思维模型和应用场景，非常棒！超出我的意料！为你们点赞！\u003c/p>\u003cp>……………………………………………………………………以下是第二个拆页\u003cstrong>【A2】\u003c/strong>催化应用……………………………………………………………………………………………………………\u003c/p>\u003cp>\u003cstrong>拆书技能点8：使用【A2】技能点指令清晰，至少一个【A2】环节提问中包含情境或场景，有学习者受启发联系到自己的具体应用场景。\u003c/strong>\u003c/p>\u003cp>通过前面一系列的拆解、举例和场景演练，相信大家对五星笔记法理解的比较清楚，下面我们来探讨哪些是你未来可以涉及的应用场景。\u003c/p>\u003cp>想一想，在工作中你会在哪些具体的场景用到五星笔记法？比如开会？听演讲？快速理解一篇高质量的资料或有启发的故事？ \u003c/p>\u003cp>或者学习写作或演讲时，拆解某位大咖的年度演讲、讲书稿或者公众号写作的文章？\u003c/p>\u003cp>又或者挖掘某位你崇拜的同事或大咖的处事方式或做事逻辑？\u003c/p>\u003cp>认真思考一下，你的生活或工作中涉及到哪个具体的场景，未来可以用到五星笔记法？请大家用6分钟的时间在小组内讨论，稍后请一位小伙伴分享。\u003c/p>\u003cp>陈陈想要用五星笔记法来拆解一下刚刚在得到新学的课程，净心想用五星笔记法来重新读一下想读的书。\u003c/p>\u003cp>\u003cstrong>拆书技能点11：结尾时给出了强有力的结语。 \u003c/strong>\u003c/p>\u003cp>结语：相信通过现场演练和关联具体的应用场景，大家对五星笔记法已经越来越熟悉，再遇到需要快速理解一篇文章、一场演讲、一次会议的底层逻辑时，一定可以通过五星笔记法来提炼思维模型，学以致用。感谢大家今天的陪伴，我的TF2-4拆书过级到此结束，感谢大家！\u003c/p>\u003cp>\u003cstrong>拆书技能点10：拆书家至少有一次给出了关联到原文知识点的回应或反馈。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书技能点12：第一个拆页时长没有少于10分钟，没有超过15分钟；第二个拆页时长没有少于30分钟，没有超过40分钟，整个拆书时长在50-60分钟之间。\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1639312444000,"updated_at":1639477230000,"ria":true},{"id":12547,"topic":"放下阅读快感，用“不读书法”读书","learn_goal":"","remark":"今天给大家带来的分享来自好好思考这本书 ，作者成甲曾经被逻辑思维评为中国最会学习的人 。我们都知道读书是性价比最高的学习方式 ，但很多人都是读到后面就忘记了前面 ，更别说去发现书中的思维 模式，成甲作为得到app的说书人 ，一年半的时间录制了上百本书 ，工作强度大的时候 一周需要录制两本书 ，从阅读到整理成说书稿 ，再到完成录制，他这么快的输入和输出 取决于他的高效阅读。今天给大家分享其中的一个方法 名字叫做“不读书法 ”。","level":"TF2-3","duration":2,"status":30,"type":0,"chaishujia":{"username":"粉黑天空","city":"深圳市"},"club":{"name":"深圳智行分舵","city":"深圳"},"prologue":"\u003cp>【自我介绍】\u003c/p>\u003cp>大家晚上好，我是粉黑天空，首先用三个标签介绍下我自己，分别指向我的过去、现在和未来。第一个标签是传播者，我做过记者，后来跨界做过品牌传播；第二个标签是升级打怪中的拆书家；第三个标签是个人成长教练，这是我未来的目标。\u003c/p>\u003cp>【技能点：学习目标包含学习者可被观察到 / 被测量到的行为或动作。】\u003c/p>\u003cp>【设定学习目标】\u003c/p>\u003cp>我今晚的拆书主题是：放下阅读快感，用“不读书法”读书。想要达成的学习目标是，在跟随我完成本次RIA现场学习后，学习者们以后在读书的时候，不再是\u003cstrong>只追求阅读快感，而是能够按照“不读书法”去分配阅读和思考时间，并进行自我提问。\u003c/strong>\u003c/p>\u003cp>我们本场分享会有一个高频词汇，那就是“思维模型”。为了方便大家理解本场的分享内容，我简单解释下，提出者查理·芒格给它的定义是“重要学科的重要原理”。这么讲比较晦涩难懂，换一个词大家可能就懂了，那就是“思考问题的套路”。\u003c/p>\u003cp>【技能点：选择图书是实用类或理论类图书；】\u003c/p>\u003cp>【技能点：在 FAB 介绍法中，能够清晰辨别出聚焦于图书和学习主题的 F、A、B。】\u003c/p>\u003cp>【F】\u003c/p>\u003cp>今天分享的片段来自《好好学习：如何练就高超学习力》这本书，作者成甲曾经被罗辑思维评选为“中国最会学习的人”。这本书是作者深入研究了股神巴菲特的黄金搭档，也就是查理·芒格提出的多元思维模型后，结合自身实践经验，总结出的多元思维学习方式。\u003c/p>\u003cp>【A】\u003c/p>\u003cp>这本书豆瓣评分7.9分，和其他致用类学习书籍相比，这本书颠覆了大多数人过往的学习方式，不再以一个个具体知识为学习的基本单位，而是以各学科的原理、规律作为知识管理、思考问题的基础。\u003c/p>\u003cp>【B1】\u003c/p>\u003cp>说到学习，我们很多人都觉得需要掌握更多知识，累积更多的经验，才能变得越来越厉害？但这本书告诉你，学习并不只是追求更多的知识，更重要的是寻找到帮助我们解决问题的思维模型。看完这本书，你会知道如何运用这种高超学习力，去解决工作和生活中的绝大多数的问题。\u003c/p>\u003cp>【B2】\u003c/p>\u003cp>我们知道，读书是性价比最高的学习方式，但我们很多人读书，经常会读了后面，就忘记前面，更别说去发现书中的思维模型了。成甲作为“得到”APP的说书人，曾经一年半时间就录制了上百本书的说书内容。工作强度大的时候，他一周要录制两本书，包括从阅读到写说书稿，到完成录制的全部工作。成甲这么快的输入和输出背后，靠的是三种高效的读书方法。我们今天这个片段，就为大家介绍其中的一种。名字非常特别，叫做“不读书法”。\u003c/p>","ratings_count":1,"texts":[{"id":16467,"quote":"\u003cp>【技能点：【R】所选拆页，可以是简单 How 的指令，也可以是隐含 How 的案例或故事；且总内容未超过 2 页图书内页。】\u003c/p>\u003cp>下面请大家用一分半钟的时间阅读下手中的原文拆页，读完的小伙伴可以举手示意我。\u003c/p>\u003cp>\u003cstrong>【R】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cu>选自《好好思考》P58-60  作者：成甲\u003c/u>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>所谓“不读书法”，是指一旦我们读书时看到对自己有启发的思维模型，我们就合上书，停止阅读。\u003c/strong>\u003c/p>\u003cp>你可能会奇怪：啊？这算哪门子读书法？为什么看到有启发的内容就不读了呢？\u003c/p>\u003cp>这是因为读书不一定都要花时间在“读”上，如果你是想要掌握知识，那你最应该花时间的地方是“思考”和“练习”，而非“阅读”。\u003c/p>\u003cp>\u003cstrong>人们在读书的时候，通常追求的是阅读获得启发的快感。\u003c/strong>我们希望阅读的脑高潮，一个接一个。可是这样读书有一个问题：读得是很爽，可读完了，啥都没记住，反而充满了失落感。其实掌握知识的关键在思考、练习有价值的解决策略，“点不在多，会用则灵”。\u003c/p>\u003cp>\u003cstrong>换句话说，从阅读改变自己的角度来讲：快感不重要，改变才重要。我们能否通过读书学习改变自己的关键是我们有没有把获得的思维模型用到生活里。\u003c/strong>过去我们把99%的时间用在了阅读上，偶尔回忆时却想不起读了什么。现在，我们要调整读书的时间分配：用20%的时间阅读，80%的时间来思考——我们要怎么应用获得的思维模型？\u003c/p>\u003cp>举个例子，如果我现在只有半小时读书，我会这么做：\u003c/p>\u003cp>（1）拿出一本书/一篇文章，看目录或快速浏览，翻到自己感兴趣的段落。\u003c/p>\u003cp>（2）一旦读到自己觉得有用/有趣的地方，就停下来合上书。\u003c/p>\u003cp>从打开书到结束读书，一般不会超过十分钟。那剩下的时间干什么呢？\u003c/p>\u003cp>当然就是“思考提问”环节啦。这时我就会：\u003c/p>\u003cp>（1）拿出纸和笔。\u003c/p>\u003cp>（2）向自己提问。\u003c/p>\u003cp>\u003cstrong>提什么问题呢？这是很关键的，不同的问题会给我们带来完全不同的收获。\u003c/strong>不过，对于大多数人而言，在只有半小时的时间内，回答下面几个常见问题就非常实用：\u003c/p>\u003cp>·为什么刚才这个点让自己有启发？它在解决什么问题？\u003c/p>\u003cp>·生活中还有类似的问题吗？自己能把这个启发点用在生活中吗？\u003c/p>\u003cp>·这个启发点有没有其他类似的知识？\u003c/p>\u003cp>…………\u003c/p>\u003cp>（阅读1.5分钟）\u003c/p>","explains":"\u003cp>好的，时间到了，我看到大部分的小伙伴已经读完了。\u003c/p>\u003cp>【what】\u003c/p>\u003cp>这个片段为我们提供了一种全新的阅读方法——不读书法，它重新调整了读书的时间分配，让我们放下对知识越多越好的贪念，聚焦于如何掌握书中的思维模型，去解决工作和生活中遇到的问题。大家有没有觉得这种读书理念，跟咱们拆书帮“拆为己用”的宗旨很像呢？\u003c/p>\u003cp>【why】 \u003c/p>\u003cp>&lt;人们通常的做法&gt;\u003c/p>\u003cp>我们很多人在阅读时都把99%的时间用在了阅读上，偶尔回忆时却想不起读了什么。\u003c/p>\u003cp>&lt;不这样做的坏处&gt;\u003c/p>\u003cp>这样读书其实是没有意义的，只会让我们走入阅读的误区，读书效率低下。“不读书法”可以帮助我们从这种阅读误区中走出来，让我们读过的书“以少胜多”，有效转化为提升自我的能力。\u003c/p>\u003cp>【技能点：【I】环节，给出了比原书拆页更加细化的行动步骤，或者将书中的案例进行了意译。】\u003c/p>\u003cp>【HOW】(细化行动步骤)\u003c/p>\u003cp>根据原文片段，我们可以提炼出“不读书法”的三大行动步骤：\u003c/p>\u003cp>\u003cstrong>1、预估自己的阅读时间\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2、拿出20%的时间用来阅读\u003c/strong>\u003c/p>\u003cp>在阅读的时候，我们要迅速找到自己觉得有用或者有趣的地方，找到了就可以合上书提前结束，不一定非要读够20%的时间。\u003c/p>\u003cp>\u003cstrong>3、拿出80%的时间向自己提问\u003c/strong>\u003c/p>\u003cp>原文罗列了一些向自己提问的常见问题，我将这些问题梳理成了三种，方便大家以后记忆和运用：\u003c/p>\u003cp>①　提出帮助自己分析和整理信息的问题。可以问自己：为什么这个点会让我有启发？它能解决什么问题？还可以问自己，这里面有我不太熟悉的概念吗？\u003c/p>\u003cp>②　提出帮助自己反思过往经验的问题。可以问自己：我过去有没有遇到过类似的问题？\u003c/p>\u003cp>③　提出帮助自己内化和应用知识的问题。可以问自己：我可以把这个启发点运用到生活中去吗？有没有其他相类似的知识？\u003c/p>\u003cp>比如说这个周五晚上，我刚好有空可以看下书。根据刚才的“不读书法”三步骤，\u003c/p>\u003cp>（1）我会先预估下自己有多少时间不会被打扰，可以专门用来看书。\u003c/p>\u003cp>（2）我估计是2个小时，于是，我会给自己预留24分钟左右的时间去阅读感兴趣的书籍，找出觉得有用或者有趣的点，然后合上书。当然，如果提前找到，就可以提前进入自我提问的环节。\u003c/p>\u003cp>（3）准备好纸和笔，开始进行自我提问，帮助自己分析和整理信息，反思过往经验以及内化和应用知识。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>可能有小伙伴还会有疑问，我不看完整本书我怎么知道哪些内容是我需要的，光靠自己想就能收获这么大的进步吗？大家首先要记住，贪多嚼不烂，与其博览群书而记不住，还不如精读一段彻底弄懂；另外，我们解决不了自己认知以外的问题，给我们造成困惑的大部分问题并不一定非常高深，但一定是我们没有认真去探究的问题。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>当然，“不读书法”虽然可以帮助我们在很短的时间内，快速发现思维模型。但它比较适合“一个问题对应一个思维模型”的简单问题。如果遇到复杂的问题，就有点捉襟见肘了。这时候，可以运用书中介绍的另外两种读书方法，时间关系就不过多展开。\u003c/p>","interaction":"\u003cp>【技能点】现场学习者设计清晰体现了该学习目标。\u003c/p>\u003cp>【技能点】【A3】环节，给出了一个非常具体、确定的场景，学习者可在此场景中演练或讨论或应用新学技能。\u003c/p>\u003cp>拆书家提问设计（逐字稿）\u003c/p>\u003cp>【场景设计】\u003c/p>\u003cp>根据我们刚才学习的“不读书法”，我们在阅读时不能再只追求阅读快感，而是要按照“不读书法”去分配阅读和思考时间，并进行自我提问。现在大家一起做一个演练。请大家认真听一下要演练的场景：\u003c/p>\u003cp>小白是一名拖延症患者，为此他错过了很多本属于他的机会。为了改变自己，小白买了很多解决拖延症方面的书籍，感觉每本书都讲到了他的痛点，就迫不及待地将每本书都看了一遍。但是大量阅读过后，小白发现书里的很多方法他根本记不住，经常看到后面就忘记了前面讲的内容。最后，小白拖延的情况还是没有改善。小清是小白的好朋友，他是大家公认的“阅读高手”。\u003c/p>\u003cp>【技能点】使用【A3】技能点的环节指令清晰，学习者可以根据拆书家设定的案例场景，进行小组讨论、应用知识点并形成一个解决方案，或是应用知识点进行组内角色扮演。 \u003c/p>\u003cp>【小组讨论、角色扮演】\u003c/p>\u003cp>现在请每两人一组，进行演练。一个扮演小白，你主动找小清去倾诉自己这段时间读书的失落感，比如读完后记不住书里面的内容，也没能改变自己；另一人扮演小清，你在听完小白的讲述后，结合“不读书法”，简单分析下小白阅读的问题出在哪里，并提出合理的读书建议。\u003c/p>\u003cp>演练时间是5分钟，现在开始。5分钟后，我会选一位“小白”和“小清”，大家一起听下他们的“不读书法”是怎么运用到场景中的。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>好，时间到。下面有请一组小伙伴来角色扮演，分享一下你们的对话。\u003c/p>\u003cp>第一组学习者：\u003c/p>\u003cp>小白：小清，我最近遇到一个问题，就是读了好多书，往回想就会忘记。你读那么多书，能不能给我一些建议？\u003c/p>\u003cp>小清：你是不是读书读了太多，读完之后没有进行思考呀？\u003c/p>\u003cp>小白：没有，我就是一路读下去。\u003c/p>\u003cp>小清：那我还是建议你读的时候，读到特别感兴趣的点就先停下来，思考下这个点，让这个点联系你的实际生活，然后把它应用到你的实际生活中去，这样你的记忆力就会加深。\u003c/p>\u003cp>小白：就是我读到有触动到我的点的时候，我就把书本合起来，然后再去思考对吗？再结合自己的实际情况，试着去做。这是个很好的方法，我会试着去搞清楚。\u003c/p>\u003cp>小清：对的。\u003c/p>\u003cp>观察家：我觉得讲的很好。如果是按照我们刚学的三个步骤，可以再细化一下吗？刚才其实已经讲到点子上了。\u003c/p>\u003cp>小清：就是你每次阅读的时候，可以预估下你的阅读时间；然后用20%时间读书，80%的时间思考。\u003c/p>\u003cp>小白：好的，我试一下。\u003c/p>\u003cp>小清：在思考的时候，就可以运用到刚才讲的方法进行自我提问，然后联系实际，运用到自己的实际生活中。\u003c/p>\u003cp>小白：谢谢你的建议，我觉得这个非常好，我回去一定要试一下。\u003c/p>\u003cp>第二组学习者：\u003c/p>\u003cp>鱼仔：我经常会看书，因为看到时候觉得挺有意思，觉得这个东西对我有用，但过了之后我又觉得没有用到我的实际生活当中。你一提我就知道，但是我自己用的时候就不会用。\u003c/p>\u003cp>伟杰：我觉得小白（鱼仔）在阅读之前可以设定一个阅读时间限制，就比如这本书你要给自己阅读2小时，还是3小时，然后再看书籍的时候，看到有戳中内心的点，产生强烈共鸣的话，你可以立马合上书籍，去思考这个点如何用，联系过往的经验想下过去是怎么用的。最后就是你再想下将来怎么运用到生活和工作中去，我给的建议就是这些，我希望未来你能够将知识得到更好的运用。\u003c/p>\u003cp>感谢两组小伙伴的精彩演练，通过这个角色扮演，让我们更深切地感受到，很多人在阅读的时候，过度追求阅读快感，而没有花时间和精力去思考阅读到的知识点要如何去运用，这样读书效率真的不高。希望今天学习了“不读书法”后，大家能够体会到它“以少胜多”的奥妙所在，给大家的成长带来一些帮助。谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1635150273000,"updated_at":1635777330000,"ria":true},{"id":12450,"topic":"“超一流”学习法","learn_goal":"","remark":"《好好思考》，作者是成甲，他是一名知识管理专家，被“逻辑思维”节目评为“中国最会学习的人之一。本书最重要的一个亮点是给学习知识重新下了一个定义：“学科管理”的思维模型，打破了学界思考的界限。","level":"TF2-2","duration":18,"status":30,"type":0,"chaishujia":{"username":"梅花Muses","city":"北海市"},"club":{"name":"北海筹备分舵","city":"北海"},"prologue":"\u003cp>\u003cstrong>分组和学习目标：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【介绍和分组】\u003c/strong>欢迎大家来到拆书现场，今晚我过TF2-2！我叫梅花，是一名初高中的英语老师。为了方便讨论和分享，我们先分组，以中间为中轴线，两边各位一组。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>伙伴们，我们都活在当下知识焦虑的时代，每个人都明白知识和学习的重要性，并想提升学习力，以便有效地解决问题。那如何练高超的学习能力？期待今天的学习之后，我们能够掌握并运用一套有效解决问题的办法：“超一流”学习法。 \u003c/p>\u003cp>\u003cstrong>观察的技能点：学习目标包含学习者可被观察到、被测量到的行为或是动作，现场学习者设计清晰体现了该学习目标。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>图书介绍：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【F 特征】\u003c/strong>我选的书叫做《好好思考》，作者是成甲，他是一名知识管理专家，被“逻辑思维”节目评为“中国最会学习的人之一”。本书最重要的一个特点是给\u003cu>学习知识重\u003c/u>新下了一个定义：“学科原理”的思维模型，打破了学界思考的界限。\u003c/p>\u003cp>（所谓“学科原理”的思维模型”--就是某学科的底层规律：如经济学有机会成本思维；边际效应思维；心理学中人有需要被尊重的思维；数学有概率思维等等）\u003c/p>\u003cp>\u003cstrong>【A 优势】其实，\u003c/strong>关于思维模型的书籍有很多，大部分都是从理论讲述，很难读懂。但本书是作者根据自己10多年的研究经验，用真实案例展示原理和实战办法，简单易懂可操作。混沌大学创始人李善友先生极力推荐。\u003c/p>\u003cp>\u003cstrong>【B 益处】\u003c/strong>那学习这本书籍有什么好处呢？有两个方面：\u003c/p>\u003cp>（第一B1）：我们每天都在学习和讨论学习，自认为非常熟悉，绝大部分的人认为：学习就是记忆更多的知识，掌握更多的知识，21世纪知识大爆炸的年代，这样子学习真的可以吗？本书会为你展开全新的思维模型的认知，并回答你的疑惑。\u003c/p>\u003cp>（第二B2）：每天我们都需要解决问题？那有没有思考过解决问题的依据是什么？还有更好的解决问题的办法吗？通过今晚学习“超一流”学习法，会为你破解这些疑惑。\u003c/p>\u003cp>\u003cstrong>观察的技能点：1）在FAB介绍法中，能够清晰辨别出聚焦于图书和学习主题的F、A、B；2）选用的图书是实用类或是理论类。\u003c/strong>\u003c/p>","ratings_count":1,"texts":[{"id":16402,"quote":"\u003cp>好，那现在开始吧！请大家用2分钟的时间阅读原文。完成的小伙伴请举手示意，谢谢。\u003c/p>\u003cp>\u003cstrong>掌握思维模型的实战方法：超一流学习法\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（《好好思考》第三章）\u003c/strong>\u003c/p>\u003cp>前面我们讲了读书和工作中寻找解决问题的思维模型的方法，但只是找到思维模型(所有能够持续有效解决问题的策略，都可以称为思维模型-查理 .芒格)还不够，我们还要把思维模型内化掌握。如何解决这个问题呢？\u003c/p>\u003cp>在过去9年应用思维模型解决问题的过程中，我发展出了一套掌握思维模型很实用的方法：“超一流学习法”。\u003c/p>\u003cp>所谓“超一流”，是在生活中提炼和运用思维模型的三个核心环节。\u003c/p>\u003cp>第一个环节：“超”，是指遇到问题时要先从超级人脉找答案，提炼思维模型。\u003c/p>\u003cp>第二个环节：“一”，是指对提炼的思维模型举一反三，多维实践，理解“一即是多，多即是一”。\u003c/p>\u003cp>第三个环节：“流”，是指要把掌握的思维模型训练成行云流水如闪电般的直觉反应。\u003c/p>\u003cp>这三个环节环环相扣，就形成了掌握思维模型的核心流程：\u003c/p>\u003cp>技能观察点：\u003c/p>\u003cp>【R】拆页，包含how的指令；且内容没有超过2页。\u003c/p>","explains":"\u003cp>大家已经阅读差不多了，谢谢你们的时间。对于这个片段，我有如下几个理解：\u003c/p>\u003cp>1、【What】本片段讲解了一套解决问题的办法：思维模型“超一流”学习法。\u003c/p>\u003cp>2、【Why】其实，人生就是遇见问题和解决问题的循环过程，我们大部分的人遇见问题的解决依据是-过往经验。在过去是很有效的策略，但是面对乌卡时代(VUCA )，是易变的，复杂的，个人有限的经验已经不足够应对未来的问题。所以我们需要学习效的决策依据，\u003cstrong>而“学科原理”\u003c/strong>思维模型的“超一流”学习法，是一种重要的解决问题的依据。\u003c/p>\u003cp>【反面案例】这让我想起自己最近的一个案例，我对写作一直都感兴趣，但都没有付诸行动。直到今年7月份，教育界的“双减”政策出台，对我们教培行业冲击很大，于是我就决定转行写作。那如何写作呢？我的认知里是停留在学生年代的写作文，认为并不难，可以是实践了两周时间，我发现自己无从写起，于是又停了下来。\u003c/p>\u003cp>【总结】发现了吗?伙伴们，我解决问题是源于过往的经验，大部分都是不靠谱的。\u003c/p>\u003cp>3、【How】那该如何解决问题才是有效的决策呢？本片段提供了一套新的决策办法：“超一流”学习法。它共有三步：\u003c/p>\u003cp>第一步：找超级人脉并提炼思维模型。\u003c/p>\u003cp>第二步：用“举一反三”训练已经提炼的思维模型。\u003c/p>\u003cp>第三步：还需要刻意练习，成为一流高手。\u003c/p>\u003cp>【反转正案例】如果，我运用“超一流”的办法，坚持写作几个月，也许效果就不一样了。我们来看看。\u003c/p>\u003cp>第一步：找超级人脉并提炼思维模型。\u003c/p>\u003cp>（我的问题是如何写作：我想到我身边的一位作家，就是我拆书帮的师父，我需要找时间求教，学习她写作的思维模型。再者，我还可以查阅一些写作大师的书籍，看看别人是如何写作的。）\u003c/p>\u003cp>第二步：用“举一反三”训练已经提炼的思维模型。\u003c/p>\u003cp>（从师父或是书籍提炼出来的写作思维模式或是正确的办法，如何用举一反三法训练呢？两个有效的工具：情景学习和交替学习。比如，情景教学：我写故事一个重要因素是冲突，那么我可以用到我的教学课堂，让照本宣科的知识有点色彩；交替学习：学到的思维模型可以用于分享和谈论。）\u003c/p>\u003cp>第三步：还需要刻意练习，成为一流高手。\u003c/p>\u003cp>有了写作目标和思维模型的办法，这只是思考层面而已，还需要行动。想要成为写作的高手，那就必须每天花时间投入和专注，然后找专业的人给予及时的反馈，最后修正，以此反复练习，直到变成直觉的反应。\u003c/p>\u003cp>4、【Where】适用于从长期角度出发，想在某个领域成为高手的人群；不适用于急需要解决的问题。\u003c/p>\u003cp>5、【预防异议】\u003c/p>\u003cp>（1）其实我们都明白，好的圈子和好的人脉对学习的重要性，但是我们不是每个人都有机会找到这样子的老师。\u003c/p>\u003cp>【讲解】如果不能够在现实中直接求教高手，那么可以阅读大师和高手的书籍或是文章，这也是一种非常有效的办法。\u003c/p>\u003cp>（2）办法好是好，但是很难坚持。刚开始会满怀信心，真的实践一段时间之后很难坚持，很有挫败感，也觉得浪费时间。\u003c/p>\u003cp>【讲解】这种现象很普遍，很难直接给你答案。不过我们需要跳出这个问题，用心态来解决它。即使不是每天坚持，中途也会有打断，这些不是意志力不强或是能力的问题，这是学习成长的过程。想起来的时候再启动，能力的提升和理解层面也会不一样。\u003c/p>\u003cp>（3）关于思维模型，不知道如何提炼？（不做讲解，有人提问就结束后探讨）\u003c/p>\u003cp>【讲解】这个问题比较大，需要一定时间。我们现场时间有限，结束后我们可以一起讨论。\u003c/p>\u003cp>【备注】乌卡时代(VUCA )是volatile，uncertain，complex，ambiguous英文缩写。乌卡时代是一个具有现代概念的词，是指我们正处于一个易变性、不确定性、复杂性、模糊性的世界里。\u003c/p>\u003cp>技能观察点：\u003c/p>\u003cp>1）【I】的讲解中有举例子。2）【I】环节提到了学习者可能产生的异议，并给与了预防性的讲解。\u003c/p>","interaction":"\u003cp>【A2 催化第一步】：\u003c/p>\u003cp>\u003cstrong>【拆书家提问设计（逐字稿）】：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>以上就是我对片段的理解。接下来到运用层面。现在请大家呼吸3秒钟，让脑袋放空一下。\u003c/strong>\u003c/p>\u003cp>每天，我们都会面临着各种各样需要解决的问题，那么现在请大家思考下，未来的一周内，在工作上、亲子教育上和梦想目标追求上会遇到什么问题？比如：\u003c/p>\u003cp>1、【工作】给上级提建议？负责启动某些项目？分享某些主题？工作与梦想不符合怎么办等等？\u003c/p>\u003cp>2、【亲子教育】教育的终极目标是培养孩子的终身学习的思维。那如何启动孩子的内驱力呢？如何培养孩子的自律呢？(所有关于教育的课题，从经济学的角度来说，都是最值得投资和思考并解决的问题)\u003c/p>\u003cp>3、【梦想和目标】也许有两种情况：一是还没有梦想和目标的，那么如何寻找梦想和目标，是一个非常需要解决的问题？二是已经有了梦想和目标，那如何行动呢？\u003c/p>\u003cp>现在请大家用3分钟后思考，自己未来一周将要解决的问题并在组内分享；之后，我请一位伙伴上台分享他需要解决的问题（1分钟）。\u003c/p>\u003cp>【学习者案例记录】：\u003c/p>\u003cp>现在请娜姐分享自己的案例：未来一周需要解决的问题。\u003c/p>\u003cp>--学习视频剪辑\u003c/p>\u003cp>非常感谢娜姐的分享，通过RIA片段的学习，联想到了需要解决的问题。\u003c/p>\u003cp>技能观察点：分步崔华中，提问中包括情景或场景，有学习者受启发联系到自己的具体应用场景。\u003c/p>\u003cp>【A2 催化第二步】：\u003c/p>\u003cp>\u003cstrong>【拆书家提问设计（逐字稿）】：\u003c/strong>\u003c/p>\u003cp>大家已经找到了下周需要解决的问题了，通过刚刚学习了“超一流”学习办法，请思考下，用“超一流”的步骤如何解决你们的问题？步骤如下表（4分钟）；之后我会请一位伙伴分享自己的案例（1分钟）\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】：\u003c/strong>\u003c/p>\u003cp>时间到了，现在请娜姐分享自己的案例：如何运用“超一流”学习法来解决问题。\u003c/p>\u003cp>【结束】谢谢娜姐的分享和大家的积极参与。期待通过学习“超一流”的学习办法后，大家能够升级自己解决问题的能力。今天拆书到此结束，谢谢大家。\u003c/p>\u003cp>技能观察点：分步催化中指令清晰，有学习者根据指令，规划出了以后可以如何做的具体计划。\u003c/p>\u003cp>总观察点：\u003c/p>\u003cp>1）总时长没有少于15分钟，没有超过20分钟；\u003c/p>\u003cp>2）每个环节的时长分配符合本训练概述的要求。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1633874196000,"updated_at":1633912544000,"ria":true},{"id":11849,"topic":"如何练就高超学习力","learn_goal":"","remark":"如果说太阳底下没有新鲜事，那么高效的学习方法是什么？与人们通常认为的学习的关键是努力掌握更多的知识，但懂得的道理再多，依旧过不好这一生。掌握的知识再多，不去应用都不会发生任何改变。 本书作者成甲，把学习知识的基本单位定义为“思维模型。那我们如何从思维模型入手，构建一个全新的学习思考体系，进而练就超强学习力？成甲老师将结合自己10多年的研究经验，从基本原理、搭建知识体系、演示实战方法等多个角度系统讲解论述。 一起跟随成甲老师的研究，学习怎样思考，怎样练就超强的学习力。","level":"TF1-1","duration":10,"status":30,"type":0,"chaishujia":{"username":"大源","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"\u003cp>拆书法介绍：\u003c/p>\u003cp>拆书法是是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。分为个人学习的拆书法和组织学习的拆书法。个人学习的应用是RIA便签读书法，让人读一本书就能达到参加同主题培训的效果。组织学习的应用就是拆书家拿一本书加工出一场现场学习，引导和促进大家把知识拆为己用。\u003c/p>\u003cp>拆书帮介绍：拆书帮是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵。拆书帮分舵是非营利性青年自组织，使命就是帮助更多学习爱好者成长为拆书家。\u003c/p>\u003cp>自我介绍：\u003c/p>\u003cp>第一个标签，\u003cstrong>拆书帮新人\u003c/strong>，两周前刚刚正式入会，这是我第一次拆书分享，希望大家多多提宝贵意见。\u003c/p>\u003cp>第二个标签，\u003cstrong>90后车间主任\u003c/strong>，2014年大学毕业，当时为了解决北京户口，就选择进入一家央企工作，从最基层岗位干起，用了4年时间做到车间主任，车间职工最多时有165人。\u003c/p>\u003cp>第三个标签，\u003cstrong>表达爱好者。\u003c/strong>我给自己规定，每天要进行1000字以上文字输出，通过这种形式提高自己的表达能力，这样做的原因我会在后面介绍。\u003c/p>","ratings_count":1,"texts":[{"id":15797,"quote":"\u003cp>片段来源：《好好思考》\u003c/p>\u003cp>阅读片段：所谓“五星笔记法”，就是每次做笔记之前，先画出一个五角星，每个角代表一个问题，一共五个问题，我做笔记的过程就是回答这五个问题的过程。五个问题回答完，笔记才算做完了。这个方法背后的核心原理是，别人说出来的东西，你就算记下来，也还是别人的知识。我们只有对别人说出来的东西进行二次深加工，把别人的知识放在自己的知识体系里，把那些启发和收获与自己的经历、接下来的行动相联系，才能真正从别人的做法中提取精华。\u003c/p>\u003cp>而五星笔记法中的五个问题分别是：\u003c/p>\u003cp>\u003cstrong>1．预判对方要讲的核心内容是什么，为什么这个内容值得讨论。\u003c/strong>\u003c/p>\u003cp>其实，无论是一本书的主题还是工作会议要讨论的议题，我们往往是提前知道的。因此，在读书或者开会之前，可以想想，如果我是作者或演讲人，我会如何讨论这个主题？等到打开书或者领导、同事开始讲的时候，我们就很容易比较大家思路之间的差别。\u003c/p>\u003cp>\u003cstrong>2．记录对方讲解的逻辑是什么。\u003c/strong>\u003c/p>\u003cp>推理逻辑往往比具体结论更重要。因此，我在做笔记的时候，不仅留心他说了什么，而且关注他讲述的逻辑，在对方讲的时候，就尝试画出关键词之间的逻辑图，推测对方的思考过程。\u003c/p>\u003cp>\u003cstrong>3．这次讨论中，我有什么疑问和启发？\u003c/strong>\u003c/p>\u003cp>对方讲的内容我有疑问吗？他的想法有什么局限性吗？有哪些观点给自己很大启发？在讨论中，我还联想到了哪些相关的案例和经验？\u003c/p>\u003cp>…………\u003c/p>\u003cp>这些灵光一现的启发点、疑问点，要及时记录下来，之后要再花时间加工分析。\u003c/p>\u003cp>\u003cstrong>4．对方的做法、想法或者给我的启发点，可以提炼为哪些有效策略（思维模型）？\u003c/strong>\u003c/p>\u003cp>顺着启发点继续追问：这个方法是解决什么问题的？这个策略为什么有效？这个策略的来源和依据是什么？我们要尽可能把获得的新启发点与自己过去学习过的其他原理联系起来，用新原理解释旧道理，这样我们能更深刻地理解这个启发。当然，这份工作是要专门花时间的。\u003c/p>\u003cp>\u003cstrong>5．这次讨论中给我的启发，哪些可以立刻变成下一步的行动？我如何把它们运用到自己的生活里？\u003c/strong>\u003c/p>\u003cp>启发不能仅仅停留在想法中，还要变成自己日程表中的行动计划，改变自己的生活。\u003c/p>\u003cp>���\u0012���Sm��\u0014\u003c/p>","explains":"\u003cp>【I便签】\u003c/p>\u003cp>what：五星笔记法给出了一套具体行动步骤，帮助我们解决怎样把学到、看到的知识内化成自己知识框架并践行下去的方法。\u003c/p>\u003cp>why：我不知道大家有没有一个感觉，就是我们听了很多讲座，并且记了很多笔记，有些讲座很精彩，学习过程中直呼NB，恨不得拍断大腿，但是听完看过之后就没有然后了。之前有一句很火的话，听过了无数道理，仍旧过不好这一生。\u003c/p>\u003cp>how：片段中的“五星笔记法”就给出了一套方案，来帮助我们解决怎样把学到的知识内化成自己知识框架，并制定出具体行动方案，一共分为5步。\u003c/p>\u003cp>第一步：预判核心内容。课程前根据演讲主题先设想核心内容，并情景代入，换成是自己去讲这个主题，应该怎样安排课程。\u003c/p>\u003cp>第二步：记录讲解逻辑。课程中认真记录讲授者讲授逻辑，并对照自己设想方案观察对比。\u003c/p>\u003cp>第三步：记录疑问和启发。在课程中有哪些疑问？受到了哪些启发？及时记录下来这些灵光一闪的点。\u003c/p>\u003cp>第四步：提炼方法。把引起我们启发的点认真思考，梳理出讲受者解决问题的方法。并把这个方法与自己的相关经历关联。\u003c/p>\u003cp>第五步：制定具体行动方案。把学到的知识用到实际情境当中，去迭代优化。\u003c/p>","interaction":"\u003cp>【A1便签】\u003c/p>\u003cp>我还是一个非常主动学习的人，参加拆书帮也能看出来哈。但我也发现，大多数情况学完、看完就这件事就结束了，并没有对我生活产生什么影响。\u003c/p>\u003cp>比如我去年学过一门投资学的课程，是一位投资家杨天南的讲授的。这门课我非常认可的，课程中我听得非常认真，笔记记得恨不得记下逐字稿，一共是32学时的课程，听完以后对我的投资方面的并没有带来实质性的影响。\u003c/p>\u003cp>反思：如果对照“五星笔记法”，我存在的问题还是非常多的。比如，我没有预判过老师要讲解的核心，课前从没有做过预习，每次都是带着脑袋去听，这就成了一种知识的灌输。其次，我记笔记恨不得记下了老师的逐字稿，却没有着重理解老师讲解的逻辑，只想着结论，却不顾论证推理的过程。最大的问题，也是没有给自己规划行动，学习只是为了学，学完以后没有任何行动。当时其实通过学习，我是知道对于大多数年轻人来说，精力要更多的用在自己主业上，投资理财可以定投指数基金，但我也没有任何行动哈，如果那时候要是定投了沪深300，收益也能有十几个点。\u003c/p>\u003cp>【A2便签】\u003c/p>\u003cp>周六我参加了一场线下分享《普通人如何破圈成长》，这个主题我想大家都感兴趣，我学以致用的使用“五星笔记法”实践了一下。\u003c/p>\u003cp>第一步，在活动开始前预判核心内容，核心是破圈和成长。如果是我讲的话，我会围绕普通人怎样破圈，又怎样成长展开，分别介绍具体实施方法。\u003c/p>\u003cp>第二步，记录介绍者的逻辑。在分享过程中，出乎我预料的是，介绍者把破圈和成长结合起来了，我们的成长就是不断破圈的结果，如何破圈才是成长的中心。\u003c/p>\u003cp>第三步,给我的启发是，现在这个时代高阶输出能力是能够破圈的核武器。\u003c/p>\u003cp>第四步，回去以后，我认真思考演讲者的观点，的确是真理。互联网时代，能够输出优质内容就能让一个人破圈。一篇好文章获得好的传播，就能让你被很多人认识，拓展到更高的圈层。我刚工作的时候，因为参加单位举办的演讲比赛，获得了一个奖项，才被大领导认识，后面给我带来了很多想不到的锻炼机会，成长也非常快。\u003c/p>\u003cp>第五步，实践。今天站在这里也是我的一个实践，向大家输出内容和观点。同时我也决定每天要输出内容，形式包括朋友圈还有跟超哥一起写启发日记。边输出也要边强化。构成一个增强回路，强的内容输出能力，让自己获得更多表达机会和链接机会。\u003c/p>\u003cp>�\u0004�S���\u0014\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1625234242000,"updated_at":1625633419000,"ria":true},{"id":9822,"topic":"能够挖掘出核心知识的五星笔记法","learn_goal":"","remark":"通过五星笔记法，挖掘核心知识，提取知识精华","level":"TF1-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"李慢慢","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"\u003cp>各位小伙伴大家好，我是拆书家李慢慢。今天给大家带来的拆页， 是选自成甲的新书《好好思考》。《好好思考》这本书，是继《好好学习》之后，作者又一部有关多元思维模型的力作。我们今天的主题是能够挖掘出核心知识的“五星笔记法” 。接下来，我将给大家通过共享屏幕分享原文片段，阅读时长1分钟30秒，请大家仔细阅读。读完的小伙伴请语音回复。\u003c/p>","ratings_count":1,"texts":[{"id":13663,"quote":"\u003cp>\u003cem>所谓“五星笔记法”，就是每次做笔记之前，先画出一个五角星，每个角代表一个问题，一共五个问题，我做笔记的过程就是回答这五个问题的过程。五个问题回答完，笔记才算做完了。\u003c/em>\u003c/p>\u003cp>\u003cem>这个方法背后的核心原理是，别人说出来的东西，你就算记下来，也还是别人的知识。我们只有对别人说出来的东西进行二次深加工，把别人的知识放在自己的知识体系里，把那些启发和收获与自己的经历、接下来的行动相联系，才能真正从别人的做法中提取精华。\u003c/em>\u003c/p>\u003cp>\u003cem>而五星笔记法中的五个问题分别是：\u003c/em>\u003c/p>\u003cp>\u003cstrong>\u003cem>1．预判对方要讲的核心内容是什么，为什么这个内容值得讨论。\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cem>其实，无论是一本书的主题还是工作会议要讨论的议题，我们往往是提前知道的。因此，在读书或者开会之前，可以想想，如果我是作者或演讲人，我会如何讨论这个主题？等到打开书或者领导、同事开始讲的时候，我们就很容易比较大家思路之间的差别。\u003c/em>\u003c/p>\u003cp>\u003cstrong>\u003cem>2．记录对方讲解的逻辑是什么。\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cem>推理逻辑往往比具体结论更重要。\u003c/em>\u003c/p>\u003cp>\u003cem>因此，我在做笔记的时候，不仅留心他说了什么，而且关注他讲述的逻辑，在对方讲的时候，就尝试画出关键词之间的逻辑图，推测对方的思考过程。\u003c/em>\u003c/p>\u003cp>\u003cstrong>\u003cem>3．这次讨论中，我有什么疑问和启发？\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cem>对方讲的内容我有疑问吗？他的想法有什么局限性吗？\u003c/em>\u003c/p>\u003cp>\u003cem>有哪些观点给自己很大启发？\u003c/em>\u003c/p>\u003cp>\u003cem>在讨论中，我还联想到了哪些相关的案例和经验？\u003c/em>\u003c/p>\u003cp>\u003cem>…………\u003c/em>\u003c/p>\u003cp>\u003cem>这些灵光一现的启发点、疑问点，要及时记录下来，之后要再花时间加工分析。\u003c/em>\u003c/p>\u003cp>\u003cstrong>\u003cem>4．对方的做法、想法或者给我的启发点，可以提炼为哪些有效策略（思维模型）？\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cem>顺着启发点继续追问：这个方法是解决什么问题的？这个策略为什么有效？这个策略的来源和依据是什么？我们要尽可能把获得的新启发点与自己过去学习过的其他原理联系起来，用新原理解释旧道理，这样我们能更深刻地理解这个启发。当然，这份工作是要专门花时间的。\u003c/em>\u003c/p>\u003cp>\u003cstrong>\u003cem>5．这次讨论中给我的启发，哪些可以立刻变成下一步的行动？我如何把它们运用到自己的生活里？\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cem>启发不能仅仅停留在想法中，还要变成自己日程表中的行动计划，改变自己的生活。\u003c/em>\u003c/p>\u003cp>\u003cem>这五个问题就是五星笔记法的核心内容。\u003c/em>\u003c/p>","explains":"\u003cp>\u003cstrong>【what】\u003c/strong>\u003c/p>\u003cp>古话说：勤能补拙是良训，一分辛苦一分才。来参加拆书活动的小伙伴，都是热爱学习的。在工作生活之余，都在通过各种方式提升自己。比如参加了很多课程、读了很多书，订阅了许多公众号、看了大量干货文章等等。相关数据表明，我们现在一天看到的信息量，是1897年的160倍。这样看来，我们都是很努力的人呢。那么问题来了，我们每天都在学习大量的知识，但为什么还是过不好这一生呢？是古人说错吗？还是这个时代变化太快？都不对，其实是我们学习知识的方法有问题。\u003c/p>\u003cp>我们大多数人在学习知识的时候，往往只是对他人外显的知识进行学习：复制、粘贴，最多再加入一些浅显的理解。而这些外显知识的背后，有一层更深入的核心知识。这层知识他人没有表达出来，我们也不知道该如何去挖掘学习。但是，如果掌握不到这些核心知识，即使我们把他人的知识背得再好、用得再熟练，也仅仅是照猫画虎，只得其形；学得多了，还有可能失去自己的主见。论语中有句话叫做：学而不思则罔。指的就是这个意思。成人学习的目的，是要借鉴别人的思想和做法，改善自己的知识体系，寻找解决问题更有效的办法。所以挖掘出他人的核心知识，并把它融入到自己的知识体系中才是我们快速进步的捷径。\u003c/p>\u003ch4>\u003c/h4>\u003ch4>\u003cstrong>【why】\u003c/strong>\u003c/h4>\u003cp>那这些更底层的核心知识我们该如何挖掘呢？通过今天要讲的“五星笔记法”，就可以从别人的做法中提取精华。\u003c/p>\u003cp>给大家讲个笑话，有个人一直想去KTV玩，可是没有钱。于是，他去KTV随便挑了一个包间，推门进去说：我是隔壁的，玩大冒险输了，惩罚就是过来唱首歌。结果就这样唱了二十几个包间，还免费喝了好多酒，还有人来搭讪。最后心满意足的说先这样吧，喝得差不多了。大家听完这个笑话，也许哈哈一笑就过去了。但是作者却使用“五星笔记法”从这个笑话中整理出一种策略：如何利用生态体系中的已有资源，寻找串联、整合价值交换的机会，借此实现自己的目的。\u003c/p>\u003ch4>\u003c/h4>\u003ch4>\u003cstrong>【how】\u003c/strong>\u003c/h4>\u003cp>大家一定很好奇作者是如何使用的吧？那么，我们跟着作者的方式来一步一步学习一下。\u003cbr>首先，在做笔记之前，先画一个五角星，每个角代表一个问题。\u003c/p>\u003cp>然后，回答这5个问题。\u003c/p>\u003cp>\u003cstrong>问题1、对方要讲的核心内容是什么？为什么这个内容值得讨论？\u003c/strong>\u003cbr>例如，上述笑话中，作者的提问就是，“这个笑话在讲什么问题？”\u003cbr>答案是：如何在没钱的情况下，免费在KTV唱歌。\u003c/p>\u003cp>\u003cstrong>问题2、对方讲解（解决问题）的逻辑是什么？\u003c/strong>\u003cbr>答：通过利用大家都熟悉的KTV游戏“大冒险”，赢得免费唱歌的机会。\u003c/p>\u003cp>\u003cstrong>问题3、这次讨论中（这个解决方案），我有什么疑问和启发？\u003c/strong>\u003cbr>答：这个方法，表面上看是利用别人的资源，实现自己的目的。实际上，创造了一种价值交换机制。因为，在KTV，人们消费的本质是购买一段快乐时光，而陌生人玩大冒险游戏来唱歌，其实是为唱KTV的人提供了新鲜的体验。本质上这个人是用时间和服务，为别人创造了欢乐时光。当然，这种策略显然也有其局限性。例如，这个人在一个包间只能唱一两首歌，否则别人会不满；这就要求他不断换包间，但这就带来更大的识破风险——很可能有某个包间的人，要这个人带其回他的包间礼尚往来。\u003c/p>\u003cp>\u003cstrong>问题4、对方的做法、想法或者给我的启发点，可以提炼为那些有效策略（思维模型）？\u003c/strong>\u003cbr>答：这个人提供了一个解决在直接资源不足时，如何实现自己目的的策略——借助产品或组织创新，利用生态环境中的已有资源发展自己。例如，优步或者爱彼迎等公司，本质上都是利用免费唱KTV的策略，通过串联各个KTV资源，实现自己的壮大。\u003c/p>\u003cp>\u003cstrong>问题5、这次讨论中给我的启发，那些可以立刻变成下一步的行动？我们如何把它们运用在自己的生活里？\u003c/strong>\u003cbr>答：我在日记本中，记录下遇到没有资源解决问题的情况时，可以考虑一种策略：如何利用生态体系中的已有资源，寻找串联、整合价值交换的机会，借此实现自己的目的。\u003c/p>\u003ch4>\u003c/h4>\u003ch4>\u003cstrong>【where】\u003c/strong>\u003c/h4>\u003cp>“五星笔记法”不仅是一个笔记法，但它也是一种我们在对知识进行梳理学习的一套方法论，无论我们在学习，还是在思考，它都能帮助我们挖掘出真正的核心知识。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】\u003c/strong>\u003c/p>\u003cp>相信大家现在对“五星笔记法”已经有所了解了，大家可以回想一下有没有经历过类似的场景：自己花了很多钱买了课程，学习后却不知道该如何应用；或者是身边有非常优秀的人，自己却学不到他的能力；诸如此类。请在小组内分享一下最近一次有这种情况是什么时候，是在学习什么技能或者跟谁学习，最终的效果是什么样的。然后，再分析一下自己没有从中收获到成长的原因是什么。请大家花8分钟的时间进行分组讨论。下面我将按照人数分成2组，大家点击“加入会议”进入分会场就可以了。\u003c/p>\u003cp>好，我刚才看到大家讨论的非常热烈，下面我将请一名小伙伴愿意分享一下自己的A1，哪位小伙伴愿意主动分享一下呢？\u003c/p>\u003cp>好的，有请xxxx。\u003c/p>\u003cblockquote>\u003cstrong>【学员分享】\u003c/strong>\u003c/blockquote>\u003cblockquote>\u003cem>我去年年底参加阿里一个讲师关于的OKR培训。 当时讲师在讲课的时候，讲解得非常全面。当时就觉得，这个东西一定非常适合我们公司用。因此，我全程做了录音、对关键词进行了记录，并且在回去之后写了100多页的内容总结。但是真正准备用的时候，却发现都是难点，自己不知道从哪里下手了。比如说，课程中说要用便签做小组内的头脑风暴，找出大家的核心使命，但是发现自己没有办法把大家推动起来做找到核心使命这件事。当时感觉自己是没有搞清楚步骤，后来经过思考发现是课程的适用范围和自己公司的有一些区别。\u003c/em>\u003c/blockquote>\u003cp>\u003cstrong>好，谢谢XXXX，给我们带来一个非常非常好的A1。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A2】\u003c/strong>\u003c/p>\u003cp>经过刚刚的A1过程，想必大家对今后的学习有很多想法，也对自己之前的学习方式有了些反思。现在大家可以想想看，如果再有一次像刚刚自己分享过的那种学习机会，你会怎么去学习？要如何运用今天的知识点，对核心知识进行深度挖掘和学习？给大家2分钟时间写下应用所学的规划，写好的小伙伴请分享到我们今天的活动群里。记住我们的A2不能仅仅是表决心，要有背景以及和技能点相关的过程，还要有结果。是具体的做法，明确的时限，要有可衡量或可观测的预期结果。\u003c/p>\u003cp>A2规划要求：\u003c/p>\u003cp>1、和自己刚刚分享的案例相关；\u003c/p>\u003cp>2、不能仅是表决心，要是具体的做法，要有明确的时限，要有可衡量或者可观测的预测结果；\u003c/p>\u003cp>3、应用到今天所学的技能点。\u003c/p>\u003cblockquote>\u003cstrong>【学员分享】\u003c/strong>\u003c/blockquote>\u003cblockquote>\u003cstrong>【背景】\u003c/strong>最近在准备师门的课程课件内容，我想把学习力内容加入到课件中，给小伙伴们分享出来。\u003c/blockquote>\u003cblockquote>\u003cstrong>【目标】\u003c/strong>我的目标是，在6月1日前，写出一份自己的学习力课件。\u003c/blockquote>\u003cblockquote>\u003cstrong>【行动步骤】\u003c/strong>\u003c/blockquote>\u003cblockquote>第一，先回顾帮主学习力课程的内容，找出适合添加到课件中的内容。\u003cbr>第二，把适合的部分认真整理，针对每一个案例，使用五星笔记法进行分析。\u003cbr>例如：帮主说的“大饼盖肉”的故事，\u003cbr>（1）大饼盖肉的故事核心内容是什么？他为什么要讲这个故事？\u003cbr>（2）这个故事的逻辑是什么？\u003cbr>如：用“旧知”附会“新知”。\u003cbr>（3）这个故事对我有什么启发？\u003cbr>（4）从这个故事中，我们能够提炼出什么策略？\u003cbr>如：从多个维度上思考和界定事物间的边界，把附会的本能反应升级为界定新知和旧知的理性反应。\u003cbr>（5）我该如何在生活中去应用？\u003cbr>如：从多个维度分析五星笔记法与RIA便签学习法的分别。\u003c/blockquote>\u003cp>\u003cstrong>我的拆书就到这里，谢谢大家！\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1589727381000,"updated_at":1590135673000,"ria":true},{"id":9670,"topic":"思维模型——培养深度思考的利器","learn_goal":"掌握思维模型的概念并学会用五星思考术积累对自己有用的思维模型","remark":"","level":"TF3-3","duration":60,"status":30,"type":0,"chaishujia":{"username":"草莓大人","city":"海口"},"club":{"name":"海口花梨分舵","city":"海口"},"prologue":"\u003cp>【片段一学习目标】通过本次的现场学习，学习者能够描述（行为）“思维模型”的定义，能从三个层次——经验、方法、原理（澄清）去追问并加深（行为）对思维模型的理解（界定）。\u003c/p>\u003cp>【片段二学习目标】通过本次的现场学习，学习者能够在日常工作和学习中，运用“五星思考法”（澄清）去积累（行为）思维模型（界定）。\u003c/p>\u003cp>\u003cstrong>[开场]\u003c/strong>大家好，我是草莓大人，是一名期货操盘手，也是一名二级拆书家，我今天要分享的主题是“思维模型”，为了便于后面的讨论，首先分一下组，从我右手边开始，每3人一组，尔康和果姐一组，一共分为4组。\u003c/p>\u003cp>\u003cstrong>[事件]\u003c/strong>好，先从一个小故事开始，我的前同事小苹果，最近升职为销售主管，本来是一件高兴的事，却给他带来不小的困扰，因为他引以为傲的销售话术经验，在带教新人的时候，不太管用，哪怕他像保姆一样手把手的教，具体到每一个场景，新人仍然成长得很慢，甚至还有2人主动辞职了，简直让他百思不得其解。\u003c/p>\u003cp>\u003cstrong>[提问]\u003c/strong>大家在平时解决问题或做某项决策的时候，你们的依据是什么，是不是主要依靠自己或他人的过往经验？比如采纳了长辈或朋友给的建议，又或者这件事情你曾经遇到过、并成功处理过，再遇到时，会沿用以前的做法。有没有想过，当这些个人的过往经验，不起作用的时候怎么办？\u003c/p>\u003cp>\u003cstrong>[影响]\u003c/strong>都说“不听老人言，吃亏在眼前”，在过去，个人经验是很有效的策略，因为面临的环境简单，但今天，外部的环境越来越复杂，你面对的问题也更具有挑战性，单纯依靠个人的有限经验，已经无法应对未来的问题，比如你的长辈如何有经验指导你玩转抖音？\u003c/p>\u003cp>\u003cstrong>[解决]\u003c/strong>这个时候怎么办？我们需要新的决策依据，比个人经验更可靠、更有效的决策依据，那是什么？是更多人的经验、是那些被人类反复验证过的各个学科原理和规律，也就是这本《好好思考》里介绍的多元思维模型，它能培养你的深度思考力，帮助你洞悉问题的本质，提高你解决问题的效率，而要想学习多元思维模型，得先从思维模型开始。\u003c/p>","ratings_count":1,"texts":[{"id":13507,"quote":"\u003cp>\u003cstrong>[过渡语]下面请大家阅读第一个片段，阅读完的小伙伴示意我一下。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>2019年5月，我在美国采访查理·芒格时专门问他:“究竟什么是思维模型，你是如何寻找思维模型的？”\u003c/p>\u003cp>芒格笑了笑，说:“其实很简单，你在解决问题时，要关注哪些做法有效、哪些无效。”\u003c/p>\u003cp>芒格的合伙人怕我没理解，补充道:“芒格先生把那些持续有效的方法总结起来，这就是思考这类问题的思维模型。”\u003c/p>\u003cp>芒格看似简单的回答，直指学习思维模型的要害——一定要深刻理解一个模型在什么情况下，解决什么问题时是有效的。\u003c/p>\u003cp>对查理·芒格而言，所有能够持续有效解决问题的策略，都可以称为思维模型。对我们而言，只有那些在遇到问题时能真正用到的策略，才是属于自己的思维模型。否则，记住了很多思维模型，却不知道能解决什么问题，就是舍本逐末。\u003c/p>","explains":"\u003cp>（互动1）大家知道查理·芒格是谁吗——巴菲特的黄金搭档，被誉为巴菲特成功背后的男人，而思维模型这个概念，被普遍认为是查理·芒格提出的，知道这两点就够了。\u003c/p>\u003cp>（互动2）我们来回看片段中的第一句话，作者问了查理·芒格两个问题，什么问题呢——什么是思维模型？如何寻找思维模型？\u003c/p>\u003cp>没错，这也是我今天要分享的主题。\u003c/p>\u003cp>\u003cstrong>[强化概念讲解]\u003c/strong>\u003c/p>\u003cp>（互动3）我们先来看第一个问题，什么是思维模型？片段中给出的答案是什么——所有能够持续有效解决问题的策略，都可以称为思维模型。\u003c/p>\u003cp>注意，这句话的两个关键词是什么——有效、策略。\u003c/p>\u003cp>策略是解决问题的方式和方法，有效就是管用，能解决问题。简言之，思维模型就是思考问题、解决问题的工具。\u003c/p>\u003cp>（互动4）举几例子\u003c/p>\u003cp>1、比如你朋友向你抱怨：“最近和伴侣关系不太好，怎么办？”你说：“不喜欢就换一个呗，反正你还年轻。”\u003c/p>\u003cp>请问，这个策略是思维模型吗？不是，至少在这个场景下它不是，因为它不能有效解决问题， 你不仅没让他们的关系变好，还将他们的关系从现任变成了前任。\u003c/p>\u003cp>2、再来，快过年了，大家都要买年货，比如买文昌鸡，如何买到相对正宗的文昌鸡呢？文昌的朋友告诉你：“跟文昌人买。”请问，这个策略是思维模型吗？当然是，虽然这是他的个人经验，但至少比你去市场上买要靠谱。\u003c/p>\u003cp>这个时候，在龙泉人家工作的朋友告诉你，可以购买龙泉人家的鸡票，不是飞机的机哈，凭鸡票可以去龙泉人家领到正宗的文昌鸡，他说这叫品牌效应。请问，这个策略是思维模型吗？当然是，这是品牌的力量，受大众认可，可能比单个人的经验更靠谱。\u003c/p>\u003cp>而如果你去请教薛兆丰教授，他可能会告诉你：“从经济学的角度来看，你要解决的问题是，如何消除信息不对称……”请问，这个策略是思维模型吗？当然是，而且是从经济学的学科原理出发，思考层次更深刻。\u003c/p>\u003cp>大家发现没，同样是买文昌鸡，思维模型不止一种，而且还有不同的层次之分，这种层次之分不是说谁好谁差，而是体现了思考的不同深度。\u003c/p>\u003cp>\u003cstrong>[WHY]\u003c/strong>所以我们常常会发现，对于同一件事情的看法，高手的见解通常比大多数人更高级、更全面、更底层，因为他的思维模型的层次更丰富、更深刻。同样的，我们要想培养深度思考力，找到更好的决策依据，就要在不同的层次阶梯上，去理解思维模型，从表面深挖到背后的原理。\u003c/p>\u003cp>\u003cstrong>[HOW]\u003c/strong>具体怎么做呢？根据前面买文昌鸡的例子，我们可以得到启发，思维模型有三个层次，所以我把这个方法叫\u003cstrong>“挖地三层法”\u003c/strong>：\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1、经验技巧层\u003c/strong>\u003c/p>\u003cp>这一层次的思维模型往往来自个人有限的经验总结，一般用于解决某一个具体的问题，比如文昌朋友给出的“跟文昌人买”的思维模型。\u003c/p>\u003cp>\u003cstrong>2、方法流程层\u003c/strong>\u003c/p>\u003cp>这一层次则是把上一层的诸多经验技巧进行归纳，提炼成一般方法流程，所以能解决同一类问题，比如龙泉人家的朋友给出的“品牌效应”思维模型，比如四象限法则、金字塔原理的总分总结构等等。\u003c/p>\u003cp>\u003cstrong>3、学科原理层\u003c/strong>\u003c/p>\u003cp>这一层次则是经过科学方法验证的规律和原理，比如“信息不对称理论”的思维模型，同样的还有心理学、社会学、数学物理等各个学科原理，当我们把思维模型追溯到学科原理的时候，这个思维模型的可靠性、准确性就会大幅提高。\u003c/p>\u003cp>\u003cstrong>[适用边界]\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>“挖地三层法”适用于很多领域，比如用于对心智的认知、阅读过程中的深度思考、知识的获取与加工、对问题本质的挖掘等等，而这三个层次，也各有不同的适用边界，掌握第一或第二层的思维模型，有助于解决日常工作中的具体问题。第三层则通常用来把控宏观大局。浅层次的思维模型解决不了问题的时候，在深层次中，或许就能找到有效的策略。\u003c/p>\u003cp>\u003cstrong>[反例变正例]\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>比如我前面说小苹果的故事，大家觉得小苹果的销售话术是属于哪一个层次的思维模型，是经验技巧型（互动5），是属于他个人经验的总结，同样的话术，用在他身上是管用的，用在别人身上就不一定了。\u003c/p>\u003cp>这个时候怎么办，根据挖地三尺法，他需要往更底层的层次去深挖，为什么他的销售话术之所以管用，可能不是因为他的话术内容，而是正好符合某一种沟通方法，比如他掌握了优质提问的方法，这是方法流程的层次。\u003c/p>\u003cp>再深挖，是不是他的优质提问法，恰好遵循管理学中的马斯洛需求层次理论，恰好满足了客户的安全需求、感情需求或是尊重需求，这是学科原理的层次。\u003c/p>\u003cp>经过挖地三层法后，我们得出结论，与其直接传授新人具体的话术内容，不如教他们如何提出优质的提问，如何寻找和满足客户的需求。\u003c/p>\u003cp>（互动6）\u003c/p>\u003cp>好，讲到这里，我们回顾一下，什么是思维模型——解决问题的有效策略，思维模型有哪几个层次——经验流程、方法流程、学科原理。\u003c/p>","interaction":"\u003cp>\u003cstrong>[A2：催化应用]编写小剧本\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：心动不如行动，刚\u003c/strong>\u003cstrong>才我列举的那些例子，大家应该都会遇到过，请大家花\u003c/strong>\u003cstrong>1\u003c/strong>\u003cstrong>分钟的时间想想，你会在什么场景中用到“挖地三层法”，在运用这个方法的时候，会和谁发生哪些对话，把它编成一个小剧本，将关键词\u003c/strong>\u003cstrong>写在学员用表中，稍后请一组小伙伴来进行分享。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>阿拉丁：\u003c/p>\u003cp>\u003cstrong>[时间]\u003c/strong>期末考试结束后\u003c/p>\u003cp>\u003cstrong>[地点]\u003c/strong>家里\u003c/p>\u003cp>\u003cstrong>[人物]\u003c/strong>我和学生家长\u003c/p>\u003cp>\u003cstrong>[事件]\u003c/strong>学生期末考砸了，学生家长来请教方法\u003c/p>\u003cp>\u003cstrong>[对话]\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学生家长：\u003c/strong>哎呀林老师，我家孩子又考砸啦，平时他在家里学习，每次遇到不会的题就放弃，做一道数学题要做半天，看似坐在桌子前认真学习，其实桌子底下拼命玩他的小手，把时间都浪费掉了，还以为我不知道。\u003c/p>\u003cp>\u003cstrong>阿拉丁：\u003c/strong>我把我的经验分享给你，以后你孩子学习的时候，你可以定个用番茄钟，每次25分钟，就让他用这25分钟来学习，然后休息5分钟，你还可以培养他冥想的习惯，在休息的5分钟内用来冥想，那么他在接下来的25分钟内，可以更加有效率地学习。（经验技巧层）\u003c/p>\u003cp>\u003cstrong>学生家长：\u003c/strong>你这个经验虽然不错，但是我家孩子不一定搞得定啊，我让他做10分钟，他都不一定坚持得下去。\u003c/p>\u003cp>\u003cstrong>阿拉丁：\u003c/strong>也对，我的经验不一定适合他，那这样，我推荐几个方法，比如找我一对一补课；还有一个方法，就是写错题本，其实学数学就是把不会的变成会的，那么错题本应该怎么写呢，先写错的题，其次写错的原因，再写正确解答，最后写自己的反思总结，他只要坚持这4步方法，数学就一定能学好。（方法流程层）\u003c/p>\u003cp>\u003cstrong>学生家长：\u003c/strong>那如果这些方法还不管用怎么办？\u003c/p>\u003cp>\u003cstrong>阿拉丁：\u003c/strong>那我就给你说一个高级的，从认知科学的原理来看，要想增加孩子的学习认知，有两个重要的点，一是把学到的知识进行编码，二是把信息提取出来，编码就是记忆，提取就是从记忆库里提取知识和信息，只要你提取顺利，做题就会轻松，所以你要想孩子学习好，就要做好这两件事，让他编码顺畅、提取顺畅，至于要怎么做到这两件事，方法有很多，比如提高记忆技巧、提高信息摄取能力、提高他对信息进行精细化解读的能力等等，再具体一点的话，就是要多做难题，增加提取信息的难度训练，有助于他今后顺畅地做题。（学科原理层）\u003c/p>\u003cp>\u003cstrong>学生家长：\u003c/strong>虽然听不太明白，但是很厉害很专业的感觉，回头我研究后去试试。\u003c/p>\u003cp>\u003cstrong>[拆书家反馈]：\u003c/strong>谢谢阿拉丁的精彩分享，清晰地体现了“挖地三层法”的运用，大家发现没，阿拉丁的分享中，从他的经验，比如使用番茄钟、冥想，到他教学中总结的“错题本”方法流程，再到“编码和提取”的认知科学原理，最后又回到方法流程层、经验技巧层，从而形成了一个循环，我听了都很受启发，再次感谢阿拉丁。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":13508,"quote":"\u003cp>\u003cstrong>[A1请大家自测]\u003c/strong>\u003c/p>\u003cp>第一个拆页我们学习了思维模型的概念、层次和重要性，一个人要想解决各种问题，就要掌握足够多的思维模型，那么我们如何在工作和学习中，去积累对我们有用的思维模型呢？下面就教大家一个笔记法，先来做一份自测题，共有5道题目，大家按1-6分给自己打分，1代表完全不符合，6代表完全符合，最后计算出总得分。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>1、阅读一本书之前，我会预判这本书要讲的核心内容是什么。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2、我做笔记的时候，会记录对方的讲解逻辑。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3、与别人进行讨论时，我会记录下我受到的启发。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4、在解决问题时，我会去追问解决策略背后的原理。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5、我获得启发后，不会停留在想法中，而是付诸行动。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>\u003cstrong>\u003cbr>\u003c/strong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cstrong>[I解释自测题]\u003c/strong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>5-10分的有没有？这个分数段的小伙伴基本属于听过就算、看过就忘的类型。\u003c/p>\u003cp>11-20分的有没有？这个分数段的小伙伴偶尔会做些记录，会有一些思考，但都流于表面。\u003c/p>\u003cp>21-30分的有没有？看来你平时有记录重要信息的习惯，但可能对信息背后更深层次原理的思考还不够深入。\u003c/p>\u003cp>这份自测题只是为了引发大家过去记笔记的经历，而我下面要介绍的记录方法，会给大家新的思路。\u003c/p>\u003cp>\u003cstrong>[过渡语]下面请大家阅读片段二，阅读完的小伙伴给我一个信号。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>[原文片段]\u003c/strong>\u003c/p>\u003cp>人们在工作中的每一次谈话、每一个决定里都包含着经验和智慧，但是要获得这些智慧，还需要我们去挖掘。\u003c/p>\u003cp>猎豹创始人傅盛曾在一篇文章中提到，在公司做会议纪要对他的快速成长帮助很大。\u003c/p>\u003cp>当年，傅盛在周鸿祎的3721公司工作时，第一次跟着周鸿祎开会就被安排去做会议纪要。那天，周总讲了两个多小时。要知道，周鸿祎是个思维非常跳跃的人，开会时，他的话题经常跳来跳去，他这个会议纪要做得很不容易。\u003c/p>\u003cp>结果，当天傅盛整理会议纪要忙到凌晨三点钟。之所以花了这么长时间，不仅是因为会议内容分散，而且是因为傅盛没有像别人一样简单地罗列领导开会时讲的内容，而是对着看似很散的会议纪要思考：周总为什么要说这句话？他为什么又从这个话题跳转到新话题，这个背后的逻辑是什么？他真正想表达的是什么？……在这种反复推敲和打磨的过程中，傅盛逐步梳理出了周鸿没有直接说出来的逻辑。\u003c/p>\u003cp>与此同时，为了方便大家阅读，傅盛又把会议纪要的内容要点提纲挈领地整理出来，在关键地方标黑，在要点底下又列出次级要点，这就让人在看会议纪要时一目了然。做完了这些还不够，他又把会议纪要提炼成一份邮件正文摘要，这样别人收到会议纪要邮件时，不用下载附件也可以知道这个会议讲了什么。\u003c/p>\u003cp>周鸿看到傅盛做的会议纪要后，十分赞赏，当即就安排以后的会议纪要让傅盛承包。几年后，奇虎内部有人认为，在公司里能和周鸿祎进行思维对话的只有两个人，其中一个就是傅盛。\u003c/p>\u003cp>这次做会议纪要的经历让傅盛记忆深刻，后来他总结道：写会议纪要这件事不仅是为上级服务，而且重要的是，在这个过程中，整理、提炼、反思、深入思考别人思考和决策的方式，这本身就是一种学习。\u003c/p>","explains":"\u003cp>\u003cstrong>[what]\u003c/strong>看完这个片段，大家对会议纪要是不是有了新的看法？没想到会议纪要还能这么玩，对吧？\u003c/p>\u003cp>会议纪要也是笔记的一种，刚才那份自测题，想必也让大家想起了一些自己过去做笔记的经历：在重要的句子下面划线，把重要的关键词记下来，或者做上各种记号，有时还会用不同颜色的笔来标注……这些经历大家都有过吧。\u003c/p>\u003cp>\u003cstrong>[why]\u003c/strong>可能有人会问，做笔记跟我们积累思维模型有什么关系呢？\u003c/p>\u003cp>我们过去做笔记的目的是为了加强记忆，除此之外，好像也没什么特别的用处了。然而这个片段告诉我们这是一个误区，做笔记不是为了记录别人的观点和想法，而是要寻找更有效的解决问题的策略，也就是思维模型。\u003c/p>\u003cp>但除了那些人类已经总结出来的现成的思维模型以外，其他思维模型通常是隐形的、看不见的，所谓“只可意会不可言传”，也就是片段中的第一句话：“人们在工作中的每一次谈话、每一个决定里都包含着经验和智慧，但是要获得这些智慧，还需要我们去挖掘。”\u003c/p>\u003cp>那我们如何挖掘这些隐形的知识，变成我们的思维模型呢？\u003c/p>\u003cp>\u003cstrong>[how]\u003c/strong>这就需要用到下面的五星思考法，它是从会议纪要等做笔记的方法中引申、提炼出来的，共有五个步骤：\u003c/p>\u003cp>\u003cstrong>1、预判内容\u003c/strong>\u003c/p>\u003cp>预判对方要讲的核心内容是什么？我们在阅读一本书，或是参加会议、培训之前，通常是会提前知道他们的主题是什么，这个时候可以想想，如果换作是你，你会怎么讲解这个主题？这样一来，当别人讲解的时候，你就很容易比较你们之间的思路差别。\u003c/p>\u003cp>这里我顺带提一下，大家也可以运用前面的“挖地三层法”，来思考这一步“预判内容”对应的是哪个学科原理呢，比如它可能利用了心理学中的好奇心，它个体学习的内在动机之一，预判内容使人产生好奇心，好奇心又会驱使人们去探索，从而提升学习效率，大家如果有兴趣的话，下面的每一步都可以用“挖地三层法”去深入思考。\u003c/p>\u003cp>\u003cstrong>2、关注逻辑\u003c/strong>\u003c/p>\u003cp>记录对方讲解的逻辑是什么？就像片段中的傅盛，他会关注周总为什么要说这句话？为什么从A到B，背后的逻辑是什么？就这样反复推敲和打磨，逐步梳理出周总没有直接说出来的逻辑。\u003c/p>\u003cp>\u003cstrong>3、记录启发\u003c/strong>\u003c/p>\u003cp>对方的观点给了我哪些启发，或我有哪些疑问？\u003c/p>\u003cp>\u003cstrong>4、提炼模型\u003c/strong>\u003c/p>\u003cp>顺着启发点继续问，对方的想法或做法，或者说给我的启发点，能用来解决什么问题？\u003c/p>\u003cp>\u003cstrong>5、采取行动\u003c/strong>\u003c/p>\u003cp>如何把这些解决问题的策略运用到自己生活中？光说不练假把式。\u003c/p>\u003cp>五星思考法的原理是，把别人的知识进行二次深加工，把自己的收获和启发与自己的经历（A1），还有接下来的行动（A2）相联系，才能真正从别人的做法中提取精华，这一点，与拆书帮的RIA学习法不谋而合。\u003c/p>\u003cp>\u003cstrong>[适用边界]\u003c/strong>\u003c/p>\u003cp>这个思考法适用很多场景，比如阅读、会议、演讲、培训、讨论会等等，生活中处处都有值得我们学习的隐性知识，只要用心去挖掘，就能获得启发。\u003c/p>\u003cp>\u003cstrong>[预防异议]\u003c/strong>\u003c/p>\u003cp>可能大家会有疑问，这个五星思考法太耗费时间了，而且世界上有那么多现成的思维模型，我把它们掌握了不就可以了，干嘛要这么麻烦？首先，能解决自己问题的思维模型才是有用的，别人的思维模型不一定适合你，哪怕是现成的思维模型，可能也需要结合自己的实际情况进行调整；其次，如果我们学习是为了培养深度思考力，提升决策判断力，那么花时间去构建属于自己的知识体系，从长远来看，是非常划算且必要的事情。\u003c/p>\u003cp>\u003cstrong>[举例]\u003c/strong>下面用一个例子，来看看五星思考法的具体运用，比如大家今晚来听我的分享，就可以用这个五星思考法。\u003c/p>\u003col>\u003cli>\u003cp>\u003cstrong>预判内容\u003c/strong>，大家应该都看了我们发布的招募帖，上面写着我要分享的主题是：思维模型——培养深度思考力的利器，那么大家就可以先预判我要讲的核心内容是什么，如果换作是你，你会如何诠释这个主题？\u003c/p>\u003c/li>\u003cli>\u003cp>\u003cstrong>关注逻辑\u003c/strong>，我是按照什么逻辑顺序进行讲解的，首先是从一个小苹果的故事开始，引发大家的兴趣和思考，接着引出思维模型的概念，并通过几个例子对比让大家加深理解，还告诉大家为什么要学习思维模型，最后给出具体的做法等等……把这些逻辑关系记录下来，就会发现我的思考过程。\u003c/p>\u003c/li>\u003cli>\u003cp>\u003cstrong>记录启发\u003c/strong>，正如傅盛做会议纪要时，会不断地反思、深入思考别人思考和决策的方式，并与自己的经历相对照。那么大家在听我讲述的过程中，有什么疑问或者启发，都可以写下来，后面可以自己加以分析，或是和我进行交流。\u003c/p>\u003c/li>\u003cli>\u003cp>\u003cstrong>提炼模型\u003c/strong>，在我今天的分享中，你觉得哪些内容是可以用来解决某些问题的，比如这五星思考法，就是一个很好的提炼他人思维方式的工具。\u003c/p>\u003c/li>\u003cli>\u003cp>\u003cstrong>采取行动\u003c/strong>，心动不如行动，明天就把这五星思考法用起来\u003cstrong>。\u003c/strong>\u003c/p>\u003c/li>\u003c/ol>","interaction":"\u003cp>\u003cstrong>[A3微行动]\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>[1、明确问题]\u003c/strong>\u003c/p>\u003cp>\u003cstrong>[拆书家提问]\u003c/strong>讲完了五星思考法后，我来问大家一个问题，大家觉得这五步里面，有没有哪一步是我讲得不够清晰的？或者你们觉得有疑问的地方？\u003c/p>\u003cp>\u003cstrong>[学习者回答]\u003c/strong>提炼模型。\u003c/p>\u003cp>\u003cstrong>[拆书家提问]\u003c/strong>提炼模型，还有吗？或者说，结合你们的经验，你们觉得哪一步是最难的？\u003c/p>\u003cp>\u003cstrong>[学习者回答]\u003c/strong>还有关注逻辑，很多人不会关注逻辑，他只会看表象。\u003c/p>\u003cp>\u003cstrong>[拆书家回应及提问]\u003c/strong>有说提炼模型难的，也有说关注逻辑难的，那我们就来做个投票，觉得关注逻辑难的小伙伴举个手，有6个，那么觉得提炼模型难的小伙伴举个手，也是6、7个，这两个投票结果都差不多。既然如此，那我们再聚焦一下，如果二选一，你们觉得哪一个更具有讨论的价值？\u003cbr>[\u003cstrong>学习者回答]\u003c/strong>如果从步骤顺序来看的话，肯定是选关注逻辑，如果这一步都卡住了，那后面就没法进行下去了。\u003c/p>\u003cp>\u003cstrong>[拆书家回应]\u003c/strong>好的，那我们就明确这个问题，就是先来解决“关注逻辑难”这个问题，可能把这一步解决了之后，后面的提炼模型就变得简单了呢。\u003c/p>\u003cp>\u003cstrong>[2、引导分组讨论问题本质]\u003c/strong>\u003c/p>\u003cp>\u003cstrong>[拆书家提问]\u003c/strong>好，下面请大家在小组里面进行讨论，大家之所以觉得关注逻辑难，是因为什么？找到最本质的原因，并把它写下来。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>[讨论后，拆书家提问]\u003c/strong>好，大家的讨论非常热烈，我问一下，大家还记得我们要讨论的问题是什么吗？\u003c/p>\u003cp>\u003cstrong>[学习者回答]\u003c/strong>为什么“关注逻辑”这么难？\u003c/p>\u003cp>\u003cstrong>[拆书家提问]\u003c/strong>那经过刚才的讨论后，各个小组找到这个问题的本质原因了吗？\u003c/p>\u003cp>\u003cstrong>[尔康组回答]\u003c/strong>我们总结的原因有两个，一个是意识，一个是能力，意识是指我们本身就没有这种逻辑意识，遇到问题通常只会关注细节，没有从大的框架去思考，而正是因为缺乏这种逻辑意识，所以导致平时很少去关注别人的逻辑，进而导致缺乏总结提炼的能力。\u003c/p>\u003cp>\u003cstrong>[拆书家提问]\u003c/strong>很好，那其他组讨论的结果呢？\u003c/p>\u003cp>\u003cstrong>[阿拉丁组]\u003c/strong>我们组讨论的结果是缺乏逻辑思维，从小到大，我们的教育就没有“逻辑思维”这一门课程，我们都是后来去自学的，\u003c/p>\u003cp>\u003cstrong>[3、明确问题本质]\u003c/strong>\u003c/p>\u003cp>\u003cstrong>[拆书家提问]\u003c/strong>综合各小组的讨论结果，“关注逻辑为什么这么难”的本质原因是缺乏逻辑思维能力，这个原因大家认可吗？\u003c/p>\u003cp>\u003cstrong>[学习者回答]\u003c/strong>认可，同意。\u003c/p>\u003cp>\u003cstrong>[4、引导分组讨论解决方案]\u003c/strong>\u003c/p>\u003cp>\u003cstrong>[拆书家引导]\u003c/strong>既然明确了这个问题的本质，是因为缺乏逻辑思维能力，那下一步，我们就来讨论如何解决“缺乏逻辑思维能力”这个问题，或者说“增强逻辑思维能力的途径有哪些？”还是以小组讨论的形式，找到解决方案。\u003c/p>\u003cp>\u003cstrong>[5、派代表讲解成果]\u003c/strong>\u003c/p>\u003cp>\u003cstrong>[拆书家]\u003c/strong>我看大家都讨论得差不多了，下面有请一组小伙伴的代表来分享一下他们得出的解决方案。\u003c/p>\u003cp>\u003cstrong>[阿拉丁组分享]\u003c/strong>我们小组讨论的解决方案一共有4个步骤：\u003c/p>\u003cp>1、首先要做的是固化表达逻辑，用什么方法来固化表达逻辑呢，有两种方式，通过写作和多说，先去行动，然后得到反馈，具体怎么做呢，可以去看一些《学会写作》之类的书，很多教写作的老师都会推荐类似的书，比如《写作是最好的自我投资》、《爆款写作课》、《爆款文案》，先学会写作，将表达逻辑固化下来。\u003c/p>\u003cp>2、然后再将表达上升到金字塔原理，因为金字塔原理是结构化思维的鼻祖，当你的表达具备了结构化思维以后，你就能从别人的文章或表述中，看到他们的表达框架，比如我刚才听了林果的分享，我就能知道她的what/why/how，很清晰，而我原来是没有这种思维方式的。\u003c/p>\u003cp>3、接下来是规避逻辑谬误，你要去看一些这方面的书，比如《好好讲道理》，据不完全统计，全世界有360多种逻辑谬误，常见的有60多种，要想全部搞清楚不太可能，但是如果你有了前面一步的结构化思维，你就能将它们很好地按框架进行归类。\u003c/p>\u003cp>4、这个时候，你才可以真正意义上地去学习逻辑学，逻辑学归类下来其实包括演绎推理和归纳推理，它们都针对非形式逻辑的一些内容，比如三段论，只有正儿八经地学了逻辑学后，你才真正知道逻辑是什么。\u003c/p>\u003cp>综上，按照这样的套路，就可以把我们的逻辑思维培养起来了。\u003c/p>\u003cp>\u003cstrong>[拆书家反馈]\u003c/strong>大家听完了阿拉丁的分享之后，有什么感想吗？是不是觉得，高级？我们来看一下阿拉丁是怎么讲的，他首先讲固化逻辑，怎么固化？通过写作，怎么写作？看书，看什么书？《学会写作》等等，从这里可以看出他的表达逻辑，他的第二步是金字塔原理，这就上升到了原理层了，而他的第三层是规避逻辑谬误，我们要学习正确的逻辑，那么很重要的一件事情是你要知道错误的逻辑长什么样儿，对吧，而他的第四步是系统地学习逻辑学，反正我听完以后，脑海中就浮现两个字——高级。\u003c/p>\u003cp>好，刚才我注意到尔康在组内的分享也特别精彩，有请尔康给我们做一个简单的分享。\u003c/p>\u003cp>\u003cstrong>[尔康组分享]\u003c/strong>我们组总结得没那么高级哈，我就简单地分享一下，我们的解决方案主要有两点，学与练，通过学跟练去提升我们的逻辑思维能力，学什么呢？有两个部分，第一是关于逻辑的主题阅读，第二是看推理小说，这是我们的小伙伴分享的，这是关于学的层面。那练什么呢？也是分两部分，第一是练工具，比如用思维导图，你在用思维导图的过程中，其实也就是在训练你分类、归类的能力。第二是表达的时候，刻意练习1、2、3，这个方法是我自己的一个经历，是我过去的老板通过123的方式，把我的逻辑能力给培养了出来，只要你在进行汇报或其他表达输出的时候，刻意使用1、2、3的方式去表达，就会逐步提升自己的逻辑思维能力。\u003c/p>\u003cp>\u003cstrong>[拆书家回应及提问]\u003c/strong>很精彩，我觉得尔康的分享特别接地气，学嘛练嘛，如果归结到我们的思维模型层次，大家觉得尔康的学跟练，是属于哪一个层次的思维模型？\u003c/p>\u003cp>\u003cstrong>[学习者回答]\u003c/strong>第二层，方法流程层。\u003c/p>\u003cp>\u003cstrong>[拆书家反馈]\u003c/strong>说得对，学与练是方法流程，它可以解决同一类问题，而不仅局限与某一个具体问题。而阿拉丁和尔康的分享加起来，其实已经涵盖了思维模型的三个层次，经验技巧层、方法流程层、学科原理，都非常经常。\u003c/p>\u003cp>\u003cstrong>[拆书家提问]\u003c/strong>至于另外一个大家觉得难的步骤“提炼模型”，大家觉得如果按照阿拉丁和尔康的分享，去进行练习和提高自己的逻辑思维能力，后面的“提炼模型”会不会就变得水到渠成了，没那么难了？\u003c/p>\u003cp>\u003cstrong>[学习者回答]\u003c/strong>是的。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>[结语/互动]\u003c/strong>最后我们再来回顾一下今天的内容，思维模型的概念是什么？\u003c/p>\u003cp>\u003cstrong>[学习者回答]\u003c/strong>解决问题的有效策略。\u003c/p>\u003cp>[拆书家提\u003cstrong>问]\u003c/strong>它有哪几个层次？\u003c/p>\u003cp>\u003cstrong>[学习者回答]\u003c/strong>经验技巧层、方法流程层、学科原理层。\u003c/p>\u003cp>[拆书家提\u003cstrong>问]\u003c/strong>五星思考法的步骤有哪些？\u003c/p>\u003cp>\u003cstrong>[学习者回答]\u003c/strong>预判内容、关注逻辑、记录启发、提炼模型、采取行动。\u003c/p>\u003cp>[拆书家\u003cstrong>]\u003c/strong>好，我的分享到此结束，谢谢大家的聆听！\u003c/p>\u003cp>\u003cstrong>[A2催化应用]\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cstrong>拆书家提问设计：\u003c/strong>\u003cstrong>给大家布置一个小作业，未来一到两周内，在你将遇到的诸如会议、阅读、培训的场景中，尝试运用五星笔记法做笔记，并将你们的笔记情况跟我分享一下。\u003c/strong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cstrong>\u003cbr>\u003c/strong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>[\u003c/strong>\u003cstrong>学习者案例记录\u003c/strong>\u003cstrong>]\u003c/strong>\u003c/p>\u003cp>\u003cstrong>王婷分享：\u003c/strong>\u003c/p>\u003cp>[目标]今晚应用五星思考法阅读《贫穷的本质》第三章“提高全球居民健康水平容易吗？”\u003c/p>\u003cp>[步骤]\u003c/p>\u003cp>\u003cstrong>1、预判内容\u003c/strong>\u003c/p>\u003cp>根据本书的目录、推荐语言、前言、第一第二章节的核心内容及本章节的主题，预判本章主要是从居民健康和贫穷之间的关系，来分析贫穷的本质问题，比如我们普通老百姓会经常说“病不起，一病回到解放前；现在不养生，将来养医生”等类似的话。\u003c/p>\u003cp>\u003cstrong>2、关注逻辑\u003c/strong>\u003c/p>\u003cp>记录对方讲解的逻辑是什么?\u003c/p>\u003cp>第一，首先是举例（非洲每年因痢疾导致5岁以下的儿童数量高达七百多万），说明发病的原因，以及简单有效但又没有普及的、便宜的预防和治疗手段，如通过水源的净化消毒和糖加盐口服液，反而滥用抗生素。\u003c/p>\u003cp>第二，通过实地调查及实际统计数据，得出因为疾病导致儿童不能正常上学、工人无法正常工作、孕妇可能生下不健康的婴儿，然后导致恶性循环，穷人家庭为了健康问题支付的费用越来越高，其他方面的支付更少，因为健康问题劳动能力也下降了，收入也更低了。\u003c/p>\u003cp>第三，通过实地调查，对采取预防措施和没有预防措施的地区进行对比，得出发病率和死亡率的差距。并引用了一个实例（在格莱姆维卡斯负责的一个村子里每个家庭安装自来水管道，这个村子的居民能够饮用到消过毒的自来水。并收集了去卫生所治疗疟疾或痢疾得人的信息，几乎一夜间痢疾重症病例就减少了一半，疟疾病例也减少了三分之一，每个家庭为此支付的费用也很低，每月仅为4美元。）\u003c/p>\u003cp>第四，还是通过实际数据对比，穷人在对待能够起到预防作的物品购买所付出的费用金额，越是接近零，需求量越高。反而在日常保健方面和私人医院治疗方面花费的费用更多。事实上大多数的私立医院并不具备行医资质，这点跟我们国家类似。还有我们国家的老百姓在昂贵无效的保健品上面花很多的钱。\u003c/p>\u003cp>第五，通过对采取疾病预防措施的孩子和没有采取任何预防措施的孩子成年后的收入数据进行对比，前者因为健康原因创造的收入也比后者高。\u003c/p>\u003cp>作者通过大量实际数据对比得出：预防是最有效的措施，而且也是最经济实惠的，比如：纯净水、蚊帐、抗蠕虫药片、儿童疫苗、加入水中的消毒剂、糖盐口服液等。为什么这些廉价的预防措施没有普及呢？\u003c/p>\u003cp>原因之一，政府：政府保健服务者的高缺席率和动力的缺乏。通过实例说明。\u003c/p>\u003cp>原因之二，认知水平。穷--上学少-地域落后-信息闭塞-健康知识和保健知识的匮乏。事实上，我们身边接受过高等教育的人群，他们的认知水平又能高到哪去呢？比如谣言的传播、“杀猪盘”、屡禁不止传销诈骗等。\u003c/p>\u003cp>措施：宣传、普及、教育、推广（实例效果）\u003c/p>\u003cp>以上，作者都是通过实地走访调查贫穷人群最集中的18个国家和地区，从穷人的日常生活，探寻到的真实画面和真实数据对比。这跟我们在电视上看到的，那些巴拉巴拉拍脑袋、满嘴跑火车的所谓经济学家本质的区别。\u003c/p>\u003cp>\u003cstrong>3\u003c/strong>\u003cstrong>、\u003c/strong>\u003cstrong>记录启\u003c/strong>\u003cstrong>发\u003c/strong>\u003c/p>\u003cp>我们国家在预防普通老百姓因病致贫方面做得很好。比如全民基本医疗保险制度、大病医疗补贴、2019年年底海南省政府出台的针对缴纳农村合作医疗和城镇医疗的居民的大病保险，每年仅仅需要几十元就享有40万的大病保险。\u003c/p>\u003cp>\u003cstrong>4、提炼模型\u003c/strong>\u003c/p>\u003cp>顺着启发点继续问，对方的想法或做法，或者说给我的启发点，能用来解决什么问题?\u003c/p>\u003cp>风平浪静时的危机意识和未雨绸缪的事前预防措施。\u003c/p>\u003cp>\u003cstrong>5、采取行动\u003c/strong>\u003c/p>\u003cp>如何把这些解决问题的策略运用到自己生活中?\u003c/p>\u003cp>适量的运动➕健康的饮食➕良好的生活习惯等养生措施，降低生病的概率；乘年轻尽可能多的储备养老金；力所能及的配置一些商业保险；台风前储备食品和水；家庭预备基本灭火器材等等。\u003c/p>\u003cp>\u003cstrong>佩璇分享：\u003c/strong>\u003c/p>\u003cp>2020年1月18日\u003c/p>\u003cp>我用五星思考法看《写作是最好的自我投资》中“不愿动笔”的三种心理片段。\u003c/p>\u003cp>\u003cstrong>1、预判内容\u003c/strong>\u003c/p>\u003cp>作者会列出大部分人想写作却迟迟未开始的三种心理原因。\u003c/p>\u003cp>我猜有可能会有完美主义倾向，因为我就是这种，从2019年年初说好的写作，到2019年结束好像总共也就只写了1篇投稿到总舵，还是因为抢书被逼无奈只能写。这次又给自己2020年定个目标，每月至少一篇文章，希望能边读这本书，边把第一月的任务完成了。\u003c/p>\u003cp>\u003cstrong>2、关注逻辑\u003c/strong>\u003c/p>\u003cp>作者写这个部分是给那些想动笔写作却迟迟没动笔写作的人看的，那这些人为什么会这样做呢？\u003c/p>\u003cp>作者不止是说完美主义要求的原因，这样一个就概括了，而是把这个完美主义要求更具象化了，比如觉得自己写的对别人没价值，这是对别人眼中的自己要求完美；觉得自己写的很幼稚，这是对自己每个踩过的过去要求完美；心里住着完美审判小人，这是对自己现在每一个小输出要求完美。\u003c/p>\u003cp>让读者更能找到共鸣，并在每个原因中举了很多实例，让读者能感同身受，最后给出方法。\u003c/p>\u003cp>\u003cstrong>3、记录启发\u003c/strong>\u003c/p>\u003cp>这三个心理状态我都有，作者是先让读者有这个意识，当他们出现这样的状态时，能知道自己是处于什么原因状态而没有开始写作，并意识到每个人都会有，接下来及时调整，迈出写作行动的第一步。书中后面章节又有讲如何持续写作和保持高质量写作的方法。\u003c/p>\u003cp>\u003cstrong>4、提炼模型\u003c/strong>\u003c/p>\u003cp>作者找到为什么很多人迟迟不愿写作的原因，并不是讲高大上的心理学原因，只是从源于他人、源于对自己过去、和源于对自己会有的心理这三个维度，越接近大众心理、越接地气，更容易让读者产生共鸣，并愿意去改变。\u003c/p>\u003cp>\u003cstrong>5、采取行动\u003c/strong>\u003c/p>\u003cp>我可以去分析下为什么很多家长知道阅读很重要，却不能坚持每天给孩子读书的原因。\u003c/p>\u003cp>先自己思考出一些原因、再从周边调查出一些原因，最后再删减，提炼出从3-4个维度出发的最主要原因。放在本月要完成的“亲子阅读入门的微课中”。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1579323722000,"updated_at":1579329231000,"ria":true}]};